window.tplRenderUniversalBgLayer = function (data, fallbackBgStyle) {
  const d = data || {};
  const preset = d.bgPreset || 'default';
  const bgUrl = d.bgMediaUrl || '';
  const isVideo = d.bgMediaType === 'video' || (bgUrl && /\.(mp4|webm|mov)(\?|$)/i.test(bgUrl));
  if (bgUrl) {
    if (isVideo) {
      return `<div class="tpl-universal-bg-layer"><video class="tpl-universal-bg-video" src="${bgUrl}" autoplay loop muted playsinline></video></div>`;
    }
    return `<div class="tpl-universal-bg-layer" style="background: url('${bgUrl}') center/cover no-repeat;"></div>`;
  }
  if (preset && preset !== 'default') {
    return `<div class="tpl-universal-bg-layer bg-preset-${preset}"></div>`;
  }
  if (fallbackBgStyle) {
    return `<div class="tpl-universal-bg-layer" style="${fallbackBgStyle}"></div>`;
  }
  return `<div class="tpl-universal-bg-layer"></div>`;
};

