          const tx = -50 - netLeft * 136;
          const ty = -50 + (1 - riseP) * 180 - moveUpOutP * 220;
          const op = Math.max(0, Math.min(1, (c < 0.20 ? 0 : riseP * 1.3) * (1 - moveUpOutP * 1.1)));
