          wavy1El.style.transform = `translateX(${((1 - l1P) * 16).toFixed(1)}px)`;
          wavy2El.style.transform = `translateY(${((1 - l2P) * 18 + Math.sin(l2P * Math.PI) * -4).toFixed(1)}px)`;
