      if (sheet) sheet.style.transform = `scale(${zoom.toFixed(2)}) translate(${panX.toFixed(1)}px, ${panY.toFixed(1)}px)`;
      if (m1) m1.style.width = `${mark1Prog}%`;
      if (m2) m2.style.width = `${mark2Prog}%`;
