function syncTopTemplateTypographyUI() {
  const target = topCustomizerState.activeTextTarget || 'main';
  const styleObj = target === 'main' ? topCustomizerState.mainStyle : topCustomizerState.subStyle;

  // 1. Update target tab buttons visual state
  const tabMain = document.getElementById('tpl-modal-tab-target-main');
  const tabSub = document.getElementById('tpl-modal-tab-target-sub');
  const targetLabel = document.getElementById('tpl-modal-active-target-label');

  if (tabMain && tabSub) {
    if (target === 'main') {
      tabMain.style.background = 'rgba(168,85,247,0.25)';
      tabMain.style.borderColor = 'rgba(168,85,247,0.5)';
      tabMain.style.color = '#fff';
      tabSub.style.background = 'transparent';
      tabSub.style.borderColor = 'transparent';
      tabSub.style.color = '#94a3b8';
    } else {
      tabSub.style.background = 'rgba(168,85,247,0.25)';
      tabSub.style.borderColor = 'rgba(168,85,247,0.5)';
      tabSub.style.color = '#fff';
      tabMain.style.background = 'transparent';
      tabMain.style.borderColor = 'transparent';
      tabMain.style.color = '#94a3b8';
    }
  }

  if (targetLabel) {
    targetLabel.textContent = target === 'main' ? 'MAIN TITLE' : 'SUBTITLE';
  }

  // 2. Populate inputs with active target's values
  const selFont = document.getElementById('tpl-modal-select-font-family');
  if (selFont) selFont.value = styleObj.fontFamily || 'Impact, sans-serif';

  const sliderFontSize = document.getElementById('tpl-modal-slider-font-size');
  const valFontSize = document.getElementById('tpl-modal-val-font-size');
  if (sliderFontSize) sliderFontSize.value = styleObj.fontSize || 52;
  if (valFontSize) valFontSize.textContent = `${styleObj.fontSize || 52}px`;

  const btnBold = document.getElementById('tpl-modal-btn-font-bold');
  if (btnBold) {
    btnBold.style.background = styleObj.bold ? 'rgba(168,85,247,0.25)' : '#161926';
    btnBold.style.borderColor = styleObj.bold ? 'rgba(168,85,247,0.5)' : 'rgba(255,255,255,0.1)';
    btnBold.style.color = styleObj.bold ? '#ffffff' : '#94a3b8';
  }

  const btnItalic = document.getElementById('tpl-modal-btn-font-italic');
  if (btnItalic) {
    btnItalic.style.background = styleObj.italic ? 'rgba(168,85,247,0.25)' : '#161926';
    btnItalic.style.borderColor = styleObj.italic ? 'rgba(168,85,247,0.5)' : 'rgba(255,255,255,0.1)';
    btnItalic.style.color = styleObj.italic ? '#ffffff' : '#94a3b8';
  }

  const btnPosBehind = document.getElementById('tpl-modal-btn-text-pos-behind');
  const btnPosFront = document.getElementById('tpl-modal-btn-text-pos-front');
  if (btnPosBehind && btnPosFront) {
    const isBehind = (styleObj.layerPos !== 'front');
    btnPosBehind.style.background = isBehind ? 'rgba(168,85,247,0.25)' : '#161926';
    btnPosBehind.style.borderColor = isBehind ? 'rgba(168,85,247,0.5)' : 'rgba(255,255,255,0.08)';
    btnPosBehind.style.color = isBehind ? '#fff' : '#94a3b8';
    btnPosFront.style.background = !isBehind ? 'rgba(168,85,247,0.25)' : '#161926';
    btnPosFront.style.borderColor = !isBehind ? 'rgba(168,85,247,0.5)' : 'rgba(255,255,255,0.08)';
    btnPosFront.style.color = !isBehind ? '#fff' : '#94a3b8';
  }
}

// Reusable Matrix Digital Rain Frame Renderer for both preview modal and main studio canvas
const MATRIX_GLYPHS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\uff8a\uff90\uff8b\uff70\uff73\uff7c\uff85\uff93\uff86\uff7b\uff9c\uff82\uff75\uff98\uff71\uff8e\uff83\uff8f\uff79\uff92\uff74\uff76\uff77\uff91\uff95\uff97\uff7e\uff88\uff7d\uff80\uff87\uff8d\u65e510\uff66\uff71\uff73\uff74\uff75\uff76\uff77\uff79\uff7a\uff7b\uff7c\uff7d\uff7e\uff7f\uff80\uff82\uff83\uff85\uff86\uff87\uff88\uff8a\uff8b\uff8e\uff8f\uff90\uff91\uff92\uff93\uff94\uff95\uff97\uff98\uff9c";
function renderMatrixRainCanvasFrame(ctx, width, height, state, dt) {
  if (!ctx || !width || !height) return;
  const fontSize = Math.max(10, state.matrixRainDensity || 16);
  const colCount = Math.floor(width / fontSize);

  // Initialize or re-init columns if dimensions or density changed
  if (!state.matrixColumns || state.matrixColumns.length !== colCount) {
    state.matrixColumns = [];
    for (let i = 0; i < colCount; i++) {
      state.matrixColumns.push({
        y: Math.random() * -100,
        speed: (Math.random() * 0.7 + 0.6) * (state.matrixRainSpeed || 1.0),
        chars: []
      });
    }
  }

  // Semi-transparent fade pass for authentic phosphor trail fade
  ctx.save();
  ctx.fillStyle = 'rgba(5, 7, 12, 0.22)';
  ctx.fillRect(0, 0, width, height);

  ctx.font = `bold ${fontSize}px monospace`;
  const baseColor = state.matrixRainColor || '#00ff41';

  for (let i = 0; i < colCount; i++) {
    const col = state.matrixColumns[i];
    const x = i * fontSize;
    
    // Pick random character
    const char = MATRIX_GLYPHS[Math.floor(Math.random() * MATRIX_GLYPHS.length)];
    
    // Draw leading glowing white/cyan droplet head
    ctx.shadowBlur = 10;
    ctx.shadowColor = '#ffffff';
    ctx.fillStyle = '#ffffff';
    ctx.fillText(char, x, col.y);

    // Draw previous character in user rain color
    ctx.shadowBlur = 12;
    ctx.shadowColor = baseColor;
    ctx.fillStyle = baseColor;
    ctx.fillText(char, x, col.y - fontSize);

    // Advance drop
    const step = fontSize * col.speed * (dt ? dt * 45 : 1);
    col.y += step;

    // Reset when off bottom
    if (col.y > height + 50 && Math.random() > 0.94) {
      col.y = Math.random() * -60;
      col.speed = (Math.random() * 0.7 + 0.6) * (state.matrixRainSpeed || 1.0);
    }
  }
  ctx.restore();
}

function generateCutoutCanvasForUrl(url, callback) {
  if (!url) return;
  // Dedicated asset overrides
  if (url.includes('hiker_cutout.png') || url.includes('hiker_parallax_reference.png')) {
    const cleanImg = new Image();
    cleanImg.onload = () => {
      const offCanvas = document.createElement('canvas');
      offCanvas.width = cleanImg.naturalWidth || cleanImg.width || 582;
      offCanvas.height = cleanImg.naturalHeight || cleanImg.height || 269;
      const offCtx = offCanvas.getContext('2d');
      offCtx.drawImage(cleanImg, 0, 0, offCanvas.width, offCanvas.height);
      callback(offCanvas);
    };
    cleanImg.src = 'hiker_cutout.png';
    return;
  }
  if (url.includes('534528741775') || url === '/portrait_cutout_clean.png' || url === 'portrait_cutout_clean.png') {
    const cleanImg = new Image();
    cleanImg.onload = () => {
      const offCanvas = document.createElement('canvas');
      offCanvas.width = cleanImg.naturalWidth || cleanImg.width || 800;
      offCanvas.height = cleanImg.naturalHeight || cleanImg.height || 1000;
      const offCtx = offCanvas.getContext('2d');
      offCtx.drawImage(cleanImg, 0, 0, offCanvas.width, offCanvas.height);
      callback(offCanvas);
    };
    cleanImg.src = '/portrait_cutout_clean.png';
    return;
  }
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.src = url;
  img.onload = () => {
    try {
      const w = img.naturalWidth || img.width || 400;
      const h = img.naturalHeight || img.height || 400;
      const offCanvas = document.createElement('canvas');
      offCanvas.width = w;
      offCanvas.height = h;
      const offCtx = offCanvas.getContext('2d');
      offCtx.drawImage(img, 0, 0, w, h);

      const imgData = offCtx.getImageData(0, 0, w, h);
      const data = imgData.data;

      // Sample 4 corners for background baseline
      const cornerSamples = [
        0,
        (w - 1) * 4,
        ((h - 1) * w) * 4,
        ((h - 1) * w + (w - 1)) * 4,
        Math.floor(w / 2) * 4
      ];
      const bgColors = cornerSamples.map(idx => ({
        r: data[idx],
        g: data[idx + 1],
        b: data[idx + 2]
      }));

      const visited = new Uint8Array(w * h);
      const queue = [];

      for (let x = 0; x < w; x++) {
        queue.push(x, 0);
        visited[x] = 1;
        const bIdx = (h - 1) * w + x;
        queue.push(x, h - 1);
        visited[bIdx] = 1;
      }
      for (let y = 0; y < h; y++) {
        const lIdx = y * w;
        if (!visited[lIdx]) { queue.push(0, y); visited[lIdx] = 1; }
        const rIdx = y * w + (w - 1);
        if (!visited[rIdx]) { queue.push(w - 1, y); visited[rIdx] = 1; }
      }

      function colorDist(r1, g1, b1, r2, g2, b2) {
        return Math.sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2);
      }

      function isBgPixel(r, g, b) {
        // Protect human skin tones and warm facial tones from being classified as background
        const isWarmSkin = (r > 95 && g > 40 && b > 20 && r > g && (r - g) > 15 && (r - b) > 15);
        if (isWarmSkin) return false;

        for (let i = 0; i < bgColors.length; i++) {
          if (colorDist(r, g, b, bgColors[i].r, bgColors[i].g, bgColors[i].b) < 32) return true;
        }
        if (r > 248 && g > 248 && b > 248) return true; // strict studio pure white
        if (r < 12 && g < 12 && b < 12) return true; // strict solid black studio bg
        if (g > 165 && r < 75 && b < 75) return true; // green screen
        return false;
      }

      let head = 0;
      while (head < queue.length) {
        const qx = queue[head++];
        const qy = queue[head++];
        const pIdx = (qy * w + qx) * 4;
        const r = data[pIdx];
        const g = data[pIdx + 1];
        const b = data[pIdx + 2];

        if (isBgPixel(r, g, b)) {
          data[pIdx + 3] = 0;
          const neighbors = [
            [qx + 1, qy], [qx - 1, qy], [qx, qy + 1], [qx, qy - 1]
          ];
          for (let n = 0; n < 4; n++) {
            const nx = neighbors[n][0];
            const ny = neighbors[n][1];
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
              const nIdx = ny * w + nx;
              if (!visited[nIdx]) {
                visited[nIdx] = 1;
                queue.push(nx, ny);
              }
            }
          }
        }
      }

      offCtx.putImageData(imgData, 0, 0);
      callback(offCanvas);
    } catch (e) {
      // CORS fallback: use canvas with subtle silhouette mask
      console.warn('Cutout fallback due to CORS:', e.message);
      const fallback = document.createElement('canvas');
      fallback.width = 400;
      fallback.height = 400;
      const fCtx = fallback.getContext('2d');
      fCtx.drawImage(img, 0, 0, 400, 400);
      callback(fallback);
    }
  };
}

