function setSpatialGroupOpacity(obj, opacity) {
  if (!obj) return;
  const clampedOp = Math.max(0, Math.min(1, opacity));
  obj.visible = clampedOp > 0.01;
  obj.traverse(child => {
    if (child.isMesh || child.isLineSegments || child.isPoints) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach(m => {
        if (!m) return;
        if (m.userData && m.userData.baseOpacity !== undefined) {
          m.opacity = m.userData.baseOpacity * clampedOp;
        } else {
          m.userData = m.userData || {};
          m.userData.baseOpacity = m.opacity !== undefined ? m.opacity : 1.0;
          m.opacity = m.userData.baseOpacity * clampedOp;
        }
        m.transparent = true;
      });
    }
    if (child.userData && child.userData.isRotatingArtifact) {
      child.rotation.y += 0.01;
      child.rotation.x += 0.005;
    }
  });
}

function createSpatialTextPlane(item) {
  const canvas = document.createElement('canvas');
  canvas.width = 1600;
  canvas.height = 380;
  const ctx = canvas.getContext('2d');

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const titleText = String(item.title || 'THE SYSTEM').toUpperCase();
  const subText = String(item.subtitle || '').toUpperCase();
  const cx = canvas.width / 2;
  const cy = subText ? 155 : 190;

  const fontFam = item.fontFamily || spatial3DState.textFont || 'Cinzel';
  const textStyle = item.textStyle || spatial3DState.textStyle || 'gold';

  let fontSize = 84;
  ctx.font = `900 ${fontSize}px "${fontFam}", "Times New Roman", Georgia, serif`;
  while (ctx.measureText(titleText).width > canvas.width - 180 && fontSize > 40) {
    fontSize -= 4;
    ctx.font = `900 ${fontSize}px "${fontFam}", "Times New Roman", Georgia, serif`;
  }

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Deep Crisp Drop Shadow
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.96)';
  ctx.shadowBlur = 28;
  ctx.shadowOffsetY = 14;
  ctx.fillStyle = '#05070c';
  ctx.fillText(titleText, cx, cy + 6);
  ctx.restore();

  // Multi-tier 3D bevel extrusion
  const bevel = item.textBevel !== undefined ? item.textBevel : (spatial3DState.textBevel || 3);
  for (let b = bevel; b >= 1; b--) {
    ctx.fillStyle = textStyle === 'chrome' ? 'rgba(30,41,59,0.9)' : textStyle === 'cyan' ? 'rgba(8,51,68,0.9)' : textStyle === 'emerald' ? 'rgba(6,78,59,0.9)' : textStyle === 'crimson' ? 'rgba(69,10,10,0.9)' : '#5c3409';
    ctx.fillText(titleText, cx, cy + b * 1.5);
  }

  // Preset Text Gradients
  let textGrad = null;
  if (textStyle === 'chrome') {
    textGrad = ctx.createLinearGradient(cx - 450, cy - 45, cx + 450, cy + 45);
    textGrad.addColorStop(0.0, '#ffffff');
    textGrad.addColorStop(0.28, '#cbd5e1');
    textGrad.addColorStop(0.52, '#64748b');
    textGrad.addColorStop(0.78, '#cbd5e1');
    textGrad.addColorStop(1.0, '#ffffff');
  } else if (textStyle === 'cyan') {
    textGrad = ctx.createLinearGradient(cx - 450, cy - 45, cx + 450, cy + 45);
    textGrad.addColorStop(0.0, '#cffafe');
    textGrad.addColorStop(0.3, '#06b6d4');
    textGrad.addColorStop(0.65, '#0284c7');
    textGrad.addColorStop(1.0, '#38bdf8');
  } else if (textStyle === 'emerald') {
    textGrad = ctx.createLinearGradient(cx - 450, cy - 45, cx + 450, cy + 45);
    textGrad.addColorStop(0.0, '#d1fae5');
    textGrad.addColorStop(0.35, '#10b981');
    textGrad.addColorStop(0.7, '#047857');
    textGrad.addColorStop(1.0, '#34d399');
  } else if (textStyle === 'crimson') {
    textGrad = ctx.createLinearGradient(cx - 450, cy - 45, cx + 450, cy + 45);
    textGrad.addColorStop(0.0, '#fee2e2');
    textGrad.addColorStop(0.3, '#ef4444');
    textGrad.addColorStop(0.7, '#991b1b');
    textGrad.addColorStop(1.0, '#f87171');
  } else if (textStyle === 'white') {
    textGrad = '#f8fafc';
  } else if (textStyle === 'custom') {
    const c1 = item.primaryColor || spatial3DState.textPrimaryColor || '#f59e0b';
    const c2 = item.secondaryColor || spatial3DState.textSecondaryColor || '#fde68a';
    textGrad = ctx.createLinearGradient(cx - 450, cy - 45, cx + 450, cy + 45);
    textGrad.addColorStop(0.0, c1);
    textGrad.addColorStop(0.5, c2);
    textGrad.addColorStop(1.0, c1);
  } else {
    // Default Gold Foil
    textGrad = ctx.createLinearGradient(cx - 450, cy - 45, cx + 450, cy + 45);
    textGrad.addColorStop(0.0, '#fef08a');
    textGrad.addColorStop(0.3, '#d97706');
    textGrad.addColorStop(0.55, '#fde68a');
    textGrad.addColorStop(0.8, '#b45309');
    textGrad.addColorStop(1.0, '#f59e0b');
  }

  ctx.fillStyle = textGrad;
  ctx.fillText(titleText, cx, cy);

  if (subText) {
    const ruleY = cy + 54;
    const ruleHalfW = 260;
    const ruleGrad = ctx.createLinearGradient(cx - ruleHalfW, ruleY, cx + ruleHalfW, ruleY);
    ruleGrad.addColorStop(0, 'rgba(217, 119, 6, 0)');
    ruleGrad.addColorStop(0.5, item.color || '#f59e0b');
    ruleGrad.addColorStop(1, 'rgba(217, 119, 6, 0)');
    ctx.fillStyle = ruleGrad;
    ctx.fillRect(cx - ruleHalfW, ruleY, ruleHalfW * 2, 2);

    ctx.font = '700 22px "JetBrains Mono", monospace';
    ctx.fillStyle = item.color || '#fde68a';
    ctx.letterSpacing = '6px';
    ctx.fillText(subText, cx, cy + 86);
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.anisotropy = 4;

  const sc = item.scale || 1;
  const planeW = 980 * sc;
  const planeH = 232 * sc;

  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  material.userData = { baseOpacity: 1.0 };

  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(planeW, planeH), material);
  mesh.position.set(item.x || 0, item.y || 15, item.z || 0);
  mesh.userData = {
    id: item.id || Date.now().toString(),
    type: 'text',
    title: item.title || 'THE SYSTEM',
    subtitle: item.subtitle || '',
    initialZ: item.z || 0,
    baseX: item.x || 0,
    baseY: item.y || 15,
    x: item.x || 0,
    y: item.y || 15,
    z: item.z || 0,
    scale: sc,
    planeWidth: planeW,
    planeHeight: planeH,
    color: item.color || '#f59e0b',
    fontFamily: fontFam,
    textStyle: textStyle,
    primaryColor: item.primaryColor || spatial3DState.textPrimaryColor,
    secondaryColor: item.secondaryColor || spatial3DState.textSecondaryColor,
    cameraAction: item.cameraAction || 'glance',
    visible: item.visible !== false
  };
  return mesh;
}

function wrapSpatialCanvasText(ctx, text, x, y, maxWidth, lineHeight) {
  const words = String(text || '').split(' ');
  let line = '';
  let curY = y;
  for (let n = 0; n < words.length; n++) {
    const testLine = line + words[n] + ' ';
    const metrics = ctx.measureText(testLine);
    if (metrics.width > maxWidth && n > 0) {
      ctx.fillText(line.trim(), x, curY);
      line = words[n] + ' ';
      curY += lineHeight;
    } else {
      line = testLine;
    }
  }
  if (line.trim()) ctx.fillText(line.trim(), x, curY);
}

function renderSpatialArtifactCanvas(canvas, item, loadedMedia) {
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  const accent = item.color || '#38bdf8';
  const mode = item.artifactMode || (item.type === 'object' ? 'object' : (item.type === 'card' ? 'card' : 'image'));
  const fontFam = item.fontFamily || 'Cinzel';
  const stamp = item.stamp || (item.color === '#ef4444' ? 'CLASSIFIED' : item.color === '#10b981' ? 'LIVE VIDEO' : 'CONFIDENTIAL');

  // Helper to check if media (Image or Video) is ready to draw
  const isVideoEl = loadedMedia && loadedMedia.tagName === 'VIDEO';
  const mediaW = isVideoEl ? (loadedMedia.videoWidth || 640) : (loadedMedia && loadedMedia.naturalWidth ? loadedMedia.naturalWidth : 0);
  const mediaH = isVideoEl ? (loadedMedia.videoHeight || 360) : (loadedMedia && loadedMedia.naturalHeight ? loadedMedia.naturalHeight : 0);
  const hasMedia = loadedMedia && ((isVideoEl && loadedMedia.readyState >= 2) || (!isVideoEl && loadedMedia.complete && mediaW > 0));

  // MODE: FORBES 3D MAGAZINE COVER (James Jani Style)
  if (mode === 'forbes') {
    const bgGrad = ctx.createRadialGradient(W * 0.5, H * 0.45, 10, W * 0.5, H * 0.45, W * 0.65);
    bgGrad.addColorStop(0, '#151a29');
    bgGrad.addColorStop(0.65, '#060912');
    bgGrad.addColorStop(1.0, '#000000');
    ctx.fillStyle = bgGrad;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(10, 10, W - 20, H - 20, 8);
    else ctx.rect(10, 10, W - 20, H - 20);
    ctx.fill();

    if (hasMedia) {
      ctx.save();
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(14, 14, W - 28, H - 28, 6);
      else ctx.rect(14, 14, W - 28, H - 28);
      ctx.clip();

      const imgRatio = mediaW / mediaH;
      const boxW = W - 28;
      const boxH = H - 28;
      let dw = boxW, dh = boxH, dx = 14, dy = 14;
      if (imgRatio > boxW / boxH) {
        dw = boxH * imgRatio;
        dx = 14 - (dw - boxW) * 0.5;
      } else {
        dh = boxW / imgRatio;
        dy = 14 - (dh - boxH) * 0.15;
      }
      ctx.drawImage(loadedMedia, dx, dy, dw, dh);
      ctx.restore();
    }

    const beamY = H * 0.40;
    const curBeamColor = item.beamColor || '#38bdf8';
    const washGrad = ctx.createLinearGradient(0, beamY - 32, W, beamY + 32);
    washGrad.addColorStop(0.0, 'rgba(56, 189, 248, 0)');
    washGrad.addColorStop(0.3, 'rgba(56, 189, 248, 0.45)');
    washGrad.addColorStop(0.5, '#ffffff');
    washGrad.addColorStop(0.7, 'rgba(56, 189, 248, 0.45)');
    washGrad.addColorStop(1.0, 'rgba(56, 189, 248, 0)');
    ctx.fillStyle = washGrad;
    ctx.fillRect(14, beamY - 26, W - 28, 52);

    ctx.shadowColor = curBeamColor;
    ctx.shadowBlur = 18;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(14, beamY - 1.5, W - 28, 3);
    ctx.shadowBlur = 0;

    const flareX = W * 0.28;
    const flareGrad = ctx.createRadialGradient(flareX, beamY, 2, flareX, beamY, 70);
    flareGrad.addColorStop(0.0, '#ffffff');
    flareGrad.addColorStop(0.35, 'rgba(56, 189, 248, 0.8)');
    flareGrad.addColorStop(1.0, 'rgba(56, 189, 248, 0)');
    ctx.fillStyle = flareGrad;
    ctx.beginPath();
    ctx.arc(flareX, beamY, 70, 0, Math.PI * 2);
    ctx.fill();

    ctx.font = '800 13px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.fillText((item.topTickerLeft || 'EXCLUSIVE INVESTIGATION').toUpperCase(), 28, 38);

    ctx.fillStyle = '#ef4444';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(W / 2 - 38, 24, 76, 20, 3);
    else ctx.fillRect(W / 2 - 38, 24, 76, 20);
    ctx.fill();
    ctx.font = '900 11px "Inter", sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.fillText((item.kickerBadge || 'EXPOSED').toUpperCase(), W / 2, 38);
    ctx.textAlign = 'left';

    ctx.font = '800 13px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.textAlign = 'right';
    ctx.fillText((item.topTickerRight || 'VOL. 104 NO. 8').toUpperCase(), W - 28, 38);
    ctx.textAlign = 'left';

    const magTitle = (item.magazineTitle || 'Forbes');
    ctx.font = '900 78px "Playfair Display", Georgia, serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = 'rgba(255,255,255,0.6)';
    ctx.shadowBlur = 24;
    ctx.fillStyle = 'rgba(255,255,255,0.85)';
    ctx.fillText(magTitle, W / 2, 118);
    ctx.shadowColor = 'rgba(0,0,0,0.9)';
    ctx.shadowBlur = 12;
    ctx.fillStyle = '#ffffff';
    ctx.fillText(magTitle, W / 2, 116);
    ctx.shadowBlur = 0;
    ctx.textAlign = 'left';

    ctx.font = 'italic 700 18px "Playfair Display", Georgia, serif';
    ctx.fillStyle = '#ffffff';
    ctx.fillText(item.featureTag || 'SPECIAL REPORT // THE ARCHITECT', 28, H - 75);

    ctx.font = '900 34px "Playfair Display", Georgia, serif';
    ctx.fillStyle = '#ffffff';
    ctx.fillText((item.featureTitle || item.title || 'THE $30 BILLION FRAUD').toUpperCase(), 28, H - 35);

    ctx.strokeStyle = 'rgba(255,255,255,0.18)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(12, 12, W - 24, H - 24);
    return;
  }

  // MODE: GEOMETRIC MUSEUM SHAPE FRAME ('arch-frame', 'circle-portal', 'hexagon-prism', 'diamond-rhombus')
  if (mode === 'shape') {
    const shapeType = item.shapeType || 'arch-frame';
    ctx.save();
    ctx.beginPath();
    const cx = W / 2, cy = H * 0.44;
    if (shapeType === 'circle-portal') {
      ctx.arc(cx, cy, Math.min(W, H) * 0.36, 0, Math.PI * 2);
    } else if (shapeType === 'hexagon-prism') {
      const rx = W * 0.40, ry = H * 0.36;
      for (let s = 0; s < 6; s++) {
        const ang = (s * Math.PI) / 3 - Math.PI / 6;
        const px = cx + Math.cos(ang) * rx;
        const py = cy + Math.sin(ang) * ry;
        if (s === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
    } else if (shapeType === 'diamond-rhombus') {
      ctx.moveTo(cx, 18);
      ctx.lineTo(W - 40, cy);
      ctx.lineTo(cx, H - 95);
      ctx.lineTo(40, cy);
      ctx.closePath();
    } else {
      // Museum Classical Arch Frame
      const archW = W * 0.68;
      const archLeft = (W - archW) / 2;
      const archRight = archLeft + archW;
      const archTopR = archW / 2;
      const archBottom = H - 100;
      ctx.moveTo(archLeft, archBottom);
      ctx.lineTo(archLeft, 24 + archTopR);
      ctx.arc(cx, 24 + archTopR, archTopR, Math.PI, 0, false);
      ctx.lineTo(archRight, archBottom);
      ctx.closePath();
    }

    ctx.fillStyle = '#090d18';
    ctx.fill();
    ctx.save();
    ctx.clip();
    if (hasMedia) {
      const imgRatio = mediaW / mediaH;
      let dw = W, dh = H, dx = 0, dy = 0;
      if (imgRatio > W / H) {
        dw = H * imgRatio;
        dx = -(dw - W) * 0.5;
      } else {
        dh = W / imgRatio;
        dy = -(dh - H) * 0.3;
      }
      ctx.drawImage(loadedMedia, dx, dy, dw, dh);
      const vGrad = ctx.createLinearGradient(0, H * 0.4, 0, H - 90);
      vGrad.addColorStop(0, 'rgba(9,13,24,0)');
      vGrad.addColorStop(1, 'rgba(9,13,24,0.88)');
      ctx.fillStyle = vGrad;
      ctx.fillRect(0, 0, W, H);
    }
    ctx.restore();

    ctx.shadowColor = accent;
    ctx.shadowBlur = 18;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.restore();

    // Museum Pedestal Plaque below shape
    ctx.fillStyle = 'rgba(11, 15, 25, 0.92)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(45, H - 88, W - 90, 74, 10);
    else ctx.rect(45, H - 88, W - 90, 74);
    ctx.fill();
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.textAlign = 'center';
    ctx.font = '700 13px "JetBrains Mono", monospace';
    ctx.fillStyle = accent;
    ctx.fillText((item.subtitle || 'MUSEUM GALLERY INSTALLATION').toUpperCase(), W / 2, H - 62);
    ctx.font = `800 23px "${fontFam}", Georgia, serif`;
    ctx.fillStyle = '#ffffff';
    ctx.fillText((item.title || 'ARCHITECTURAL ARTIFACT').toUpperCase(), W / 2, H - 32);
    ctx.textAlign = 'left';
    return;
  }

  // Frosted Dark Glass Dossier Frame (Standard Image, Video, Chart, or Card)
  ctx.fillStyle = 'rgba(11, 15, 25, 0.94)';
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(10, 10, W - 20, H - 20, 14);
  else ctx.rect(10, 10, W - 20, H - 20);
  ctx.fill();

  if ((mode === 'image' || mode === 'video') && hasMedia) {
    const imgH = Math.round((H - 20) * 0.64);
    ctx.save();
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(12, 12, W - 24, imgH, [12, 12, 0, 0]);
    else ctx.rect(12, 12, W - 24, imgH);
    ctx.clip();

    const imgRatio = mediaW / mediaH;
    const boxW = W - 24;
    const boxRatio = boxW / imgH;
    let dw = boxW, dh = imgH, dx = 12, dy = 12;
    if (imgRatio > boxRatio) {
      dw = imgH * imgRatio;
      dx = 12 - (dw - boxW) * 0.5;
    } else {
      dh = boxW / imgRatio;
      dy = 12 - (dh - imgH) * 0.35;
    }
    ctx.drawImage(loadedMedia, dx, dy, dw, dh);

    const fadeGrad = ctx.createLinearGradient(0, 12 + imgH * 0.45, 0, 12 + imgH);
    fadeGrad.addColorStop(0, 'rgba(11, 15, 25, 0)');
    fadeGrad.addColorStop(1, 'rgba(11, 15, 25, 0.98)');
    ctx.fillStyle = fadeGrad;
    ctx.fillRect(12, 12, boxW, imgH);
    ctx.restore();

    // Live Video indicator or Classification Stamp
    ctx.save();
    ctx.translate(W - 135, 36);
    ctx.rotate(mode === 'video' ? 0 : -0.08);
    ctx.strokeStyle = mode === 'video' ? '#ef4444' : accent;
    ctx.lineWidth = 2;
    ctx.strokeRect(-10, -14, 118, 26);
    ctx.font = '800 12px "JetBrains Mono", monospace';
    ctx.fillStyle = mode === 'video' ? '#ef4444' : accent;
    ctx.fillText(mode === 'video' ? '● LIVE VIDEO' : stamp, -2, 4);
    ctx.restore();

    ctx.fillStyle = accent;
    ctx.fillRect(28, 12 + imgH, W - 56, 2);

    ctx.font = '700 15px "JetBrains Mono", monospace';
    ctx.fillStyle = accent;
    ctx.fillText((item.subtitle || (mode === 'video' ? 'MOTION EXHIBIT // B-ROLL' : 'DEPT. TREASURY // CLASSIFIED')).toUpperCase(), 32, 12 + imgH + 30);

    ctx.font = `800 28px "${fontFam}", Georgia, serif`;
    ctx.fillStyle = '#f8fafc';
    ctx.fillText((item.title || 'CONFIDENTIAL SCAN').toUpperCase(), 32, 12 + imgH + 66);

    ctx.font = '400 16px "Inter", sans-serif';
    ctx.fillStyle = '#94a3b8';
    wrapSpatialCanvasText(ctx, item.body || '', 32, 12 + imgH + 100, W - 64, 22);
  } else if (mode === 'chart') {
    ctx.fillStyle = '#080c14';
    ctx.fillRect(20, 20, W - 40, H - 40);

    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    for (let gy = 50; gy < H - 50; gy += 40) {
      ctx.beginPath(); ctx.moveTo(30, gy); ctx.lineTo(W - 30, gy); ctx.stroke();
    }

    ctx.strokeStyle = accent;
    ctx.lineWidth = 3;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.moveTo(35, H * 0.65);
    ctx.bezierCurveTo(W * 0.25, H * 0.8, W * 0.45, H * 0.35, W * 0.68, H * 0.45);
    ctx.lineTo(W - 35, H * 0.22);
    ctx.stroke();
    ctx.shadowBlur = 0;

    ctx.font = '700 16px "JetBrains Mono", monospace';
    ctx.fillStyle = accent;
    ctx.fillText(item.subtitle || 'FINANCIAL METRIC // TELEMETRY', 35, 45);

    ctx.font = `800 28px "${fontFam}", Georgia, serif`;
    ctx.fillStyle = '#ffffff';
    ctx.fillText(item.title || 'MARKET VOLUME DISCREPANCY', 35, 80);

    ctx.font = '400 16px "Inter", sans-serif';
    ctx.fillStyle = '#cbd5e1';
    wrapSpatialCanvasText(ctx, item.body || 'Capital flow indicates structural liquidity redistribution across decentralized nodes.', 35, H - 90, W - 70, 22);
  } else {
    const headerGrad = ctx.createLinearGradient(0, 14, 0, 85);
    headerGrad.addColorStop(0, 'rgba(255,255,255,0.05)');
    headerGrad.addColorStop(1, 'rgba(255,255,255,0.01)');
    ctx.fillStyle = headerGrad;
    ctx.fillRect(14, 14, W - 28, 70);

    ctx.fillStyle = accent;
    ctx.fillRect(32, 28, 6, 42);

    ctx.font = '700 16px "JetBrains Mono", monospace';
    ctx.fillStyle = accent;
    ctx.fillText((item.subtitle || 'EXECUTIVE SUMMARY').toUpperCase(), 48, 44);

    ctx.font = `800 28px "${fontFam}", Georgia, serif`;
    ctx.fillStyle = '#ffffff';
    ctx.fillText((item.title || 'ARCHIVAL RECORD').toUpperCase(), 48, 72);

    ctx.fillStyle = 'rgba(255,255,255,0.08)';
    ctx.fillRect(32, 102, W - 64, 1);

    ctx.font = '400 18px "Inter", -apple-system, sans-serif';
    ctx.fillStyle = '#e2e8f0';
    wrapSpatialCanvasText(ctx, item.body || 'Declassified dossier record entered into official forensic catalog.', 36, 145, W - 72, 26);
  }

  ctx.strokeStyle = 'rgba(255,255,255,0.14)';
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.strokeStyle = accent;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.45;
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(14, 14, W - 28, H - 28, 10);
  else ctx.rect(14, 14, W - 28, H - 28);
  ctx.stroke();
  ctx.globalAlpha = 1.0;
}

function createSpatialCardPlane(item) {
  const sc = item.scale || 1;
  const cardW = 520 * sc;
  const cardH = 328 * sc;
  const group = new THREE.Group();

  const mode = item.artifactMode || (item.type === 'object' ? 'object' : (item.type === 'card' ? 'card' : 'image'));
  const isPureCelestial = (mode === 'object');

  const canvas = document.createElement('canvas');
  canvas.width = 760;
  canvas.height = 480;

  const texture = new THREE.CanvasTexture(canvas);
  texture.anisotropy = 4;

  const defaultPhotos = ['/paper_tear_stock_archival_news.jpg', '/boardroom_scene_hd.jpg', '/red_string_board_cinematic_plate.jpg', '/cctv_surveillance_scene.jpg', '/paper_tear_gold_standard.jpg', '/power_meeting_cinematic_plate.jpg'];
  const fallbackPhoto = defaultPhotos[Math.abs(parseInt(item.id || '1', 10)) % defaultPhotos.length];
  const imgUrl = (item.imageUrl !== undefined && item.imageUrl !== '') ? item.imageUrl : (mode === 'card' ? '' : fallbackPhoto);
  const vidUrl = item.videoUrl || ((mode === 'video' && /\.(mp4|webm|mov)(\?|$)/i.test(imgUrl)) ? imgUrl : '');

  let activeVideoEl = null;
  if (mode === 'video' && vidUrl && typeof document !== 'undefined') {
    let vid = _spatialVideoTexCache[vidUrl];
    if (!vid) {
      vid = document.createElement('video');
      vid.crossOrigin = 'anonymous';
      vid.src = vidUrl;
      vid.muted = true;
      vid.loop = true;
      vid.playsInline = true;
      vid.autoplay = true;
      vid.addEventListener('canplay', () => {
        vid.play().catch(() => {});
        renderSpatialArtifactCanvas(canvas, item, vid);
        texture.needsUpdate = true;
      });
      vid.load();
      vid.play().catch(() => {});
      _spatialVideoTexCache[vidUrl] = vid;
    } else if (vid.paused) {
      vid.play().catch(() => {});
    }
    activeVideoEl = vid;
  }

  const cachedImg = imgUrl ? _spatialImageTexCache[imgUrl] : null;
  renderSpatialArtifactCanvas(canvas, item, activeVideoEl && activeVideoEl.readyState >= 2 ? activeVideoEl : cachedImg);
  texture.needsUpdate = true;

  if (imgUrl && (!cachedImg || !cachedImg.complete)) {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      _spatialImageTexCache[imgUrl] = img;
      if (!activeVideoEl || activeVideoEl.readyState < 2) {
        renderSpatialArtifactCanvas(canvas, item, img);
        texture.needsUpdate = true;
      }
    };
    img.src = imgUrl;
  }

  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  material.userData = { baseOpacity: isPureCelestial ? 0.3 : 1.0 };
  const frontMesh = new THREE.Mesh(new THREE.PlaneGeometry(cardW, cardH), material);
  group.add(frontMesh);

  // Pure 3D Celestial / Wireframe Geometric Object
  if (isPureCelestial) {
    const shape = item.objectShape || item.objectGeometry || 'icosahedron';
    const objSize = 75 * sc;
    let geom = null;

    if (shape === 'torus') {
      geom = new THREE.TorusGeometry(objSize * 0.85, objSize * 0.28, 16, 36);
    } else if (shape === 'octahedron') {
      geom = new THREE.OctahedronGeometry(objSize, 0);
    } else if (shape === 'dodecahedron') {
      geom = new THREE.DodecahedronGeometry(objSize, 0);
    } else if (shape === 'monolith') {
      geom = new THREE.BoxGeometry(objSize * 0.65, objSize * 1.5, objSize * 0.22);
    } else {
      geom = new THREE.IcosahedronGeometry(objSize, 1);
    }

    const accentColor = item.color ? new THREE.Color(item.color) : new THREE.Color(0x38bdf8);

    const wireMat = new THREE.MeshBasicMaterial({
      color: accentColor,
      wireframe: true,
      transparent: true,
      opacity: 0.95
    });
    wireMat.userData = { baseOpacity: 0.95 };
    const wireMesh = new THREE.Mesh(geom, wireMat);
    wireMesh.position.set(0, 30 * sc, 45);
    wireMesh.userData = {
      isRotatingArtifact: true,
      rotSpeedX: 0.006 + (Math.random() * 0.008),
      rotSpeedY: 0.012 + (Math.random() * 0.01)
    };

    const coreMat = new THREE.MeshStandardMaterial({
      color: accentColor,
      roughness: 0.15,
      metalness: 0.85,
      transparent: true,
      opacity: 0.55
    });
    coreMat.userData = { baseOpacity: 0.55 };
    const coreMesh = new THREE.Mesh(geom.clone(), coreMat);
    coreMesh.scale.set(0.92, 0.92, 0.92);
    wireMesh.add(coreMesh);

    group.add(wireMesh);
  }

  // Flanking gallery angle inward
  const sideSign = (item.x || 0) < 0 ? -1 : ((item.x || 0) > 0 ? 1 : 0);
  const baseTiltY = sideSign < 0 ? 0.38 : (sideSign > 0 ? -0.38 : 0);
  group.rotation.y = baseTiltY;

  group.position.set(item.x !== undefined ? item.x : (sideSign * 520), item.y || 0, item.z || 0);
  group.userData = {
    id: item.id || Date.now().toString(),
    type: item.type || 'card',
    artifactMode: mode,
    objectShape: item.objectShape || item.objectGeometry || 'icosahedron',
    shapeType: item.shapeType || 'arch-frame',
    imageUrl: imgUrl,
    videoUrl: vidUrl,
    _videoEl: activeVideoEl,
    _canvas: canvas,
    _texture: texture,
    _itemConfig: Object.assign({}, item, { artifactMode: mode, imageUrl: imgUrl, videoUrl: vidUrl }),
    magazineTitle: item.magazineTitle,
    featureTag: item.featureTag,
    featureTitle: item.featureTitle,
    topTickerLeft: item.topTickerLeft,
    topTickerRight: item.topTickerRight,
    kickerBadge: item.kickerBadge,
    beamActive: item.beamActive,
    beamColor: item.beamColor,
    title: item.title || 'CONFIDENTIAL SCAN',
    subtitle: item.subtitle || '',
    body: item.body || '',
    stamp: item.stamp || '',
    transitionEffect: item.transitionEffect || 'fade',
    fontFamily: item.fontFamily || 'Cinzel',
    cameraAction: item.cameraAction || 'stop-zoom', // 'stop-zoom', 'detour-veer', 'glance', 'ignore-skip'
    visible: item.visible !== false,
    initialZ: item.z || 0,
    baseX: item.x !== undefined ? item.x : (sideSign * 520),
    baseY: item.y || 0,
    baseRotY: baseTiltY,
    x: item.x !== undefined ? item.x : (sideSign * 520),
    y: item.y || 0,
    z: item.z || 0,
    scale: sc,
    planeWidth: cardW,
    planeHeight: cardH,
    color: item.color || '#f59e0b'
  };
  return group;
}

function createSpatialCodePlane(item) {
  const canvas = document.createElement('canvas');
  canvas.width = 700;
  canvas.height = 400;
  const ctx = canvas.getContext('2d');

  const codeColor = item.color || '#10b981';

  ctx.fillStyle = 'rgba(6, 9, 15, 0.95)';
  ctx.beginPath();
  if (ctx.roundRect) {
    ctx.roundRect(10, 10, 680, 380, 16);
  } else {
    ctx.rect(10, 10, 680, 380);
  }
  ctx.fill();

  ctx.lineWidth = 2;
  ctx.strokeStyle = codeColor;
  ctx.stroke();

  ctx.fillStyle = codeColor;
  ctx.font = 'bold 20px "JetBrains Mono", monospace';
  ctx.fillText('> ' + item.title, 40, 50);

  ctx.font = '18px "JetBrains Mono", monospace';
  ctx.fillStyle = '#6ee7b7';
  const lines = (item.text || item.body || '').split('\n');
  lines.forEach((line, i) => {
    ctx.fillText(line, 40, 110 + (i * 32));
  });

  const texture = new THREE.CanvasTexture(canvas);
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  material.userData = { baseOpacity: 1.0 };

  const sc = item.scale || 1;
  const planeGeo = new THREE.PlaneGeometry(520 * sc, 295 * sc);
  const mesh = new THREE.Mesh(planeGeo, material);
  const sideSign = (item.x || 0) < 0 ? -1 : 1;
  mesh.rotation.y = sideSign < 0 ? 0.35 : -0.35;
  mesh.position.set(item.x || 0, item.y || 0, item.z || 0);
  mesh.userData = {
    id: item.id || Date.now().toString(),
    type: 'code',
    artifactMode: 'code',
    title: item.title,
    initialZ: item.z || 0,
    baseX: item.x || 0,
    baseY: item.y || 0,
    x: item.x || 0,
    y: item.y || 0,
    z: item.z || 0,
    scale: sc,
    planeWidth: 520 * sc,
    planeHeight: 295 * sc,
    color: codeColor,
    text: item.text || item.body || '',
    subtitle: '',
    body: item.text || item.body || ''
  };
  return mesh;
}

function buildSpatialDustParticles(scene) {
  const particleCount = spatial3DState.starCount || 1400;
  const geometry = new THREE.BufferGeometry();
  const positions = new Float32Array(particleCount * 3);

  for (let i = 0; i < particleCount * 3; i += 3) {
    positions[i] = (Math.random() - 0.5) * 4500;
    positions[i + 1] = (Math.random() - 0.5) * 2800;
    positions[i + 2] = (Math.random() - 0.5) * 9500 - 1500;
  }

  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const material = new THREE.PointsMaterial({
    color: 0xe2e8f0,
    size: spatial3DState.starSize || 3.8,
    transparent: true,
    opacity: 0.65,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });

  const dust = new THREE.Points(geometry, material);
  scene.add(dust);
  return dust;
}

function buildSpatialSmokeClouds(scene) {
  const smokeGroup = new THREE.Group();
  const puffCanvas = document.createElement('canvas');
  puffCanvas.width = 256;
  puffCanvas.height = 256;
  const pCtx = puffCanvas.getContext('2d');
  const rad = pCtx.createRadialGradient(128, 128, 8, 128, 128, 124);
  rad.addColorStop(0.0, 'rgba(148, 163, 184, 0.34)');
  rad.addColorStop(0.45, 'rgba(71, 85, 105, 0.16)');
  rad.addColorStop(1.0, 'rgba(15, 23, 42, 0.0)');
  pCtx.fillStyle = rad;
  pCtx.fillRect(0, 0, 256, 256);

  const puffTex = new THREE.CanvasTexture(puffCanvas);
  const puffCount = 42;
  for (let i = 0; i < puffCount; i++) {
    const mat = new THREE.MeshBasicMaterial({
      map: puffTex,
      color: new THREE.Color(spatial3DState.smokeColor || '#334155'),
      transparent: true,
      opacity: 0.22 * ((spatial3DState.smokeIntensity !== undefined ? spatial3DState.smokeIntensity : 65) / 100),
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide
    });
    const size = 900 + Math.random() * 1100;
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(size, size * 0.65), mat);
    plane.position.set(
      (Math.random() - 0.5) * 2200,
      -340 + (Math.random() - 0.35) * 620,
      1100 - (i / puffCount) * 5200 + (Math.random() - 0.5) * 240
    );
    plane.rotation.z = Math.random() * Math.PI * 2;
    plane.userData = {
      driftSpeed: 0.0003 + Math.random() * 0.0006,
      baseX: plane.position.x,
      baseY: plane.position.y,
      phase: i * 0.7
    };
    smokeGroup.add(plane);
  }
  scene.add(smokeGroup);
  return smokeGroup;
}
window.buildSpatialSmokeClouds = buildSpatialSmokeClouds;

function rebuildSpatialGridHelpers() {
  const { gridMeshes, gridDensity, gridColor, envStyle } = spatial3DState;
  if (!gridMeshes || !gridMeshes.group) return;

  const targetDivisions = Math.max(30, Math.min(360, Math.round(gridDensity || 180)));
  let hex = gridColor;
  if (!hex) {
    if (envStyle === 'tunnel-gold') hex = '#d4af37';
    else if (envStyle === 'tunnel-slate') hex = '#64748b';
    else hex = '#06b6d4';
  }
  const mainCol = new THREE.Color(hex);
  const subCol = mainCol.clone().multiplyScalar(0.38);

  if (
    gridMeshes._builtDivisions === targetDivisions &&
    gridMeshes._builtHex === hex.toLowerCase()
  ) {
    return;
  }

  // Clear previous grid children
  while (gridMeshes.group.children.length > 0) {
    const ch = gridMeshes.group.children[0];
    gridMeshes.group.remove(ch);
    if (ch.geometry) ch.geometry.dispose();
    if (ch.material) ch.material.dispose();
  }

  const tunnelLen = 10000;
  const tunnelW = 1800;
  const tunnelH = 960;

  const floorGrid = new THREE.GridHelper(tunnelLen, targetDivisions, mainCol, subCol);
  floorGrid.position.set(0, -tunnelH / 2, -1500);
  gridMeshes.group.add(floorGrid);

  const ceilingGrid = new THREE.GridHelper(tunnelLen, targetDivisions, mainCol, subCol);
  ceilingGrid.position.set(0, tunnelH / 2, -1500);
  ceilingGrid.rotation.x = Math.PI;
  gridMeshes.group.add(ceilingGrid);

  const leftWallGrid = new THREE.GridHelper(tunnelLen, targetDivisions, mainCol, subCol);
  leftWallGrid.position.set(-tunnelW / 2, 0, -1500);
  leftWallGrid.rotation.z = Math.PI / 2;
  gridMeshes.group.add(leftWallGrid);

  const rightWallGrid = new THREE.GridHelper(tunnelLen, targetDivisions, mainCol, subCol);
  rightWallGrid.position.set(tunnelW / 2, 0, -1500);
  rightWallGrid.rotation.z = -Math.PI / 2;
  gridMeshes.group.add(rightWallGrid);

  gridMeshes.floor = floorGrid;
  gridMeshes.ceiling = ceilingGrid;
  gridMeshes.leftWall = leftWallGrid;
  gridMeshes.rightWall = rightWallGrid;
  gridMeshes._builtDivisions = targetDivisions;
  gridMeshes._builtHex = hex.toLowerCase();
  spatial3DState.floorGrid = floorGrid;
}
window.rebuildSpatialGridHelpers = rebuildSpatialGridHelpers;

function updateSpatialEnvironmentGrid() {
  const { gridMeshes, bgStyle, envStyle, gridLuminescence, gridGlow, gridColor, gridVisible, dustVisible, particlesMesh, smokeGroup, smokeVisible, smokeIntensity, smokeColor, gridWallMode, scene, renderer, bgColor, transparentBg } = spatial3DState;
  if (!gridMeshes || !gridMeshes.group) return;

  // Rebuild grid geometry if division density or color changed so grid cells are genuinely tiny & crisp
  rebuildSpatialGridHelpers();

  // Background color & transparent pass
  if (scene) {
    if (transparentBg) {
      scene.background = null;
      if (renderer) renderer.setClearColor(0x000000, 0);
    } else {
      const isPitchMode = bgStyle === 'pitch-black' || bgStyle === 'pitch-dark' || bgStyle === 'black-stars' || bgStyle === 'black-smoke' || bgStyle === 'black-stars-smoke';
      const col = new THREE.Color(isPitchMode ? (bgColor || '#020306') : (bgColor || '#05070c'));
      scene.background = col;
      if (renderer) renderer.setClearColor(col, 1.0);
    }
  }

  const lum = Math.max(0, (gridLuminescence !== undefined ? gridLuminescence : 42) / 100);
  let hex = gridColor;
  if (!hex) {
    if (envStyle === 'tunnel-gold') hex = '#d4af37';
    else if (envStyle === 'tunnel-slate') hex = '#64748b';
    else hex = '#06b6d4';
  }
  const color = new THREE.Color(hex);

  const styleHelper = (gh) => {
    if (!gh || !gh.material) return;
    gh.material.transparent = true;
    gh.material.opacity = Math.min(0.95, 0.45 * lum);
    if (gh.material.color) gh.material.color.copy(color);
  };

  [gridMeshes.floor, gridMeshes.ceiling, gridMeshes.leftWall, gridMeshes.rightWall].forEach(styleHelper);

  // Unified Background Mode Logic:
  // 'pitch-black' | 'pitch-dark' -> Pure Pitch Black (No Grid, No Stars, No Smoke)
  // 'black-stars' | 'stars-only' -> Pitch Black + Stars (No Grid, No Smoke)
  // 'black-smoke'                -> Pitch Black + Volumetric Smoke (No Grid, No Stars)
  // 'black-stars-smoke'          -> Pitch Black + Stars + Volumetric Smoke (No Grid)
  // 'cyber-set' | 'grid-stars'   -> 3D Cyber Grid Set + Stars + Smoke
  // 'cyber-set-clean' | 'grid-only' -> 3D Cyber Grid Set Only
  const mode = bgStyle || 'cyber-set';
  const showGridByMode = (mode === 'cyber-set' || mode === 'grid-stars' || mode === 'cyber-set-clean' || mode === 'grid-only') && (gridVisible !== false);
  const showStarsByMode = (mode === 'black-stars' || mode === 'stars-only' || mode === 'black-stars-smoke' || mode === 'cyber-set' || mode === 'grid-stars') && (dustVisible !== false);
  const showSmokeByMode = (mode === 'black-smoke' || mode === 'black-stars-smoke' || mode === 'cyber-set' || mode === 'grid-stars') && (smokeVisible !== false);

  const wallMode = gridWallMode || (envStyle === 'open-stars' ? 'floor-only' : 'tunnel');
  if (!showGridByMode) {
    gridMeshes.group.visible = false;
  } else {
    gridMeshes.group.visible = true;
    gridMeshes.floor.visible = true;
    gridMeshes.ceiling.visible = (wallMode === 'tunnel' || wallMode === 'floor-ceiling');
    gridMeshes.leftWall.visible = (wallMode === 'tunnel');
    gridMeshes.rightWall.visible = (wallMode === 'tunnel');
  }

  if (particlesMesh) {
    particlesMesh.visible = showStarsByMode;
  }

  if (smokeGroup) {
    smokeGroup.visible = showSmokeByMode;
    const sOp = 0.22 * ((smokeIntensity !== undefined ? smokeIntensity : 65) / 100);
    const sCol = new THREE.Color(smokeColor || '#334155');
    smokeGroup.children.forEach(ch => {
      if (ch.material) {
        ch.material.opacity = sOp;
        ch.material.color.copy(sCol);
      }
    });
  }

  if (spatial3DState.pointLight) {
    spatial3DState.pointLight.intensity = (gridGlow !== undefined ? gridGlow : 85) / 100 * 1.4;
  }

  if (scene && scene.fog) {
    if (mode === 'pitch-black' || mode === 'pitch-dark') scene.fog.density = 0.00004;
    else if (showSmokeByMode) scene.fog.density = 0.00032;
    else scene.fog.density = 0.00022;
  }
}

function sampleDrawnPathX(path, t) {
  if (!path || path.length === 0) return 0;
  if (path.length === 1) return path[0].x;
  const idx = t * (path.length - 1);
  const i0 = Math.max(0, Math.min(path.length - 1, Math.floor(idx)));
  const i1 = Math.max(0, Math.min(path.length - 1, i0 + 1));
  const frac = idx - i0;
  return path[i0].x * (1 - frac) + path[i1].x * frac;
}
window.sampleDrawnPathX = sampleDrawnPathX;

function triggerSpatialWhooshSound() {
  if (!spatial3DState.audioEnabled) return;
  try {
    if (!spatial3DState.audioCtx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      spatial3DState.audioCtx = new AudioCtx();
    }
    const ctx = spatial3DState.audioCtx;
    if (ctx.state === 'suspended') ctx.resume();

    const now = ctx.currentTime;
    const bufferSize = Math.floor(ctx.sampleRate * 0.42);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.sin((i / bufferSize) * Math.PI);
    }

    const noise = ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(140, now);
    filter.frequency.exponentialRampToValueAtTime(520, now + 0.18);
    filter.frequency.exponentialRampToValueAtTime(110, now + 0.42);
    filter.Q.value = 1.6;

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.01, now);
    gain.gain.linearRampToValueAtTime(0.18, now + 0.16);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.42);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.42);
  } catch (e) {}
}

function checkSpatialZPassWhoosh(camZ) {
  if (!spatial3DState.audioEnabled) {
    spatial3DState.lastZPassCheck = camZ;
    return;
  }
  const prevZ = spatial3DState.lastZPassCheck;
  spatial3DState.lastZPassCheck = camZ;
  if (Math.abs(prevZ - camZ) > 300) return;

  for (let i = 0; i < spatial3DState.elements3D.length; i++) {
    const elZ = spatial3DState.elements3D[i].position.z;
    const passPoint = elZ + 180;
    if ((prevZ > passPoint && camZ <= passPoint) || (prevZ < passPoint && camZ >= passPoint)) {
      triggerSpatialWhooshSound();
      break;
    }
  }
}

function updateSpatialHUDTelemetry() {
  const { camera, flightMode, elements3D } = spatial3DState;
  if (!camera) return;
  const hudZ = document.getElementById('spatial-hud-z');
  const hudFov = document.getElementById('spatial-hud-fov');
  const hudLayers = document.getElementById('spatial-hud-layers');
  const hudMode = document.getElementById('spatial-hud-cam-mode');
  if (hudZ) hudZ.textContent = `${camera.position.z.toFixed(1)}`;
  if (hudFov) hudFov.textContent = `${Math.round(camera.fov)}°`;
  if (hudLayers) hudLayers.textContent = `${elements3D.length}`;
  if (hudMode) {
    const modeLabels = {
      'museum-tour': 'MUSEUM CAMERAMAN (ROAM, DETOUR & SLOW-MO ZOOM)',
      'zoomthrough': 'CORRIDOR FLY-THROUGH',
      'pullback': 'PULL-BACK REVEAL',
      'slalom': 'SLALOM DRIFT',
      'orbit': 'ORBITAL RIG',
      'custom-path': 'CUSTOM DRAWN PATH'
    };
    hudMode.textContent = modeLabels[flightMode] || 'MUSEUM CAMERAMAN';
  }
  checkSpatialZPassWhoosh(camera.position.z);
}

function resetSpatialCameraPath() {
  if (!spatial3DState.camera) return;
  spatial3DState.currentTime = 0;
  spatial3DState.lastZPassCheck = 1350;
  if (spatial3DState.flightMode === 'pullback') {
    spatial3DState.camera.position.set(0, 15, -3200);
  } else {
    spatial3DState.camera.position.set(0, 15, 1150);
  }
  const slider = document.getElementById('spatial-timeline-slider');
  if (slider) slider.value = 0;
  updateSpatialTimelineDisplay();
}

function updateSpatialTimelineDisplay() {
  const disp = document.getElementById('spatial-timecode-display');
  if (!disp) return;
  const totalSec = 10;
  const cur = spatial3DState.currentTime * totalSec;
  const s = Math.floor(cur);
  const f = Math.floor((cur - s) * 30);
  disp.textContent = `00:${String(s).padStart(2, '0')}:${String(f).padStart(2, '0')} / 00:10:00`;
}
window.updateSpatialTimelineDisplay = updateSpatialTimelineDisplay;

function renderSpatialLayerList() {
  const listEl = document.getElementById('spatial-layer-list');
  if (!listEl) return;
  listEl.innerHTML = '';

  spatial3DState.elements3D.forEach((mesh, index) => {
    const data = mesh.userData || {};
    const row = document.createElement('div');
    row.style.cssText = 'background:#131826; border:1px solid rgba(255,255,255,0.08); border-radius:8px; padding:10px; display:flex; flex-direction:column; gap:8px;';

    const badgeColors = {
      text: { bg: 'rgba(245,158,11,0.18)', text: '#fbbf24', label: '3D TITLE' },
      card: { bg: 'rgba(56,189,248,0.18)', text: '#38bdf8', label: 'EXHIBIT' },
      code: { bg: 'rgba(16,185,129,0.18)', text: '#34d399', label: 'CODE TERMINAL' }
    };
    const b = badgeColors[data.type] || badgeColors.card;

    row.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <div style="display:flex; align-items:center; gap:6px;">
          <span style="padding:2px 6px; border-radius:4px; background:${b.bg}; color:${b.text}; font-size:9px; font-weight:800;">${b.label}</span>
          <span style="font-size:11px; font-weight:700; color:#f8fafc; max-width:120px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${data.title || 'Layer'}</span>
        </div>
        <div style="display:flex; gap:4px;">
          <button class="btn-edit-spatial-layer" data-index="${index}" style="background:rgba(255,255,255,0.06); border:none; color:#cbd5e1; border-radius:4px; padding:3px 6px; font-size:9px; cursor:pointer;">Edit</button>
          <button class="btn-del-spatial-layer" data-index="${index}" style="background:rgba(239,68,68,0.15); border:none; color:#f87171; border-radius:4px; padding:3px 6px; font-size:9px; cursor:pointer;">✕</button>
        </div>
      </div>
      <div style="display:grid; grid-template-columns:1fr 1fr 1fr; gap:6px; font-size:9px; color:#94a3b8; font-family:'JetBrains Mono', monospace;">
        <div>X: <strong style="color:#e2e8f0;">${Math.round(mesh.position.x)}</strong></div>
        <div>Y: <strong style="color:#e2e8f0;">${Math.round(mesh.position.y)}</strong></div>
        <div>Z: <strong style="color:#38bdf8;">${Math.round(mesh.position.z)}</strong></div>
      </div>
    `;
    listEl.appendChild(row);
  });

  listEl.querySelectorAll('.btn-edit-spatial-layer').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const idx = parseInt(e.currentTarget.dataset.index, 10);
      openLayerEditorModal(idx);
    });
  });

  listEl.querySelectorAll('.btn-del-spatial-layer').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const idx = parseInt(e.currentTarget.dataset.index, 10);
      removeSpatialLayer(idx);
    });
  });

  updateSpatialHUDTelemetry();
}

function openLayerEditorModal(index = -1) {
  spatial3DState.editingLayerIndex = index;
  const modal = document.getElementById('spatial-layer-editor-modal');
  if (!modal) return;
  const titleEl = document.getElementById('spatial-editor-modal-title');
  const typeEl = document.getElementById('spatial-edit-type');
  const headingEl = document.getElementById('spatial-edit-heading');
  const bodyEl = document.getElementById('spatial-edit-body');
  const zEl = document.getElementById('spatial-edit-z');
  const xEl = document.getElementById('spatial-edit-x');

  if (index >= 0 && spatial3DState.elements3D[index]) {
    const mesh = spatial3DState.elements3D[index];
    const d = mesh.userData || {};
    if (titleEl) titleEl.textContent = `Edit Layer #${index + 1}`;
    if (typeEl) typeEl.value = d.type || 'card';
    if (headingEl) headingEl.value = d.title || '';
    if (bodyEl) bodyEl.value = d.body || d.subtitle || '';
    if (zEl) zEl.value = Math.round(mesh.position.z);
    if (xEl) xEl.value = Math.round(mesh.position.x);
  } else {
    if (titleEl) titleEl.textContent = 'Add New 3D Spatial Layer';
    if (typeEl) typeEl.value = 'card';
    if (headingEl) headingEl.value = 'CLASSIFIED EXHIBIT';
    if (bodyEl) bodyEl.value = 'ARCHIVAL EVIDENCE RECORD VERIFIED.';
    if (zEl) zEl.value = -400;
    if (xEl) xEl.value = -500;
  }

  modal.style.display = 'flex';
}

function removeSpatialLayer(index) {
  const mesh = spatial3DState.elements3D[index];
  if (!mesh || !spatial3DState.scene) return;
  spatial3DState.scene.remove(mesh);
  spatial3DState.elements3D.splice(index, 1);
  renderSpatialLayerList();
}

// =========================================================================
// MUSEUM ART COLLECTION CAMERAMAN CHOREOGRAPHY ENGINE
// Roams straight, turns left/right to inspect walls, stops & zooms with
// controllable slow-mo, detours/veers toward another exhibit while ignoring
// skipped items, then continues down the gallery route.
// =========================================================================
function updateSpatialCameraPosition() {
  const {
    camera, flightMode, cameramanStyle, currentTime, camDrift, camShake,
    mouse, camPitch, camYaw, elements3D, showText, pathStyle, pathCurve,
    drawnPath, slowMoIntensity, zoomInspectDepth, detourVeerStrength, wallLookAround
  } = spatial3DState;
  if (!camera) return;

  const driftFactor = Math.max(0, Math.min(1, (camDrift !== undefined ? camDrift : 22) / 100));
  const slowMoAmt = Math.max(0, Math.min(1, (slowMoIntensity !== undefined ? slowMoIntensity : 68) / 100));
  const zoomAmt = Math.max(0, Math.min(1, (zoomInspectDepth !== undefined ? zoomInspectDepth : 65) / 100));
  const detourAmt = Math.max(0, Math.min(1, (detourVeerStrength !== undefined ? detourVeerStrength : 75) / 100));
  const lookWallAmt = Math.max(0, Math.min(1, (wallLookAround !== undefined ? wallLookAround : 65) / 100));
  const t = Math.max(0, Math.min(1, currentTime));

  // Refresh any active video textures on exhibits
  for (let i = 0; i < elements3D.length; i++) {
    const u = elements3D[i].userData;
    if (u && u._videoEl && u._videoEl.readyState >= 2 && u._canvas && u._texture) {
      if (u._videoEl.paused) u._videoEl.play().catch(() => {});
      renderSpatialArtifactCanvas(u._canvas, u._itemConfig || u, u._videoEl);
      u._texture.needsUpdate = true;
    }
  }

  let targetZ = 1150;
  let targetX = 0;
  let targetY = 15;
  let dynamicLookX = 0;
  let dynamicLookY = 15;
  let dynamicLookZ = 150;
  let useDynamicLook = false;

  if (flightMode === 'pullback') {
    targetZ = -3100 + (t * 4250);
  } else if (flightMode === 'orbit') {
    const angle = (t - 0.5) * Math.PI * 0.75;
    const radius = 1600;
    targetX = Math.sin(angle) * radius * 0.55;
    targetZ = -1200 + Math.cos(angle) * radius;
    targetY = 60 + Math.sin(t * Math.PI * 2) * 45;
  } else if (flightMode === 'museum-tour' && (!drawnPath || drawnPath.length < 2)) {
    // Build dynamic Museum Cameraman waypoints from active exhibits sorted front-to-back (Z descending)
    const activeStops = [];
    // Entrance waypoint (cameraman enters gallery walking straight)
    activeStops.push({
      x: 0, y: 18, z: 1120,
      lookX: 0, lookY: 18, lookZ: 550,
      dwell: 0.04
    });

    const sortedMeshes = elements3D
      .filter(m => m && m.userData && m.userData.visible !== false)
      .slice()
      .sort((a, b) => b.position.z - a.position.z);

    for (let i = 0; i < sortedMeshes.length; i++) {
      const m = sortedMeshes[i];
      const u = m.userData || {};
      if (u.type === 'text' && showText === false) continue;

      const action = u.cameraAction || (u.type === 'text' ? 'glance' : 'stop-zoom');
      const exX = u.baseX !== undefined ? u.baseX : m.position.x;
      const exY = u.baseY !== undefined ? u.baseY : m.position.y;
      const exZ = m.position.z;

      if (action === 'ignore-skip') {
        // Cameraman spots another piece ahead, makes a deliberate veer/detour to the opposite side and bypasses this one!
        const veerOppositeX = exX < 0 ? (190 * detourAmt) : (exX > 0 ? (-190 * detourAmt) : 140 * detourAmt);
        activeStops.push({
          x: veerOppositeX,
          y: 22,
          z: exZ + 380,
          lookX: veerOppositeX * 1.35,
          lookY: 20,
          lookZ: exZ - 260,
          dwell: 0.02
        });
        continue;
      }

      if (action === 'detour-veer') {
        // Pre-detour approach in center hallway, then sudden lateral veer toward the exhibit wall & zoom inspect
        const approachX = exX * 0.18 * detourAmt;
        activeStops.push({
          x: approachX,
          y: 18,
          z: exZ + 620,
          lookX: exX * 0.75 * lookWallAmt,
          lookY: exY,
          lookZ: exZ,
          dwell: 0.03
        });

        const inspectDist = Math.max(240, 440 - zoomAmt * 185);
        const lateralVeerX = exX * (0.62 * detourAmt + 0.18 * zoomAmt);
        activeStops.push({
          x: lateralVeerX,
          y: exY * 0.55 + 10,
          z: exZ + inspectDist,
          lookX: exX * (0.45 + 0.55 * lookWallAmt),
          lookY: exY,
          lookZ: exZ,
          dwell: 0.18 + slowMoAmt * 0.42
        });
      } else if (action === 'stop-zoom') {
        // Cameraman walks up, turns toward the wall/hero piece, stops in slow-mo & zooms in close
        const inspectDist = Math.max(230, 460 - zoomAmt * 200);
        const lateralShiftX = exX * (0.44 * detourAmt + 0.22 * zoomAmt);
        activeStops.push({
          x: lateralShiftX,
          y: exY * 0.5 + 12,
          z: exZ + inspectDist,
          lookX: exX * (0.4 + 0.6 * lookWallAmt),
          lookY: exY,
          lookZ: exZ,
          dwell: 0.22 + slowMoAmt * 0.48
        });
      } else {
        // 'glance': cameraman continues walking straight while panning head to admire the piece
        activeStops.push({
          x: exX * 0.15 * detourAmt,
          y: 16,
          z: exZ + 480,
          lookX: exX * 0.85 * lookWallAmt,
          lookY: exY,
          lookZ: exZ,
          dwell: 0.05 + slowMoAmt * 0.10
        });
      }
    }

    // Final exit runway waypoint
    const lastZ = sortedMeshes.length ? sortedMeshes[sortedMeshes.length - 1].position.z : -2600;
    activeStops.push({
      x: 0, y: 18, z: lastZ - 320,
      lookX: 0, lookY: 15, lookZ: lastZ - 1200,
      dwell: 0.05
    });

    // Allocate timeline segments across [0, 1] with slow-mo plateaus on high-dwell exhibits
    const segWeights = [];
    let totalWeight = 0;
    for (let i = 0; i < activeStops.length - 1; i++) {
      const moveWeight = 0.28;
      const pauseWeight = activeStops[i + 1].dwell || 0.05;
      const w = moveWeight + pauseWeight;
      segWeights.push({ moveWeight, pauseWeight, total: w });
      totalWeight += w;
    }

    let accum = 0;
    let segIdx = 0;
    let localT = 0;
    for (let i = 0; i < segWeights.length; i++) {
      const normW = segWeights[i].total / (totalWeight || 1);
      if (t <= accum + normW || i === segWeights.length - 1) {
        segIdx = i;
        localT = normW > 0 ? Math.max(0, Math.min(1, (t - accum) / normW)) : 0;
        break;
      }
      accum += normW;
    }

    const p0 = activeStops[segIdx];
    const p1 = activeStops[segIdx + 1] || p0;
    const sw = segWeights[segIdx] || { moveWeight: 0.5, pauseWeight: 0.5, total: 1 };
    const movePortion = sw.moveWeight / sw.total;

    let interp = 0;
    let inSlowMoPlateau = false;
    let plateauFrac = 0;
    if (localT < movePortion) {
      const mFrac = localT / Math.max(0.001, movePortion);
      // Smooth cubic ease-in-out between gallery stops
      interp = mFrac < 0.5 ? 4 * mFrac * mFrac * mFrac : 1 - Math.pow(-2 * mFrac + 2, 3) / 2;
    } else {
      // Cameraman is stopped & zooming in slow-motion on exhibit p1
      inSlowMoPlateau = true;
      plateauFrac = (localT - movePortion) / Math.max(0.001, 1 - movePortion);
      interp = 1.0;
    }

    targetX = p0.x + (p1.x - p0.x) * interp;
    targetY = p0.y + (p1.y - p0.y) * interp;
    targetZ = p0.z + (p1.z - p0.z) * interp;

    // During slow-mo inspection, cameraman leans in closer (macro push-in) and subtly breathes
    if (inSlowMoPlateau) {
      const pushIn = Math.sin(plateauFrac * Math.PI * 0.85) * (95 * zoomAmt * slowMoAmt);
      const leanX = (p1.lookX - p1.x) * 0.18 * Math.sin(plateauFrac * Math.PI) * zoomAmt;
      targetZ -= pushIn;
      targetX += leanX;
    }

    dynamicLookX = p0.lookX + (p1.lookX - p0.lookX) * interp;
    dynamicLookY = p0.lookY + (p1.lookY - p0.lookY) * interp;
    dynamicLookZ = p0.lookZ + (p1.lookZ - p0.lookZ) * interp;
    useDynamicLook = true;
  } else {
    // Standard zoomthrough / slalom / custom-path
    targetZ = 1150 - (t * 4250);
    if (pathStyle === 'slalom' || flightMode === 'slalom') {
      targetX = Math.sin(t * Math.PI * 3) * 220 * driftFactor;
      targetY = 15 + Math.cos(t * Math.PI * 3) * 28 * driftFactor;
    } else if (pathStyle === 'cosmic-wave') {
      targetX = Math.sin(t * Math.PI * 2) * 180 * driftFactor;
      targetY = 15 + Math.cos(t * Math.PI * 4) * 55 * driftFactor;
    } else if (drawnPath && drawnPath.length >= 2) {
      targetX = sampleDrawnPathX(drawnPath, t);
      targetY = 15 + (pathCurve || 0) * 0.2;
    } else {
      const curveOffset = (pathCurve || 0) * 3.5;
      targetX = Math.sin(t * Math.PI) * curveOffset + (Math.sin(t * Math.PI * 2) * (36 * driftFactor));
      targetY = 15 + (Math.cos(t * Math.PI * 2) * (20 * driftFactor));
    }
  }

  // Organic Handheld Cameraman Breathing & Imperfection
  const shakeAmt = (camShake !== undefined ? camShake : 12) / 100;
  const now = performance.now() * 0.0018;
  const shakeX = Math.sin(now * 2.6) * 4.2 * shakeAmt;
  const shakeY = Math.cos(now * 3.2) * 3.0 * shakeAmt;
  const shakeRoll = Math.sin(now * 1.7) * 0.006 * shakeAmt;

  camera.position.z += (targetZ - camera.position.z) * 0.14;
  camera.position.x += ((targetX + shakeX) - camera.position.x) * 0.12;
  camera.position.y += ((targetY + shakeY) - camera.position.y) * 0.12;

  const pitchRad = ((camPitch || 0) * Math.PI) / 180;
  const yawRad = ((camYaw || 0) * Math.PI) / 180;

  if (useDynamicLook) {
    spatial3DState._smoothLookX = (spatial3DState._smoothLookX !== undefined ? spatial3DState._smoothLookX : dynamicLookX) + (dynamicLookX - (spatial3DState._smoothLookX || 0)) * 0.11;
    spatial3DState._smoothLookY = (spatial3DState._smoothLookY !== undefined ? spatial3DState._smoothLookY : dynamicLookY) + (dynamicLookY - (spatial3DState._smoothLookY || 15)) * 0.11;
    spatial3DState._smoothLookZ = (spatial3DState._smoothLookZ !== undefined ? spatial3DState._smoothLookZ : dynamicLookZ) + (dynamicLookZ - (spatial3DState._smoothLookZ || 0)) * 0.11;

    const finalLookX = spatial3DState._smoothLookX + Math.sin(yawRad) * 420 + (mouse.x * 28);
    const finalLookY = spatial3DState._smoothLookY - Math.sin(pitchRad) * 320 + (-mouse.y * 18);
    const finalLookZ = spatial3DState._smoothLookZ;
    camera.lookAt(finalLookX, finalLookY, finalLookZ);
  } else {
    const lookDistance = 1000;
    const lookTargetX = camera.position.x + Math.sin(yawRad) * lookDistance + (mouse.x * 24);
    const lookTargetY = camera.position.y - Math.sin(pitchRad) * lookDistance + (-mouse.y * 16);
    const lookTargetZ = camera.position.z - Math.cos(yawRad) * Math.cos(pitchRad) * lookDistance;
    camera.lookAt(lookTargetX, lookTargetY, lookTargetZ);
  }
  camera.rotation.z += shakeRoll;

  // Per-Layer Focal Visibility, Transition Effects & Corridor Clearance
  for (let i = 0; i < elements3D.length; i++) {
    const obj = elements3D[i];
    const u = obj.userData || {};
    if (u.visible === false) {
      setSpatialGroupOpacity(obj, 0.0);
      continue;
    }
    const distInFront = camera.position.z - obj.position.z;

    let opacity = 1.0;

    if (u.type === 'text') {
      if (showText === false) {
        setSpatialGroupOpacity(obj, 0.0);
        continue;
      }
      if (distInFront <= 160) {
        opacity = 0.0;
      } else if (distInFront < 420) {
        const p = (distInFront - 160) / (420 - 160);
        opacity = p * p * (3 - 2 * p);
      } else if (distInFront > 2200) {
        opacity = 0.0;
      } else if (distInFront > 1450) {
        const p = 1.0 - (distInFront - 1450) / (2200 - 1450);
        opacity = p * p * (3 - 2 * p);
      }
      obj.position.x = u.baseX || 0;
      obj.position.y = u.baseY || 15;
    } else {
      const rawX = u.baseX !== undefined ? u.baseX : obj.position.x;
      const sideSign = rawX < 0 ? -1 : (rawX > 0 ? 1 : 0);
      const isCenterHero = sideSign === 0;

      const baseW = Math.abs(rawX) > 0 ? Math.abs(rawX) : (isCenterHero ? 0 : 500);
      const minCorridorHalfWidth = isCenterHero ? 0 : Math.max(360, Math.min(680, baseW));

      const effect = u.transitionEffect || 'fade';
      let effX = sideSign * minCorridorHalfWidth;
      let effScale = u.scale || 1.0;
      let effRotY = isCenterHero ? 0 : (u.baseRotY || (sideSign < 0 ? 0.38 : -0.38));

      if (distInFront > 800 && distInFront < 2600) {
        const normDist = (distInFront - 800) / (2600 - 800);
        if (effect === 'slide-in') {
          effX += sideSign * normDist * 160;
        } else if (effect === 'scale-pop') {
          effScale *= (1.0 - normDist * 0.28);
        } else if (effect === 'yaw-drift') {
          effRotY += sideSign * normDist * 0.35;
        }
      }

      obj.position.x = effX;
      obj.position.y = (u.baseY || 0) + Math.sin(performance.now() * 0.0012 + i * 1.5) * 6;
      obj.scale.set(effScale, effScale, effScale);
      obj.rotation.y = effRotY;

      if (distInFront <= 120) {
        opacity = 0.0;
      } else if (distInFront < 340) {
        const p = (distInFront - 120) / (340 - 120);
        opacity = p * p * (3 - 2 * p);
      } else if (distInFront > 3500) {
        opacity = 0.0;
      } else if (distInFront > 2450) {
        const p = 1.0 - (distInFront - 2450) / (3500 - 2450);
        opacity = p * p * (3 - 2 * p);
      }
    }

    setSpatialGroupOpacity(obj, opacity);
  }

  updateSpatialHUDTelemetry();
}

function loadSpatialPreset(presetKey) {
  spatial3DState.activePreset = presetKey;
  if (presetKey === 'forbes-hallway') {
    spatial3DState.envStyle = 'tunnel-cyan';
    spatial3DState.gridColor = '#06b6d4';
    spatial3DState.flightMode = 'museum-tour';
    spatial3DState.pathStyle = 'corridor-hallway';
    spatial3DState.textStyle = 'white';
  } else if (presetKey === 'cyber-matrix') {
    spatial3DState.envStyle = 'tunnel-cyan';
    spatial3DState.gridColor = '#06b6d4';
    spatial3DState.textStyle = 'cyan';
  } else if (presetKey === 'philosophy') {
    spatial3DState.envStyle = 'tunnel-gold';
    spatial3DState.gridColor = '#d4af37';
    spatial3DState.textStyle = 'white';
  } else if (presetKey === 'cosmic-universe') {
    spatial3DState.envStyle = 'open-stars';
    spatial3DState.gridColor = '#38bdf8';
    spatial3DState.textStyle = 'cyan';
  } else {
    spatial3DState.envStyle = 'tunnel-slate';
    spatial3DState.gridColor = '#64748b';
    spatial3DState.textStyle = 'white';
  }

  const scene = spatial3DState.scene;
  if (!scene) return;

  (spatial3DState.elements3D || []).forEach(obj => scene.remove(obj));
  spatial3DState.elements3D = [];

  document.querySelectorAll('.btn-spatial-preset').forEach(btn => {
    const isAct = btn.dataset.preset === presetKey;
    btn.style.background = isAct ? 'rgba(168,85,247,0.25)' : 'rgba(18,19,28,0.8)';
    btn.style.borderColor = isAct ? 'rgba(168,85,247,0.6)' : 'rgba(255,255,255,0.1)';
    btn.style.color = isAct ? '#e9d5ff' : '#94a3b8';
  });

  const items = SPATIAL_PRESETS[presetKey] || SPATIAL_PRESETS['forbes-hallway'] || SPATIAL_PRESETS['docu-essay'];
  items.forEach(item => {
    let mesh = null;
    if (item.type === 'text') mesh = createSpatialTextPlane(item);
    else if (item.type === 'card' || item.type === 'image' || item.type === 'object' || item.type === 'video' || item.type === 'shape') mesh = createSpatialCardPlane(item);
    else if (item.type === 'code') mesh = createSpatialCodePlane(item);

    if (mesh) {
      scene.add(mesh);
      spatial3DState.elements3D.push(mesh);
    }
  });

  if (typeof updateSpatialEnvironmentGrid === 'function') updateSpatialEnvironmentGrid();
  if (typeof renderSpatialLayerList === 'function') renderSpatialLayerList();
  if (typeof resetSpatialCameraPath === 'function') resetSpatialCameraPath();
}
window.loadSpatialPreset = loadSpatialPreset;

function initSpatialThreeJSEngine() {
  const container = document.getElementById('spatial-threejs-container') || document.getElementById('spatial-threejs-container-legacy');
  if (!container || typeof THREE === 'undefined') return;

  if (spatial3DState.renderer) {
    const w = container.clientWidth || 800;
    const h = container.clientHeight || 500;
    spatial3DState.camera.aspect = w / h;
    spatial3DState.camera.updateProjectionMatrix();
    spatial3DState.renderer.setSize(w, h);
    if (!spatial3DState.elements3D || spatial3DState.elements3D.length === 0) {
      loadSpatialPreset(spatial3DState.activePreset || 'forbes-hallway');
    }
    return;
  }

  const w = container.clientWidth || 800;
  const h = container.clientHeight || 500;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x05070c);
  scene.fog = new THREE.FogExp2(0x05070c, 0.00026);

  const camera = new THREE.PerspectiveCamera(52, w / h, 10, 10000);
  camera.position.set(0, 15, 1150);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, preserveDrawingBuffer: true });
  renderer.setSize(w, h);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setClearColor(0x05070c, 1.0);

  container.innerHTML = '';
  container.appendChild(renderer.domElement);

  const ambientLight = new THREE.AmbientLight(0xffffff, 0.95);
  scene.add(ambientLight);

  const dirLight = new THREE.DirectionalLight(0xf59e0b, 1.1);
  dirLight.position.set(500, 1000, 1000);
  scene.add(dirLight);

  const pointLight = new THREE.PointLight(0x38bdf8, 1.2, 3500);
  pointLight.position.set(0, 0, -2000);
  scene.add(pointLight);

  // Tiny Fine 3D Cyber Grid Group (dynamically rebuilt with 60–340 divisions)
  const gridGroup = new THREE.Group();
  scene.add(gridGroup);

  const particlesMesh = buildSpatialDustParticles(scene);
  const smokeGroup = buildSpatialSmokeClouds(scene);

  spatial3DState.scene = scene;
  spatial3DState.camera = camera;
  spatial3DState.renderer = renderer;
  spatial3DState.particlesMesh = particlesMesh;
  spatial3DState.smokeGroup = smokeGroup;
  spatial3DState.gridMeshes = {
    group: gridGroup,
    floor: null,
    ceiling: null,
    leftWall: null,
    rightWall: null,
    _builtDivisions: 0,
    _builtHex: ''
  };
  spatial3DState.ambientLight = ambientLight;
  spatial3DState.pointLight = pointLight;

  container.addEventListener('mousemove', (e) => {
    const rect = container.getBoundingClientRect();
    spatial3DState.mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    spatial3DState.mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  });

  updateSpatialEnvironmentGrid();
  loadSpatialPreset(spatial3DState.activePreset || 'forbes-hallway');

  function animateSpatialEngine() {
    if (spatial3DState.isPlaying) {
      const speedStep = 0.0014 * (spatial3DState.camSpeed !== undefined ? spatial3DState.camSpeed : 1.0);
      spatial3DState.currentTime += speedStep;

      if (spatial3DState.currentTime > 1.0) spatial3DState.currentTime = 0.0;
      else if (spatial3DState.currentTime < 0.0) spatial3DState.currentTime = 1.0;

      const slider = document.getElementById('spatial-timeline-slider');
      if (slider) slider.value = spatial3DState.currentTime * 100;
      updateSpatialTimelineDisplay();
    }

    updateSpatialCameraPosition();

    // Active Grid Conveyor streaming flow down corridor
    if (spatial3DState.gridMeshes && spatial3DState.gridMeshes.group && spatial3DState.gridSpeed > 0) {
      const cellSpan = 10000 / Math.max(40, spatial3DState.gridDensity || 180);
      const flowZ = (spatial3DState.currentTime * 2400 * spatial3DState.gridSpeed) % cellSpan;
      spatial3DState.gridMeshes.group.position.z = flowZ;
    }

    if (spatial3DState.particlesMesh && spatial3DState.particlesMesh.visible) {
      spatial3DState.particlesMesh.rotation.y += 0.0003 * (spatial3DState.starSpeed || 1);
      spatial3DState.particlesMesh.rotation.x += 0.0001 * (spatial3DState.starSpeed || 1);
    }

    if (spatial3DState.smokeGroup && spatial3DState.smokeGroup.visible) {
      const nowT = performance.now() * 0.001;
      spatial3DState.smokeGroup.children.forEach(puff => {
        const ud = puff.userData || {};
        puff.rotation.z += (ud.driftSpeed || 0.0004);
        puff.position.x = (ud.baseX || 0) + Math.sin(nowT * 0.5 + (ud.phase || 0)) * 55;
      });
    }

    // Tumble 3D celestial wireframe objects
    if (spatial3DState.elements3D && spatial3DState.elements3D.length) {
      for (let i = 0; i < spatial3DState.elements3D.length; i++) {
        const grp = spatial3DState.elements3D[i];
        for (let j = 0; j < grp.children.length; j++) {
          const child = grp.children[j];
          if (child.userData && child.userData.isRotatingArtifact) {
            child.rotation.x += (child.userData.rotSpeedX || 0.01);
            child.rotation.y += (child.userData.rotSpeedY || 0.015);
          }
        }
      }
    }

    if (spatial3DState.renderer && spatial3DState.scene && spatial3DState.camera) {
      spatial3DState.renderer.render(spatial3DState.scene, spatial3DState.camera);
    }

    spatial3DState.animId = requestAnimationFrame(animateSpatialEngine);
  }
  spatial3DState.animId = requestAnimationFrame(animateSpatialEngine);
}

function openSpatial3DMotionSuite() {
  const tpl = (typeof EFFECT_TEMPLATES_DATA !== 'undefined') && EFFECT_TEMPLATES_DATA.find(t => t.id === 'spatial-3d-motion-suite');
  if (tpl && typeof openTopTemplateCustomizer === 'function') {
    openTopTemplateCustomizer(tpl);
    return;
  }
  const modal = document.getElementById('modal-spatial-3d-suite');
  if (!modal) return;
  modal.style.display = 'flex';
  setTimeout(() => {
    initSpatialThreeJSEngine();
  }, 100);
}

function closeSpatial3DMotionSuite() {
  const modal = document.getElementById('modal-spatial-3d-suite');
  if (!modal) return;
  modal.style.display = 'none';
  if (spatial3DState.animId) {
    cancelAnimationFrame(spatial3DState.animId);
    spatial3DState.animId = null;
  }
}

function bindSpatial3DModalControls() {
  // Modal close buttons
  document.getElementById('btn-close-spatial-3d-suite')?.addEventListener('click', closeSpatial3DMotionSuite);

  // Tab switching: Camera Rig, 3D Layers, Post FX
  const tabCam = document.getElementById('tab-spatial-cam');
  const tabLayers = document.getElementById('tab-spatial-layers');
  const tabFx = document.getElementById('tab-spatial-fx');
  const panelCam = document.getElementById('spatial-panel-cam');
  const panelLayers = document.getElementById('spatial-panel-layers');
  const panelFx = document.getElementById('spatial-panel-fx');

  function setSpatialTab(activeTab, activePanel) {
    [tabCam, tabLayers, tabFx].forEach(t => {
      if (!t) return;
      t.style.background = 'transparent';
      t.style.color = '#94a3b8';
    });
    [panelCam, panelLayers, panelFx].forEach(p => {
      if (p) p.style.display = 'none';
    });
    if (activeTab) {
      activeTab.style.background = 'rgba(168,85,247,0.25)';
      activeTab.style.color = '#c084fc';
    }
    if (activePanel) activePanel.style.display = 'flex';
  }

  tabCam?.addEventListener('click', () => setSpatialTab(tabCam, panelCam));
  tabLayers?.addEventListener('click', () => {
    setSpatialTab(tabLayers, panelLayers);
    renderSpatialLayerList();
  });
  tabFx?.addEventListener('click', () => setSpatialTab(tabFx, panelFx));

  // Preset switching
  document.querySelectorAll('.btn-spatial-preset').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const p = e.currentTarget.dataset.preset;
      loadSpatialPreset(p);
    });
  });

  // Flight Mode Buttons
  document.querySelectorAll('.btn-spatial-cam-mode').forEach(btn => {
    btn.addEventListener('click', (e) => {
      document.querySelectorAll('.btn-spatial-cam-mode').forEach(b => {
        b.style.background = '#131826';
        b.style.borderColor = 'rgba(255,255,255,0.08)';
        b.style.color = '#cbd5e1';
      });
      e.currentTarget.style.background = 'rgba(168,85,247,0.18)';
      e.currentTarget.style.borderColor = '#a855f7';
      e.currentTarget.style.color = '#e9d5ff';

      const mode = e.currentTarget.dataset.mode;
      spatial3DState.flightMode = mode;
      resetSpatialCameraPath();
    });
  });

  // Camera Sliders
  document.getElementById('spatial-range-speed')?.addEventListener('input', (e) => {
    spatial3DState.camSpeed = parseFloat(e.target.value);
    const lbl = document.getElementById('spatial-val-speed');
    if (lbl) lbl.textContent = `${spatial3DState.camSpeed.toFixed(1)}x`;
  });
  document.getElementById('spatial-range-drift')?.addEventListener('input', (e) => {
    spatial3DState.camDrift = parseFloat(e.target.value);
    const lbl = document.getElementById('spatial-val-drift');
    if (lbl) lbl.textContent = `${spatial3DState.camDrift}%`;
  });
  document.getElementById('spatial-range-fovwarp')?.addEventListener('input', (e) => {
    spatial3DState.fovWarp = parseFloat(e.target.value);
    const lbl = document.getElementById('spatial-val-fovwarp');
    if (lbl) lbl.textContent = `${spatial3DState.fovWarp}\u00b0`;
    if (spatial3DState.camera) {
      spatial3DState.camera.fov = spatial3DState.fovWarp;
      spatial3DState.camera.updateProjectionMatrix();
    }
  });

  // 3D Parallax & Depth Angles: Pitch & Yaw
  document.getElementById('spatial-range-pitch')?.addEventListener('input', (e) => {
    spatial3DState.camPitch = parseFloat(e.target.value);
    const lbl = document.getElementById('spatial-val-pitch');
    if (lbl) lbl.textContent = `${spatial3DState.camPitch}\u00b0`;
  });

  document.getElementById('spatial-range-yaw')?.addEventListener('input', (e) => {
    spatial3DState.camYaw = parseFloat(e.target.value);
    const lbl = document.getElementById('spatial-val-yaw');
    if (lbl) lbl.textContent = `${spatial3DState.camYaw}\u00b0`;
  });

  // Post FX Sliders
  document.getElementById('spatial-range-fog')?.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value);
    spatial3DState.fogDensity = val;
    const densityVal = 0.0001 + (val / 100) * 0.0008;
    if (spatial3DState.scene && spatial3DState.scene.fog) {
      spatial3DState.scene.fog.density = densityVal;
    }
    const lbl = document.getElementById('spatial-val-fog');
    if (lbl) lbl.textContent = val < 30 ? 'Low' : val > 70 ? 'Heavy' : 'Medium';
  });

  document.getElementById('spatial-range-light')?.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value);
    spatial3DState.lightIntensity = val;
    if (spatial3DState.ambientLight) {
      spatial3DState.ambientLight.intensity = (val / 100) * 0.95;
    }
    const lbl = document.getElementById('spatial-val-light');
    if (lbl) lbl.textContent = `${val}%`;
  });

  // Grid & Dust Toggles
  document.getElementById('btn-spatial-toggle-grid')?.addEventListener('click', () => {
    spatial3DState.gridVisible = !spatial3DState.gridVisible;
    if (spatial3DState.floorGrid) spatial3DState.floorGrid.visible = spatial3DState.gridVisible;
    const btn = document.getElementById('btn-spatial-toggle-grid');
    if (btn) {
      btn.style.background = spatial3DState.gridVisible ? 'rgba(168,85,247,0.18)' : 'rgba(255,255,255,0.05)';
      btn.style.borderColor = spatial3DState.gridVisible ? 'rgba(168,85,247,0.5)' : 'rgba(255,255,255,0.1)';
    }
  });

  document.getElementById('btn-spatial-toggle-dust')?.addEventListener('click', () => {
    spatial3DState.dustVisible = !spatial3DState.dustVisible;
    if (spatial3DState.particlesMesh) spatial3DState.particlesMesh.visible = spatial3DState.dustVisible;
    const btn = document.getElementById('btn-spatial-toggle-dust');
    if (btn) {
      btn.style.background = spatial3DState.dustVisible ? 'rgba(168,85,247,0.18)' : 'rgba(255,255,255,0.05)';
      btn.style.borderColor = spatial3DState.dustVisible ? 'rgba(168,85,247,0.5)' : 'rgba(255,255,255,0.1)';
    }
  });

  // Audio SFX Toggle
  document.getElementById('btn-spatial-toggle-sfx')?.addEventListener('click', () => {
    spatial3DState.audioEnabled = !spatial3DState.audioEnabled;
    const icon = document.getElementById('spatial-sfx-icon');
    const text = document.getElementById('spatial-sfx-text');
    if (spatial3DState.audioEnabled) {
      if (icon) icon.textContent = '\ud83d\udd0a';
      if (text) text.textContent = 'SFX ON';
      triggerSpatialWhooshSound(); // Test feedback
    } else {
      if (icon) icon.textContent = '\ud83d\udd08';
      if (text) text.textContent = 'SFX OFF';
    }
  });

  // Playback Controls
  document.getElementById('btn-spatial-toggle-play')?.addEventListener('click', () => {
    spatial3DState.isPlaying = !spatial3DState.isPlaying;
    const btn = document.getElementById('btn-spatial-toggle-play');
    if (btn) btn.textContent = spatial3DState.isPlaying ? '\u275a\u275a' : '\u25b6';
  });

  document.getElementById('btn-spatial-reset-path')?.addEventListener('click', () => {
    resetSpatialCameraPath();
  });

  // Timeline Slider Scrub
  document.getElementById('spatial-timeline-slider')?.addEventListener('input', (e) => {
    spatial3DState.currentTime = parseFloat(e.target.value) / 100;
    updateSpatialCameraPosition();
    updateSpatialTimelineDisplay();
  });

  // Layer Modal Type Change Handler (shows extra fields for cards)
  document.getElementById('modal-layer-type')?.addEventListener('change', (e) => {
    const extraFields = document.getElementById('modal-layer-extra-card-fields');
    if (extraFields) {
      extraFields.style.display = e.target.value === 'card' ? 'flex' : 'none';
    }
  });

  // Easy Z-slider & Nerds Exact Z input synchronization
  const zSlider = document.getElementById('modal-layer-z-slider');
  const zValDisplay = document.getElementById('modal-layer-z-val');
  const posZInput = document.getElementById('modal-layer-z');

  zSlider?.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value);
    if (zValDisplay) zValDisplay.textContent = Math.round(val);
    if (posZInput) posZInput.value = Math.round(val);
  });

  posZInput?.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value) || 0;
    if (zSlider) zSlider.value = val;
    if (zValDisplay) zValDisplay.textContent = Math.round(val);
  });

  // Scale slider synchronization
  document.getElementById('modal-layer-scale-slider')?.addEventListener('input', (e) => {
    const sVal = document.getElementById('modal-layer-scale-val');
    if (sVal) sVal.textContent = `${parseFloat(e.target.value).toFixed(1)}x`;
  });

  // Quick Color Dots click handler
  document.querySelectorAll('.quick-color-dot').forEach(dot => {
    dot.addEventListener('click', (e) => {
      const col = e.currentTarget.dataset.color;
      const colorInput = document.getElementById('modal-layer-color');
      if (colorInput) colorInput.value = col;
    });
  });

  // Progressive Disclosure Toggle ("For Nerds" panel)
  const btnToggleNerd = document.getElementById('btn-toggle-nerd-mode');
  const nerdPanel = document.getElementById('spatial-nerd-panel');
  const nerdChevron = document.getElementById('nerd-mode-chevron');

  btnToggleNerd?.addEventListener('click', () => {
    if (!nerdPanel) return;
    const isHidden = nerdPanel.style.display === 'none' || !nerdPanel.style.display;
    nerdPanel.style.display = isHidden ? 'flex' : 'none';
    if (nerdChevron) nerdChevron.textContent = isHidden ? '\u25b2' : '\u25bc';
  });

  // Add Layer Modal open/close
  const addModal = document.getElementById('modal-spatial-add-layer');
  document.getElementById('btn-spatial-add-layer')?.addEventListener('click', () => {
    openLayerEditorModal(-1);
  });
  document.getElementById('btn-close-add-layer-modal')?.addEventListener('click', () => {
    if (addModal) addModal.style.display = 'none';
  });
  document.getElementById('btn-cancel-add-layer')?.addEventListener('click', () => {
    if (addModal) addModal.style.display = 'none';
  });

  // Confirm Save / Add Layer
  document.getElementById('btn-confirm-add-layer')?.addEventListener('click', () => {
    const type = document.getElementById('modal-layer-type')?.value || 'text';
    const title = document.getElementById('modal-layer-text')?.value || 'NEW 3D PLANE';
    const subtitle = document.getElementById('modal-layer-subtitle')?.value || '';
    const body = document.getElementById('modal-layer-body')?.value || '';
    const color = document.getElementById('modal-layer-color')?.value || '#f59e0b';
    const z = parseFloat(document.getElementById('modal-layer-z')?.value || document.getElementById('modal-layer-z-slider')?.value || '-2500');
    const x = parseFloat(document.getElementById('modal-layer-x')?.value || '0');
    const y = parseFloat(document.getElementById('modal-layer-y')?.value || '0');
    const scale = parseFloat(document.getElementById('modal-layer-scale-slider')?.value || '1.0');

    const item = {
      id: spatial3DState.editingLayerIndex >= 0 ? (spatial3DState.elements3D[spatial3DState.editingLayerIndex]?.userData?.id || Date.now().toString()) : Date.now().toString(),
      type,
      title,
      subtitle,
      body,
      text: body,
      color,
      x,
      y,
      z,
      scale
    };

    let newMesh = null;
    if (type === 'text') newMesh = createSpatialTextPlane(item);
    else if (type === 'card') newMesh = createSpatialCardPlane(item);
    else if (type === 'code') newMesh = createSpatialCodePlane(item);

    if (newMesh && spatial3DState.scene) {
      if (spatial3DState.editingLayerIndex >= 0 && spatial3DState.elements3D[spatial3DState.editingLayerIndex]) {
        // Replace existing mesh in scene
        const oldMesh = spatial3DState.elements3D[spatial3DState.editingLayerIndex];
        spatial3DState.scene.remove(oldMesh);
        spatial3DState.scene.add(newMesh);
        spatial3DState.elements3D[spatial3DState.editingLayerIndex] = newMesh;
        showTextTimingAlert(`Updated 3D Plane "${title}"!`, 'success');
      } else {
        // Add new mesh
        spatial3DState.scene.add(newMesh);
        spatial3DState.elements3D.push(newMesh);
        showTextTimingAlert(`Created 3D Plane "${title}" at Z: ${Math.round(z)}!`, 'success');
      }
      renderSpatialLayerList();
    }

    if (addModal) addModal.style.display = 'none';
    setTimeout(() => showTextTimingAlert(''), 2500);
  });

  // Apply to Timeline
  document.getElementById('btn-spatial-apply-timeline')?.addEventListener('click', () => {
    closeSpatial3DMotionSuite();
    switchStudioView('editor');

    const firstItem = spatial3DState.elements3D[0]?.userData?.title || 'THE SYSTEM';
    const sampleBg = {
      id: `img-spatial-bg-${Date.now()}`,
      name: 'Regaarder_3D_Spatial_Scene.jpg',
      url: 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=800&auto=format&fit=crop&q=80',
      start: 0,
      duration: 7,
      scale: 1.25,
      zoomEffect: 'snap',
      zoomScale: 1.3
    };
    const sampleTitle = {
      id: `txt-spatial-${Date.now() + 1}`,
      text: firstItem,
      highlight: firstItem.split(' ')[0] || '',
      highlightColor: '#c084fc',
      anim: 'pop',
      fontSize: 70,
      fontFamily: 'Cinzel, serif',
      start: 0,
      duration: 7
    };

    if (timelineClips && timelineClips.image && timelineClips.text) {
      timelineClips.image = [sampleBg];
      timelineClips.text = [sampleTitle];
      renderAllTimelineTracks();
      selectClip(sampleTitle, 'text');
    }

    showTextTimingAlert(`Applied Regaarder 3D Spatial Scene "${firstItem}" to timeline!`, 'success');
    setTimeout(() => showTextTimingAlert(''), 2500);
  });
}

