  docCtx: null,
  quoteCanvas: null,
  quoteCtx: null,
  textureMap: null,
  quoteTextureMap: null,
  animId: null,
  isPlaying: false,
  timelineProgress: 0,
  playbackSpeed: 1.0,
  animTween: null,
  isDraggingCanvas: false,
  dragStartPos: { x: 0, y: 0 },
  dragStartPitch: 30,
