  // Initial category & template renders
  renderHomepageCategories();
  renderHomepageTemplates();
  bindSpatial3DModalControls();
  bindDocument3DFXModalControls();
  bindJaniSuiteModalControls();
  bindCountdownSuiteModalControls();
