// Initialize chart data points
for (let i = 0; i < 50; i++) {
  countdownSuiteState.chartPoints.push(Math.random() * 0.4 + 0.5);
}

function initCountdownAudio() {
  if (countdownSuiteState.audioCtx) return;
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    countdownSuiteState.audioCtx = new AudioCtx();
  } catch (err) {}
}

function playCountdownTick(isUrgent = false) {
  if (!countdownSuiteState.audioEnabled) return;
  initCountdownAudio();
  const ctx = countdownSuiteState.audioCtx;
  if (!ctx) return;
  if (ctx.state === 'suspended') ctx.resume();

  try {
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'square';
    osc.frequency.setValueAtTime(isUrgent ? 520 : 380, now);
    osc.frequency.exponentialRampToValueAtTime(100, now + 0.04);
    gain.gain.setValueAtTime(isUrgent ? 0.35 : 0.2, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.04);
  } catch (err) {}
}

function triggerCountdownClimaxImpact() {
  countdownSuiteState.climaxTriggered = true;
  if (countdownSuiteState.shakeEnabled) {
    countdownSuiteState.shakeAmount = 26;
    countdownSuiteState.flashOpacity = 0.85;
  }
  
  // Audio climax impact
  if (countdownSuiteState.audioEnabled) {
    initCountdownAudio();
    const ctx = countdownSuiteState.audioCtx;
    if (ctx) {
      if (ctx.state === 'suspended') ctx.resume();
      try {
        const now = ctx.currentTime;
        // Deep sub-bass boom
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(120, now);
        osc.frequency.exponentialRampToValueAtTime(30, now + 1.2);
        gain.gain.setValueAtTime(0.8, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 1.2);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now);
        osc.stop(now + 1.2);
      } catch (err) {}
    }
  }

  showCountdownToast("\u26a0\ufe0f SYSTEMIC COLLAPSE CLIMAX TRIGGERED!");
}

function showCountdownToast(msg) {
  const toast = document.getElementById('countdown-toast');
  const txt = document.getElementById('countdown-toast-msg');
  if (!toast || !txt) return;
  txt.textContent = msg;
  toast.style.opacity = '1';
  toast.style.transform = 'translate(-50%, 0px)';
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translate(-50%, 40px)';
  }, 3200);
}

// --- Countdown Suite Asset Management ---
const countdownAssets = {
  bgPlate: null,
  fgPapers: null,
  isLoaded: false
};

function ensureCountdownAssets() {
  if (countdownAssets.isLoaded) return;
  const bg = new Image();
  bg.crossOrigin = 'anonymous';
  bg.src = '/countdown_warroom_clean_bg.png';
  bg.onload = () => { countdownAssets.bgPlate = bg; };
  countdownAssets.bgPlate = bg;

  const fg = new Image();
  fg.crossOrigin = 'anonymous';
  fg.src = '/countdown_warroom_foreground_papers.png';
  fg.onload = () => { countdownAssets.fgPapers = fg; };
  countdownAssets.fgPapers = fg;

  countdownAssets.isLoaded = true;
}

if (typeof window !== 'undefined') {
  ensureCountdownAssets();
}

function drawCountdownBackground(ctx, w, h, progress) {
  ensureCountdownAssets();
  
  // If custom user background image was uploaded / specified
  if (countdownSuiteState.customBgImage && countdownSuiteState.customBgImage.complete) {
    ctx.drawImage(countdownSuiteState.customBgImage, 0, 0, w, h);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, w, h);
  } else if (countdownAssets.bgPlate && countdownAssets.bgPlate.complete && countdownAssets.bgPlate.naturalWidth > 0) {
    // 3D Curved Financial War Room Terminal Screen Environment
    ctx.drawImage(countdownAssets.bgPlate, 0, 0, w, h);
  } else {
    // Fallback radial gradient war room environment
    const bgGrad = ctx.createRadialGradient(w * 0.42, h * 0.5, 40, w * 0.42, h * 0.5, w * 0.8);
    bgGrad.addColorStop(0, '#160609');
    bgGrad.addColorStop(0.55, '#080204');
    bgGrad.addColorStop(1, '#000000');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, w, h);
  }
}

function drawCountdownEffect(ctx, w, h, remainingSec) {
  const mins = Math.floor(remainingSec / 60);
  const secs = Math.floor(remainingSec % 60);
  const millis = Math.floor((remainingSec % 1) * 1000);
  const pad = (n, width = 2) => String(n).padStart(width, '0');

  let timeStr = "";
  if (countdownSuiteState.displayMode === 'tminus') {
    timeStr = `T-MINUS ${pad(mins)}:${pad(secs)}.${pad(millis, 3)}`;
  } else {
    timeStr = `23:${pad(59 - mins)}:${pad(59 - secs)}`;
  }

  // Central Monitor Positioning Geometry
  // The center monitor screen center is at xc = 535
  const xc = 535;
  const progress = Math.max(0, Math.min(1, 1 - (remainingSec / countdownSuiteState.totalDuration)));

  ctx.save();

  // 1. Technical Coordinate Grid on Monitor Screen
  ctx.save();
  ctx.strokeStyle = "rgba(239, 68, 68, 0.07)";
  ctx.lineWidth = 1;
  for (let x = 190; x <= 880; x += 32) {
    ctx.beginPath();
    ctx.moveTo(x, 110);
    ctx.lineTo(x - 8, 615);
    ctx.stroke();
  }
  for (let y = 120; y <= 610; y += 32) {
    ctx.beginPath();
    ctx.moveTo(185, y);
    ctx.lineTo(885, y - 4);
    ctx.stroke();
  }
  ctx.restore();

  // 2. Headline & Tactical HUD Layer: [ FTX LIQUIDITY CRASH ]
  ctx.save();
  ctx.textAlign = 'center';
  ctx.font = "700 23px 'Chakra Petch', 'Inter', -apple-system, sans-serif";
  ctx.fillStyle = "#ffffff";
  ctx.shadowColor = "rgba(255, 255, 255, 0.5)";
  ctx.shadowBlur = 8;
  const titleText = (countdownSuiteState.title || "FTX LIQUIDITY CRASH").toUpperCase();
  ctx.fillText(`[ ${titleText} ]`, xc, 178);
  ctx.restore();

  // 3. Tactile Monospace Countdown Rig inside Clean HUD Box (24px+ padding below headline)
  const boxW = 420;
  const boxH = 54;
  const by0 = 214;
  const textY = by0 + boxH / 2;
  const bx0 = xc - boxW / 2;
  const bx1 = xc + boxW / 2;
  const by1 = by0 + boxH;

  ctx.save();
  // Translucent dark glass box
  ctx.fillStyle = "rgba(12, 3, 5, 0.85)";
  ctx.beginPath();
  if (ctx.roundRect) {
    ctx.roundRect(bx0, by0, boxW, boxH, 8);
  } else {
    ctx.rect(bx0, by0, boxW, boxH);
  }
  ctx.fill();

  // Fine HUD border
  ctx.strokeStyle = "rgba(255, 255, 255, 0.32)";
  ctx.lineWidth = 1.4;
  ctx.stroke();

  // Tactical Corner L-Brackets
  const cl = 9;
  ctx.strokeStyle = "rgba(255, 255, 255, 0.9)";
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(bx0, by0 + cl); ctx.lineTo(bx0, by0); ctx.lineTo(bx0 + cl, by0);
  ctx.moveTo(bx1 - cl, by0); ctx.lineTo(bx1, by0); ctx.lineTo(bx1, by0 + cl);
  ctx.moveTo(bx0, by1 - cl); ctx.lineTo(bx0, by1); ctx.lineTo(bx0 + cl, by1);
  ctx.moveTo(bx1 - cl, by1); ctx.lineTo(bx1, by1); ctx.lineTo(bx1, by1 - cl);
  ctx.stroke();

  // High-Density Monospace Typography with Micro-Chromatic Aberration
  ctx.font = "700 35px 'JetBrains Mono', 'DIN Pro', 'Share Tech Mono', ui-monospace, monospace";
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Red Channel Shift (+1.5px)
  ctx.fillStyle = "rgba(239, 68, 68, 0.85)";
  ctx.fillText(timeStr, xc + 1.5, textY);

  // Cyan Channel Shift (-1.5px)
  ctx.fillStyle = "rgba(56, 189, 248, 0.65)";
  ctx.fillText(timeStr, xc - 1.5, textY);

  // Core Monospace Glow Pass
  if (remainingSec < 3) {
    ctx.fillStyle = "#ff334b";
    ctx.shadowColor = "rgba(255, 51, 75, 0.95)";
    ctx.shadowBlur = 22;
  } else {
    ctx.fillStyle = "#ffffff";
    ctx.shadowColor = "rgba(239, 68, 68, 0.85)";
    ctx.shadowBlur = 14;
  }
  ctx.fillText(timeStr, xc, textY);
  ctx.restore();

  // 4. Volumetric Crimson Gradient Area Chart & Candlestick Drops
  const chartX0 = 210;
  const chartX1 = 865;
  const chartW = chartX1 - chartX0;
  const chartBottom = 524;
  const totalPoints = 50;
  const pts = [];

  for (let i = 0; i < totalPoints; i++) {
    const norm = i / (totalPoints - 1);
    const dropFactor = norm > (1 - progress * 0.85) ? (1 + progress * 2.6) : 1;
    let baseVal = (countdownSuiteState.chartPoints[i] || 0.65) / dropFactor;
    if (progress > 0.65 && norm > 0.5) baseVal += (Math.sin(i * 9.7 + performance.now() * 0.01) * 0.04);
    const px = chartX0 + norm * chartW;
    const py = 285 + (1 - baseVal) * 215;
    pts.push({ x: px, y: Math.max(280, Math.min(chartBottom, py)) });
  }

  // Draw Area Fill with rich crimson gradient
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(chartX0, chartBottom);
  for (let i = 0; i < pts.length; i++) {
    ctx.lineTo(pts[i].x, pts[i].y);
  }
  ctx.lineTo(chartX1, chartBottom);
  ctx.closePath();

  const fillGrad = ctx.createLinearGradient(0, 280, 0, chartBottom);
  fillGrad.addColorStop(0, "rgba(239, 68, 68, 0.78)");
  fillGrad.addColorStop(0.35, "rgba(185, 28, 28, 0.48)");
  fillGrad.addColorStop(0.75, "rgba(69, 10, 10, 0.26)");
  fillGrad.addColorStop(1, "rgba(8, 2, 4, 0.04)");
  ctx.fillStyle = fillGrad;
  ctx.fill();

  // Matrix Digital Data Streams inside Area
  ctx.fillStyle = "rgba(255, 120, 120, 0.16)";
  ctx.font = "10px 'JetBrains Mono', monospace";
  const nowTime = performance.now() * 0.003;
  for (let c = 0; c < 14; c++) {
    const colX = chartX0 + 25 + c * 45;
    const colY = 320 + ((nowTime * 45 + c * 38) % 170);
    ctx.fillText((c % 2 === 0 ? "1" : "0"), colX, colY);
  }

  // Candlestick Markers along the chart
  for (let i = 2; i < pts.length - 2; i += 3) {
    const pt = pts[i];
    const candleH = 14 + (i % 4) * 6;
    const candleW = 5;
    // Wick
    ctx.strokeStyle = "rgba(239, 68, 68, 0.85)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(pt.x, pt.y - 8);
    ctx.lineTo(pt.x, pt.y + candleH + 8);
    ctx.stroke();
    // Body
    ctx.fillStyle = "#dc2626";
    ctx.fillRect(pt.x - candleW / 2, pt.y, candleW, candleH);
  }

  // Key Trigger Drop Nodes (glowing pulsing circles)
  const triggerIndices = [14, 27, 41];
  triggerIndices.forEach(idx => {
    if (idx < pts.length) {
      const tp = pts[idx];
      ctx.save();
      ctx.shadowColor = "#ef4444";
      ctx.shadowBlur = 14;
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.arc(tp.x, tp.y, 4, 0, Math.PI * 2);
      ctx.fill();

      // Pulsing Ring
      const rPulse = 6 + (Math.sin(performance.now() * 0.008 + idx) + 1) * 3;
      ctx.strokeStyle = "rgba(239, 68, 68, 0.85)";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(tp.x, tp.y, rPulse, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
  });

  // Top Neon Glowing Jagged Contour Line
  ctx.beginPath();
  for (let i = 0; i < pts.length; i++) {
    if (i === 0) ctx.moveTo(pts[i].x, pts[i].y);
    else ctx.lineTo(pts[i].x, pts[i].y);
  }
  ctx.strokeStyle = "#ff2a4b";
  ctx.lineWidth = 3.2;
  ctx.shadowColor = "#ef4444";
  ctx.shadowBlur = 14;
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}

function drawCountdownStockTicker(ctx, w, h) {
  if (!countdownSuiteState.tickerEnabled) return;
  const tickerX0 = 195;
  const tickerX1 = 875;
  const tickerW = tickerX1 - tickerX0;
  const tickerY0 = 566;
  const tickerH = 38;

  ctx.save();
  // Clip to the monitor bottom bezel bounds
  ctx.beginPath();
  ctx.rect(tickerX0, tickerY0, tickerW, tickerH);
  ctx.clip();

  // Dark high-contrast background bar
  ctx.fillStyle = "rgba(8, 2, 4, 0.96)";
  ctx.fillRect(tickerX0, tickerY0, tickerW, tickerH);

  // Red top border line
  ctx.strokeStyle = "rgba(239, 68, 68, 0.85)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(tickerX0, tickerY0);
  ctx.lineTo(tickerX1, tickerY0);
  ctx.stroke();

  // Scrolling Marquee offset
  countdownSuiteState.tickerOffset -= 2.2;

  // Render ticker text with bold badges
  const textY = tickerY0 + tickerH / 2 + 4;
  const items = countdownSuiteState.tickerText.split(/[•|]/).map(s => s.trim()).filter(Boolean);

  // Measure full line width
  ctx.font = "700 12px 'JetBrains Mono', 'Share Tech Mono', monospace";
  let blockW = 0;
  const itemWidths = items.map(item => {
    const isBadge = item.includes('-') || item.includes('PAUSED') || item.includes('BANKRUPT');
    const badgeW = ctx.measureText(item).width + (isBadge ? 18 : 10);
    blockW += badgeW + 16;
    return { text: item, isBadge, width: badgeW };
  });

  if (blockW > 0 && Math.abs(countdownSuiteState.tickerOffset) > blockW) {
    countdownSuiteState.tickerOffset = 0;
  }

  // Draw 2 passes for seamless looping
  for (let pass = 0; pass < 2; pass++) {
    let curX = tickerX0 + countdownSuiteState.tickerOffset + pass * (blockW + 40);
    for (let k = 0; k < itemWidths.length; k++) {
      const it = itemWidths[k];
      if (curX + it.width > tickerX0 - 50 && curX < tickerX1 + 50) {
        if (it.isBadge) {
          // Solid Red Pill Badge
          ctx.fillStyle = "#dc2626";
          ctx.beginPath();
          if (ctx.roundRect) {
            ctx.roundRect(curX, tickerY0 + 8, it.width, 22, 4);
          } else {
            ctx.rect(curX, tickerY0 + 8, it.width, 22);
          }
          ctx.fill();

          ctx.fillStyle = "#ffffff";
          ctx.font = "800 11.5px 'JetBrains Mono', monospace";
          ctx.textAlign = 'center';
          ctx.fillText(it.text, curX + it.width / 2, textY);
        } else {
          ctx.fillStyle = "#fca5a5";
          ctx.font = "600 12px 'JetBrains Mono', monospace";
          ctx.textAlign = 'left';
          ctx.fillText(it.text, curX + 4, textY);
        }

        // Separator pipe
        ctx.fillStyle = "rgba(239, 68, 68, 0.6)";
        ctx.fillText("|", curX + it.width + 6, textY);
      }
      curX += it.width + 16;
    }
  }

  ctx.restore();
}

function drawCountdownDramaticSubtitle(ctx, w, h) {
  if (!countdownSuiteState.quote.trim()) return;
  const xc = 535;
  const yc = 542;

  ctx.save();
  ctx.textAlign = 'center';
  ctx.font = "italic 600 13.5px 'Playfair Display', Georgia, serif";
  ctx.fillStyle = "rgba(244, 244, 245, 0.96)";
  ctx.shadowColor = "rgba(0, 0, 0, 0.9)";
  ctx.shadowBlur = 8;
  ctx.fillText(countdownSuiteState.quote, xc, yc);
  ctx.restore();
}

function drawCountdownAtmosphere(ctx, w, h) {
  // 1. Composite Foreground Physical Paper Notes (over monitor bezels)
  if (countdownAssets.fgPapers && countdownAssets.fgPapers.complete && countdownAssets.fgPapers.naturalWidth > 0) {
    ctx.drawImage(countdownAssets.fgPapers, 0, 0, w, h);
  }

  // 2. CRT Scanline Shaders Overlay (opacity 0.08 across the screen)
  if (countdownSuiteState.crtEnabled) {
    ctx.save();
    ctx.fillStyle = "rgba(0, 0, 0, 0.08)";
    for (let y = 110; y < 615; y += 3) {
      ctx.fillRect(190, y, 685, 1.2);
    }
    ctx.restore();
  }

  // 3. Specular Glass Glare Pass across top corners
  ctx.save();
  const glareGrad = ctx.createLinearGradient(195, 110, 360, 260);
  glareGrad.addColorStop(0, "rgba(255, 255, 255, 0.09)");
  glareGrad.addColorStop(0.5, "rgba(255, 255, 255, 0.02)");
  glareGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
  ctx.fillStyle = glareGrad;
  ctx.beginPath();
  ctx.moveTo(195, 115);
  ctx.lineTo(420, 110);
  ctx.lineTo(215, 300);
  ctx.lineTo(190, 250);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // 4. Subtle Vignette Falloff
  const intensity = countdownSuiteState.vignetteIntensity;
  if (intensity > 0) {
    ctx.save();
    const vigGrad = ctx.createRadialGradient(w * 0.42, h * 0.5, w * 0.28, w * 0.42, h * 0.5, w * 0.65);
    vigGrad.addColorStop(0, 'rgba(0,0,0,0)');
    vigGrad.addColorStop(1, `rgba(0,0,0,${intensity * 0.75})`);
    ctx.fillStyle = vigGrad;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }
}

function renderCountdownLoop(now) {
  const canvas = document.getElementById('countdown-studio-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;

  const deltaTime = (now - countdownSuiteState.lastFrameTime) / 1000;
  countdownSuiteState.lastFrameTime = now;

  if (countdownSuiteState.isPlaying) {
    countdownSuiteState.currentTime -= deltaTime;
    if (countdownSuiteState.currentTime <= 0) {
      countdownSuiteState.currentTime = 0;
      countdownSuiteState.isPlaying = false;
      const icon = document.getElementById('countdown-play-icon');
      if (icon) icon.textContent = '\u25b6';
      if (!countdownSuiteState.climaxTriggered) {
        triggerCountdownClimaxImpact();
      }
    }
  }

  // Audio tick rate trigger
  if (countdownSuiteState.isPlaying && countdownSuiteState.currentTime > 0) {
    const secFloor = Math.floor(countdownSuiteState.currentTime);
    if (secFloor !== countdownSuiteState.lastTickSecond) {
      countdownSuiteState.lastTickSecond = secFloor;
      playCountdownTick(countdownSuiteState.currentTime < 3);
    }
  }

  const progress = Math.max(0, Math.min(1, 1 - (countdownSuiteState.currentTime / countdownSuiteState.totalDuration)));

  // Screen shake
  ctx.save();
  if (countdownSuiteState.shakeAmount > 0) {
    const dx = (Math.random() - 0.5) * countdownSuiteState.shakeAmount;
    const dy = (Math.random() - 0.5) * countdownSuiteState.shakeAmount;
    ctx.translate(dx, dy);
    countdownSuiteState.shakeAmount *= 0.9;
  }

  ctx.clearRect(0, 0, w, h);

  drawCountdownBackground(ctx, w, h, progress);
  drawCountdownEffect(ctx, w, h, countdownSuiteState.currentTime);
  drawCountdownStockTicker(ctx, w, h);
  drawCountdownDramaticSubtitle(ctx, w, h);
  drawCountdownAtmosphere(ctx, w, h);

  ctx.restore();

  // Climax red flash
  if (countdownSuiteState.flashOpacity > 0) {
    ctx.fillStyle = `rgba(239, 68, 68, ${countdownSuiteState.flashOpacity})`;
    ctx.fillRect(0, 0, w, h);
    countdownSuiteState.flashOpacity *= 0.88;
  }

  // Update timeline UI
  const pad = (n, width = 2) => String(n).padStart(width, '0');
  const sec = Math.floor(countdownSuiteState.currentTime % 60);
  const ms = Math.floor((countdownSuiteState.currentTime % 1) * 1000);
  const timeReadout = document.getElementById('countdown-time-readout');
  if (timeReadout) timeReadout.textContent = `00:${pad(sec)}:${pad(ms, 3)}`;

  const riserReadout = document.getElementById('countdown-riser-readout');
  if (riserReadout) riserReadout.textContent = `${Math.round(100 + progress * 200)}%`;

  const bar = document.getElementById('countdown-tension-bar');
  if (bar) bar.style.width = `${progress * 100}%`;

  const handle = document.getElementById('countdown-scrubber-handle');
  if (handle) handle.style.left = `${progress * 100}%`;

  const hudFill = document.getElementById('countdown-hud-scrubber-fill');
  if (hudFill) hudFill.style.width = `${progress * 100}%`;

  const hudTime = document.getElementById('countdown-hud-timecode');
  if (hudTime) hudTime.textContent = `00:${pad(sec)}:${pad(ms, 3)}`;

  const hudPlayIcon = document.getElementById('countdown-hud-icon-play');
  const hudPauseIcon = document.getElementById('countdown-hud-icon-pause');
  if (hudPlayIcon && hudPauseIcon) {
    if (countdownSuiteState.isPlaying) {
      hudPlayIcon.style.display = 'none';
      hudPauseIcon.style.display = 'block';
    } else {
      hudPlayIcon.style.display = 'block';
      hudPauseIcon.style.display = 'none';
    }
  }

  countdownSuiteState.animFrameId = requestAnimationFrame(renderCountdownLoop);
}

function openCountdownSuite() {
  ensureCountdownAssets();
  const modal = document.getElementById('modal-countdown-suite');
  if (!modal) return;
  modal.style.display = 'flex';
  countdownSuiteState.isPlaying = true;
  countdownSuiteState.lastFrameTime = performance.now();
  const icon = document.getElementById('countdown-play-icon');
  if (icon) icon.textContent = '\u275a\u275a';
  if (!countdownSuiteState.animFrameId) {
    countdownSuiteState.animFrameId = requestAnimationFrame(renderCountdownLoop);
  }
}

function closeCountdownSuite() {
  const modal = document.getElementById('modal-countdown-suite');
  if (!modal) return;
  modal.style.display = 'none';
  countdownSuiteState.isPlaying = false;
  const icon = document.getElementById('countdown-play-icon');
  if (icon) icon.textContent = '\u25b6';
  if (countdownSuiteState.animFrameId) {
    cancelAnimationFrame(countdownSuiteState.animFrameId);
    countdownSuiteState.animFrameId = null;
  }
}

function bindCountdownSuiteModalControls() {
  document.getElementById('btn-close-countdown-suite')?.addEventListener('click', closeCountdownSuite);

  const toggleCountdownPlay = () => {
    initCountdownAudio();
    countdownSuiteState.isPlaying = !countdownSuiteState.isPlaying;
    const icon = document.getElementById('countdown-play-icon');
    if (icon) icon.textContent = countdownSuiteState.isPlaying ? '\u275a\u275a' : '\u25b6';
    if (countdownSuiteState.currentTime <= 0) {
      countdownSuiteState.currentTime = countdownSuiteState.totalDuration;
      countdownSuiteState.climaxTriggered = false;
    }
  };

  // Play / Pause (Bottom bar & Floating HUD)
  document.getElementById('btn-countdown-play')?.addEventListener('click', toggleCountdownPlay);
  document.getElementById('btn-countdown-hud-play')?.addEventListener('click', (e) => {
    e.stopPropagation();
    toggleCountdownPlay();
  });

  const resetCountdownPlay = () => {
    countdownSuiteState.currentTime = countdownSuiteState.totalDuration;
    countdownSuiteState.climaxTriggered = false;
    countdownSuiteState.isPlaying = true;
    const icon = document.getElementById('countdown-play-icon');
    if (icon) icon.textContent = '\u275a\u275a';
  };

  // Restart / Replay (Bottom bar & Floating HUD)
  document.getElementById('btn-countdown-restart')?.addEventListener('click', resetCountdownPlay);
  document.getElementById('btn-countdown-hud-replay')?.addEventListener('click', (e) => {
    e.stopPropagation();
    resetCountdownPlay();
  });

  // HUD Scrubber Seeking
  const hudScrubWrap = document.getElementById('countdown-hud-scrubber-wrap');
  if (hudScrubWrap) {
    let isHudScrubbing = false;
    const handleHudScrub = (ev) => {
      const rect = hudScrubWrap.getBoundingClientRect();
      const clickX = Math.max(0, Math.min(ev.clientX - rect.left, rect.width));
      const pct = clickX / rect.width;
      countdownSuiteState.currentTime = countdownSuiteState.totalDuration * (1 - pct);
      countdownSuiteState.climaxTriggered = false;
    };
    hudScrubWrap.addEventListener('pointerdown', (ev) => {
      isHudScrubbing = true;
      handleHudScrub(ev);
    });
    window.addEventListener('pointermove', (ev) => {
      if (isHudScrubbing) handleHudScrub(ev);
    });
    window.addEventListener('pointerup', () => {
      isHudScrubbing = false;
    });
  }

  // Trigger Climax
  document.getElementById('btn-countdown-trigger-climax')?.addEventListener('click', () => {
    countdownSuiteState.currentTime = 0;
    triggerCountdownClimaxImpact();
  });

  // Audio Toggle
  document.getElementById('btn-countdown-audio-toggle')?.addEventListener('click', () => {
    countdownSuiteState.audioEnabled = !countdownSuiteState.audioEnabled;
    const txt = document.getElementById('countdown-audio-text');
    const icn = document.getElementById('countdown-audio-icon');
    if (countdownSuiteState.audioEnabled) {
      if (txt) txt.textContent = 'Audio FX On';
      if (icn) icn.textContent = '\ud83d\udd0a';
      playCountdownTick(false);
    } else {
      if (txt) txt.textContent = 'Audio FX Muted';
      if (icn) icn.textContent = '\ud83d\udd07';
    }
  });

  // Scenario Presets Switcher
  document.getElementById('countdown-preset-select')?.addEventListener('change', (e) => {
    const p = COUNTDOWN_PRESETS[e.target.value];
    if (p) {
      countdownSuiteState.title = p.title;
      countdownSuiteState.totalDuration = p.duration;
      countdownSuiteState.currentTime = p.duration;
      countdownSuiteState.tickerText = p.ticker;
      countdownSuiteState.quote = p.quote;
      countdownSuiteState.stylePreset = p.style;
      countdownSuiteState.climaxTriggered = false;

      // Sync input fields
      const inTitle = document.getElementById('countdown-input-title');
      const inQuote = document.getElementById('countdown-input-quote');
      const inTicker = document.getElementById('countdown-input-ticker');
      const inStyle = document.getElementById('countdown-select-style');
      const durSlider = document.getElementById('countdown-slider-duration');
      const durVal = document.getElementById('countdown-val-duration');

      if (inTitle) inTitle.value = p.title;
      if (inQuote) inQuote.value = p.quote;
      if (inTicker) inTicker.value = p.ticker;
      if (inStyle) inStyle.value = p.style;
      if (durSlider) durSlider.value = p.duration;
      if (durVal) durVal.textContent = `${p.duration}s`;

      showCountdownToast(`Loaded: ${p.title}`);
    }
  });

  // Text Inputs Live Sync
  document.getElementById('countdown-input-title')?.addEventListener('input', (e) => {
    countdownSuiteState.title = e.target.value;
  });

  document.getElementById('countdown-input-quote')?.addEventListener('input', (e) => {
    countdownSuiteState.quote = e.target.value;
  });

  document.getElementById('countdown-input-ticker')?.addEventListener('input', (e) => {
    countdownSuiteState.tickerText = e.target.value;
  });

  document.getElementById('countdown-check-ticker')?.addEventListener('change', (e) => {
    countdownSuiteState.tickerEnabled = e.target.checked;
  });

  // Custom Background Image Upload / URL
  document.getElementById('countdown-upload-bg-input')?.addEventListener('change', (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const img = new Image();
      img.onload = () => {
        countdownSuiteState.customBgImage = img;
        const urlInput = document.getElementById('countdown-input-bg-url');
        if (urlInput) urlInput.value = `[Uploaded: ${file.name}]`;
        showCountdownToast('Custom background photo loaded!');
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  });

  document.getElementById('countdown-input-bg-url')?.addEventListener('input', (e) => {
    const url = e.target.value.trim();
    if (url) {
      const img = new Image();
      img.onload = () => {
        countdownSuiteState.customBgImage = img;
        showCountdownToast('Loaded background image from URL');
      };
      img.src = url;
    }
  });

  document.getElementById('btn-countdown-clear-bg')?.addEventListener('click', () => {
    countdownSuiteState.customBgImage = null;
    const urlInput = document.getElementById('countdown-input-bg-url');
    if (urlInput) urlInput.value = '';
    showCountdownToast('Cleared custom background');
  });

  // Duration Slider
  document.getElementById('countdown-slider-duration')?.addEventListener('input', (e) => {
    countdownSuiteState.totalDuration = parseInt(e.target.value) || 10;
    countdownSuiteState.currentTime = countdownSuiteState.totalDuration;
    const lbl = document.getElementById('countdown-val-duration');
    if (lbl) lbl.textContent = `${countdownSuiteState.totalDuration}s`;
  });

  // Mode Buttons
  document.querySelectorAll('.btn-countdown-mode').forEach(btn => {
    btn.addEventListener('click', (e) => {
      document.querySelectorAll('.btn-countdown-mode').forEach(b => {
        b.style.background = '#18181b';
        b.style.borderColor = 'rgba(255,255,255,0.08)';
        b.style.color = '#a1a1aa';
      });
      e.currentTarget.style.background = 'rgba(239, 68, 68, 0.2)';
      e.currentTarget.style.borderColor = '#ef4444';
      e.currentTarget.style.color = '#f87171';
      countdownSuiteState.displayMode = e.currentTarget.dataset.mode;
    });
  });

  // Style Preset Selector
  document.getElementById('countdown-select-style')?.addEventListener('change', (e) => {
    countdownSuiteState.stylePreset = e.target.value;
  });

  // Vignette Slider
  document.getElementById('countdown-slider-vignette')?.addEventListener('input', (e) => {
    const val = parseInt(e.target.value) || 80;
    countdownSuiteState.vignetteIntensity = val / 100;
    const lbl = document.getElementById('countdown-val-vignette');
    if (lbl) lbl.textContent = `${val}%`;
  });

  // CRT Scanlines & Screen Shake Toggles
  document.getElementById('countdown-check-crt')?.addEventListener('change', (e) => {
    countdownSuiteState.crtEnabled = e.target.checked;
  });

  document.getElementById('countdown-check-shake')?.addEventListener('change', (e) => {
    countdownSuiteState.shakeEnabled = e.target.checked;
  });

  // Timeline Scrubber Track Click & Drag
  const scrubTrack = document.getElementById('countdown-timeline-track');
  if (scrubTrack) {
    let isScrubbing = false;
    const handleScrub = (ev) => {
      const rect = scrubTrack.getBoundingClientRect();
      const clickX = Math.max(0, Math.min(ev.clientX - rect.left, rect.width));
      const pct = clickX / rect.width;
      countdownSuiteState.currentTime = countdownSuiteState.totalDuration * (1 - pct);
      countdownSuiteState.climaxTriggered = false;
    };
    scrubTrack.addEventListener('pointerdown', (ev) => {
      isScrubbing = true;
      handleScrub(ev);
    });
    window.addEventListener('pointermove', (ev) => {
      if (isScrubbing) handleScrub(ev);
    });
    window.addEventListener('pointerup', () => {
      isScrubbing = false;
    });
  }

  // Apply to Active Timeline
  document.getElementById('btn-countdown-apply-timeline')?.addEventListener('click', () => {
    closeCountdownSuite();
    switchStudioView('editor');

    const countdownBg = {
      id: `img-countdown-${Date.now()}`,
      name: 'James_Jani_Countdown_Panic.jpg',
      url: 'https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=800&auto=format&fit=crop&q=80',
      start: 0,
      duration: countdownSuiteState.totalDuration,
      scale: 1.15,
      zoomEffect: 'snap',
      zoomScale: 1.3
    };

    const countdownTitle = {
      id: `txt-countdown-title-${Date.now() + 1}`,
      text: countdownSuiteState.title,
      highlight: countdownSuiteState.title.split(' ')[0] || '',
      highlightColor: '#ef4444',
      anim: 'pop',
      fontSize: 56,
      fontFamily: 'Chakra Petch, sans-serif',
      start: 0,
      duration: countdownSuiteState.totalDuration
    };

    const countdownQuote = {
      id: `txt-countdown-quote-${Date.now() + 2}`,
      text: countdownSuiteState.quote,
      highlight: '',
      highlightColor: '#f59e0b',
      anim: 'fade',
      fontSize: 26,
      fontFamily: 'Playfair Display, serif',
      start: 0.5,
      duration: countdownSuiteState.totalDuration - 0.5
    };

    if (timelineClips && timelineClips.image && timelineClips.text) {
      timelineClips.image = [countdownBg];
      timelineClips.text = [countdownTitle, countdownQuote];
      renderAllTimelineTracks();
      selectClip(countdownTitle, 'text');
    }

    showTextTimingAlert('Applied James Jani Countdown Effect to timeline!', 'success');
    setTimeout(() => showTextTimingAlert(''), 2500);
  });
}

/* =========================================================
   JAMES JANI FX ENGINE: NONLINEAR FLASHBACKS CONTROLLER
   ========================================================= */
let flashbackSuiteState = {
  isPlaying: false,
  currentTime: 1.4,
  duration: 10.0,
  flashDuration: 350,
  blurAngle: 45,
  blurMagnitude: 28,
  colorGrade: 'bw',
  timeShiftMode: 'flashback', // 'flashback' or 'flashforward'
  isFlashing: false,
  headline: 'THE 2008 CRASH',
  subcaption: 'FLASHBACK: 15 YEARS PRIOR',
  imageUrl: 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=800&auto=format&fit=crop&q=80',
  animFrameId: null,
  lastTime: performance.now()
};

const FLASHBACK_STOCK_IMAGES = [
  'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=800&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=800&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?w=800&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=800&auto=format&fit=crop&q=80'
];

function playFlashbackAudioSFX(type = 'flash') {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    if (type === 'flash') {
      // Whoosh high-pass sweep + impact pop
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(800, now);
      osc.frequency.exponentialRampToValueAtTime(120, now + 0.25);
      gain.gain.setValueAtTime(0.5, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.25);
    }
  } catch (err) {}
}

function triggerTemporalShift(mode) {
  flashbackSuiteState.timeShiftMode = mode;
  flashbackSuiteState.isFlashing = true;
  playFlashbackAudioSFX('flash');

  const flashEl = document.getElementById('flashback-flash-cut');
  const flashTag = document.getElementById('flashback-flash-tag');
  const bgImg = document.getElementById('flashback-canvas-img');
  const hudStatus = document.getElementById('flashback-hud-status');

  if (flashTag) {
    flashTag.textContent = mode === 'flashback' ? '\u26a1 TIME SHIFT: FLASHBACK (-10Y)' : '\u26a1 TIME SHIFT: FLASHFORWARD (+5Y)';
  }

  if (flashEl) {
    flashEl.style.opacity = '1';
  }

  if (hudStatus) {
    hudStatus.textContent = mode === 'flashback' ? 'STATE: MEMORY ARCHIVE' : 'STATE: FUTURE PROJECTION';
  }

  // Apply color grade and blur
  updateFlashbackVisualStyles();

  setTimeout(() => {
    if (flashEl) flashEl.style.opacity = '0';
    flashbackSuiteState.isFlashing = false;
  }, flashbackSuiteState.flashDuration);

  showTextTimingAlert(mode === 'flashback' ? '\u26a1 Triggered Flashback (-10 Years)' : '\u26a1 Triggered Flashforward (+5 Years)', 'info');
  setTimeout(() => showTextTimingAlert(''), 2000);
}

function updateFlashbackVisualStyles() {
  const bgImg = document.getElementById('flashback-canvas-img');
  if (!bgImg) return;

  const mode = flashbackSuiteState.timeShiftMode;
  const grade = flashbackSuiteState.colorGrade;
  let filterStr = '';

  if (grade === 'bw') {
    filterStr = 'grayscale(100%) contrast(150%) brightness(0.9)';
  } else if (grade === 'cyan') {
    filterStr = 'hue-rotate(180deg) saturate(180%) contrast(120%)';
  } else {
    filterStr = 'sepia(80%) contrast(140%) brightness(0.95)';
  }

  if (flashbackSuiteState.isFlashing) {
    filterStr += ` blur(${flashbackSuiteState.blurMagnitude}px)`;
  }

  bgImg.style.filter = filterStr;
}

function renderFlashbackLoop(now) {
  const delta = (now - flashbackSuiteState.lastTime) / 1000;
  flashbackSuiteState.lastTime = now;

  if (flashbackSuiteState.isPlaying) {
    flashbackSuiteState.currentTime += delta;
    if (flashbackSuiteState.currentTime >= flashbackSuiteState.duration) {
      flashbackSuiteState.currentTime = 0;
    }
  }

  // Update readouts
  const pad = (n, w = 2) => String(n).padStart(w, '0');
  const curSec = Math.floor(flashbackSuiteState.currentTime);
  const curMs = Math.floor((flashbackSuiteState.currentTime % 1) * 100);
  const durSec = Math.floor(flashbackSuiteState.duration);
  const durMs = Math.floor((flashbackSuiteState.duration % 1) * 100);

  const tReadout = document.getElementById('flashback-time-readout');
  if (tReadout) {
    tReadout.textContent = `00:${pad(curSec)}.${pad(curMs)} / 00:${pad(durSec)}.${pad(durMs)}`;
  }

  const pReadout = document.getElementById('flashback-playhead-readout');
  if (pReadout) {
    pReadout.textContent = `PLAYHEAD: 00:${pad(curSec)}.${pad(curMs)}`;
  }

  const needle = document.getElementById('flashback-playhead-needle');
  if (needle) {
    needle.style.left = `${(flashbackSuiteState.currentTime / flashbackSuiteState.duration) * 88 + 6}%`;
  }

  flashbackSuiteState.animFrameId = requestAnimationFrame(renderFlashbackLoop);
}

function openFlashbackSuite() {
  const modal = document.getElementById('modal-flashback-suite');
  if (!modal) return;
  modal.style.display = 'flex';
  flashbackSuiteState.isPlaying = true;
  flashbackSuiteState.lastTime = performance.now();
  const icon = document.getElementById('flashback-play-icon');
  if (icon) icon.textContent = '\u275a\u275a';
  updateFlashbackVisualStyles();
  if (!flashbackSuiteState.animFrameId) {
    flashbackSuiteState.animFrameId = requestAnimationFrame(renderFlashbackLoop);
  }
}

function closeFlashbackSuite() {
  const modal = document.getElementById('modal-flashback-suite');
  if (!modal) return;
  modal.style.display = 'none';
  flashbackSuiteState.isPlaying = false;
  const icon = document.getElementById('flashback-play-icon');
  if (icon) icon.textContent = '\u25b6';
  if (flashbackSuiteState.animFrameId) {
    cancelAnimationFrame(flashbackSuiteState.animFrameId);
    flashbackSuiteState.animFrameId = null;
  }
}

function bindFlashbackSuiteModalControls() {
  document.getElementById('btn-close-flashback-suite')?.addEventListener('click', closeFlashbackSuite);

  // Play / Pause
  document.getElementById('btn-flashback-play')?.addEventListener('click', () => {
    flashbackSuiteState.isPlaying = !flashbackSuiteState.isPlaying;
    const icon = document.getElementById('flashback-play-icon');
    if (icon) icon.textContent = flashbackSuiteState.isPlaying ? '\u275a\u275a' : '\u25b6';
  });

  // Jump triggers
  document.getElementById('btn-flashback-jump-past')?.addEventListener('click', () => triggerTemporalShift('flashback'));
  document.getElementById('btn-flashback-trigger-past')?.addEventListener('click', () => triggerTemporalShift('flashback'));
  document.getElementById('btn-flashback-jump-future')?.addEventListener('click', () => triggerTemporalShift('flashforward'));
  document.getElementById('btn-flashback-trigger-future')?.addEventListener('click', () => triggerTemporalShift('flashforward'));

  // Text inputs
  document.getElementById('flashback-input-headline')?.addEventListener('input', (e) => {
    flashbackSuiteState.headline = e.target.value;
    const h = document.getElementById('flashback-display-headline');
    if (h) h.textContent = e.target.value.toUpperCase();
  });

  document.getElementById('flashback-input-subcaption')?.addEventListener('input', (e) => {
    flashbackSuiteState.subcaption = e.target.value;
    const s = document.getElementById('flashback-display-subcaption');
    if (s) s.textContent = e.target.value.toUpperCase();
  });

  // Image editing (URL input)
  document.getElementById('flashback-input-img-url')?.addEventListener('input', (e) => {
    const url = e.target.value.trim();
    if (url) {
      flashbackSuiteState.imageUrl = url;
      const img = document.getElementById('flashback-canvas-img');
      if (img) img.src = url;
    }
  });

  // Upload custom photo
  document.getElementById('flashback-upload-file-input')?.addEventListener('change', (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      flashbackSuiteState.imageUrl = ev.target.result;
      const img = document.getElementById('flashback-canvas-img');
      if (img) img.src = ev.target.result;
      const urlInput = document.getElementById('flashback-input-img-url');
      if (urlInput) urlInput.value = `[Uploaded: ${file.name}]`;
      playFlashbackAudioSFX('flash');
      showTextTimingAlert(`Uploaded custom archival photo: ${file.name}`, 'success');
      setTimeout(() => showTextTimingAlert(''), 2500);
    };
    reader.readAsDataURL(file);
  });

  // Shuffle stock photo
  document.getElementById('btn-flashback-shuffle-img')?.addEventListener('click', () => {
    const nextImg = FLASHBACK_STOCK_IMAGES[Math.floor(Math.random() * FLASHBACK_STOCK_IMAGES.length)];
    flashbackSuiteState.imageUrl = nextImg;
    const img = document.getElementById('flashback-canvas-img');
    if (img) img.src = nextImg;
    const urlInput = document.getElementById('flashback-input-img-url');
    if (urlInput) urlInput.value = nextImg;
    playFlashbackAudioSFX('flash');
  });

  // Flash duration slider
  document.getElementById('flashback-slider-duration')?.addEventListener('input', (e) => {
    flashbackSuiteState.flashDuration = parseInt(e.target.value) || 350;
    const lbl = document.getElementById('flashback-val-duration');
    if (lbl) lbl.textContent = `${flashbackSuiteState.flashDuration}ms`;
  });

  // Motion blur slider
  document.getElementById('flashback-slider-blur')?.addEventListener('input', (e) => {
    flashbackSuiteState.blurMagnitude = parseInt(e.target.value) || 28;
    const lbl = document.getElementById('flashback-val-blur');
    if (lbl) lbl.textContent = `${flashbackSuiteState.blurMagnitude}px`;
  });

  // Color grade select
  document.getElementById('flashback-select-grade')?.addEventListener('change', (e) => {
    flashbackSuiteState.colorGrade = e.target.value;
    updateFlashbackVisualStyles();
  });

  // Apply to Active Timeline
  document.getElementById('btn-flashback-apply-timeline')?.addEventListener('click', () => {
    closeFlashbackSuite();
    switchStudioView('editor');

    const flashbackClip = {
      id: `img-flashback-${Date.now()}`,
      name: 'Nonlinear_Flashback_Scene.jpg',
      url: flashbackSuiteState.imageUrl,
      start: 0,
      duration: 6,
      scale: 1.15,
      zoomEffect: 'snap',
      zoomScale: 1.25,
      transition: 'fly_through',
      transitionDuration: flashbackSuiteState.flashDuration / 1000
    };

    const headlineClip = {
      id: `txt-flashback-headline-${Date.now() + 1}`,
      text: flashbackSuiteState.headline,
      highlight: flashbackSuiteState.headline.split(' ')[0] || '',
      highlightColor: '#fbbf24',
      anim: 'pop',
      fontSize: 56,
      fontFamily: 'Inter, sans-serif',
      start: 0,
      duration: 6
    };

    const subcaptionClip = {
      id: `txt-flashback-sub-${Date.now() + 2}`,
      text: flashbackSuiteState.subcaption,
      highlight: '',
      highlightColor: '#c084fc',
      anim: 'fade',
      fontSize: 24,
      fontFamily: 'monospace',
      start: 0.2,
      duration: 5.8
    };

    if (timelineClips && timelineClips.image && timelineClips.text) {
      timelineClips.image = [flashbackClip];
      timelineClips.text = [headlineClip, subcaptionClip];
      renderAllTimelineTracks();
      selectClip(headlineClip, 'text');
    }

    showTextTimingAlert('Applied Nonlinear Flashback Suite to timeline!', 'success');
    setTimeout(() => showTextTimingAlert(''), 2500);
  });
}

