function bpEaseOutCubic(x) {
  const c = Math.max(0, Math.min(1, x));
  return 1 - Math.pow(1 - c, 3);
}

function bpEaseInCubic(x) {
  const c = Math.max(0, Math.min(1, x));
  return c * c * c;
}

function bpEaseInOutCubic(x) {
  const c = Math.max(0, Math.min(1, x));
  return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
}

function bpHexToRgba(hex, alpha) {
  let c = (hex || '#ffffff').replace('#', '');
  if (c.length === 3) c = c[0]+c[0]+c[1]+c[1]+c[2]+c[2];
  const num = parseInt(c, 16) || 0;
  const r = (num >> 16) & 255;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha.toFixed(2)})`;
}

function bpComputeCutoutGlowFilter(colorHex, intensityPercent, isDeskCutout) {
  if (isDeskCutout) {
    if (intensityPercent <= 0) return 'drop-shadow(0 14px 28px rgba(0,0,0,0.65))';
    const a1 = (intensityPercent / 100) * 0.9;
    const a2 = (intensityPercent / 100) * 0.55;
    const r1 = Math.round(12 * (intensityPercent / 100));
    const r2 = Math.round(28 * (intensityPercent / 100));
    return `drop-shadow(0 0 ${r1}px ${bpHexToRgba(colorHex, a1)}) drop-shadow(0 0 ${r2}px ${bpHexToRgba(colorHex, a2)}) drop-shadow(0 14px 28px rgba(0,0,0,0.65))`;
  }
  if (intensityPercent <= 0) {
    return 'drop-shadow(0 8px 16px rgba(0,0,0,0.5))';
  }
  const a1 = Math.min(1, (intensityPercent / 100) * 1.1);
  const a2 = (intensityPercent / 100) * 0.65;
  const r1 = Math.round(14 * (intensityPercent / 100));
  const r2 = Math.round(36 * (intensityPercent / 100));
  return `drop-shadow(0 0 ${r1}px ${bpHexToRgba(colorHex, a1)}) drop-shadow(0 0 ${r2}px ${bpHexToRgba(colorHex, a2)})`;
}

function bpFormatAnimLabel(inAnim, outAnim) {
  const map = {
    left_to_right: "Left→Right",
    bottom_to_up: "Bottom→Up",
    right_to_left: "Right→Left",
    top_to_down: "Top→Down",
    scale_pop: "Scale Pop",
    fade_out: "Fade Out"
  };
  return `In: ${map[inAnim] || inAnim} • Out: ${map[outAnim] || outAnim}`;
}

function computeGranularCutoutTransform(playhead, inTime, outTime, inAnim, outAnim) {
  const inDur = 0.48;
  const outDur = 0.48;
  let tx = 0;
  let ty = 0;
  let scale = 1;
  let opacity = 1;

  // Entrance Phase (Smooth Cubic Glide — zero jitter/shaking)
  if (playhead < inTime) {
    opacity = 0;
    if (inAnim === "left_to_right") tx = -125;
    else if (inAnim === "bottom_to_up") ty = 105;
    else if (inAnim === "right_to_left") tx = 125;
    else if (inAnim === "scale_pop") scale = 0.72;
  } else if (playhead < inTime + inDur) {
    const p = bpEaseOutCubic((playhead - inTime) / inDur);
    opacity = Math.min(1, p * 1.35);
    if (inAnim === "left_to_right") tx = (1 - p) * -125;
    else if (inAnim === "bottom_to_up") ty = (1 - p) * 105;
    else if (inAnim === "right_to_left") tx = (1 - p) * 125;
    else if (inAnim === "scale_pop") scale = 0.72 + 0.28 * p;
  }

  // Exit Phase (Smooth Cubic Glide with millisecond stagger)
  if (playhead >= outTime) {
    const q = bpEaseInCubic((playhead - outTime) / outDur);
    opacity *= Math.max(0, 1 - q * 1.15);
    if (outAnim === "right_to_left") tx += -160 * q;
    else if (outAnim === "left_to_right") tx += 160 * q;
    else if (outAnim === "top_to_down") ty += 105 * q;
    else if (outAnim === "fade_out") scale *= (1 - 0.08 * q);
  }

  return {
    transform: `translate3d(${tx.toFixed(2)}%, ${ty.toFixed(2)}%, 0) scale(${scale.toFixed(3)})`,
    opacity: Math.max(0, Math.min(1, opacity)).toFixed(3)
  };
}

function renderWavyKineticSpans(containerEl, text, progress, isWavyMode) {
  if (!containerEl) return;
  if (containerEl.getAttribute('data-raw-text') !== text) {
    containerEl.setAttribute('data-raw-text', text);
    containerEl.innerHTML = '';
    const chars = Array.from(text);
    chars.forEach((ch, idx) => {
      const span = document.createElement('span');
      span.textContent = ch === ' ' ? ' ' : ch;
      span.style.display = 'inline-block';
      span.style.willChange = 'transform, opacity';
      span.setAttribute('data-ch-idx', idx);
      containerEl.appendChild(span);
    });
  }
  const spans = containerEl.children;
  const total = spans.length || 1;
  for (let i = 0; i < spans.length; i++) {
    const sp = spans[i];
    if (!isWavyMode) {
      // Line 1: Crisp left-to-right staggered slide/reveal
      const charDelay = (i / total) * 0.35;
      const localP = bpEaseOutCubic((progress - charDelay) / 0.65);
      const tx = (1 - localP) * 18;
      sp.style.opacity = localP.toFixed(3);
      sp.style.transform = `translate3d(${tx.toFixed(1)}px, 0px, 0)`;
    } else {
      // Line 2: Wavy form up (Screenshots 4 & 5: "ON THE" up first while "INTERNET." rises up in a wave)
      const charDelay = (i / total) * 0.52;
      const rawLocal = Math.max(0, Math.min(1, (progress - charDelay) / 0.48));
      const easeP = bpEaseOutCubic(rawLocal);
      // Wave crest as character rises from bottom -> up
      const waveCrest = Math.sin(rawLocal * Math.PI) * -6;
      const ty = (1 - easeP) * 34 + (rawLocal < 1 ? waveCrest : 0);
      sp.style.opacity = Math.min(1, rawLocal * 1.6).toFixed(3);
      sp.style.transform = `translate3d(0px, ${ty.toFixed(1)}px, 0)`;
    }
  }
}

// Renders Scene 3 ("FOR ALMOST NOTHING."):
// 1) Words appear one after the other in a wavy form (Image 3: "NOTHING" dipped lower in a wave while "FOR ALMOST" is higher)
// 2) Then the wave flattens out so all words sit on a crisp horizontal line and the trailing period "." snaps in (Image 4)
function renderGlobeWavyHeadlineSpans(containerEl, rawText, elapsedSec) {
  if (!containerEl) return;
  const cleanText = (rawText || 'FOR ALMOST NOTHING.').trim();
  const hasDot = cleanText.endsWith('.');
  const coreText = hasDot ? cleanText.slice(0, -1) : cleanText;
  const words = coreText.split(/\s+/).filter(Boolean);

  const cacheKey = cleanText + '__v1';
  if (containerEl.getAttribute('data-globe-raw') !== cacheKey) {
    containerEl.setAttribute('data-globe-raw', cacheKey);
    containerEl.innerHTML = '';
    words.forEach((word, wIdx) => {
      const wSpan = document.createElement('span');
      wSpan.setAttribute('data-word-idx', String(wIdx));
      wSpan.style.display = 'inline-block';
      wSpan.style.willChange = 'transform, opacity';
      Array.from(word).forEach((ch, cIdx) => {
        const cSpan = document.createElement('span');
        cSpan.setAttribute('data-char-idx', String(cIdx));
        cSpan.style.display = 'inline-block';
        cSpan.style.willChange = 'transform, opacity';
        cSpan.textContent = ch;
        wSpan.appendChild(cSpan);
      });
      containerEl.appendChild(wSpan);
      if (wIdx < words.length - 1) {
        const spaceSpan = document.createElement('span');
        spaceSpan.style.display = 'inline-block';
        spaceSpan.innerHTML = '&nbsp;';
        containerEl.appendChild(spaceSpan);
      }
    });
    if (hasDot) {
      const dotSpan = document.createElement('span');
      dotSpan.setAttribute('data-globe-dot', '1');
      dotSpan.style.display = 'inline-block';
      dotSpan.style.willChange = 'transform, opacity';
      dotSpan.textContent = '.';
      containerEl.appendChild(dotSpan);
    }
  }

  // Timeline inside Scene 3 text reveal (elapsedSec starts at 0 when text begins):
  // 0.00s -> 1.15s: Words appear one after the other in wavy form (Image 3)
  // 1.15s -> 1.65s: Wave flattens out smoothly to 0 offset (Image 4)
  // 1.45s -> 1.70s: Trailing period "." appears as the line stabilizes flat (Image 4)
  const flattenProg = bpEaseInOutCubic((elapsedSec - 1.10) / 0.52);
  const waveAmp = 1.0 - flattenProg;

  const wordEls = containerEl.querySelectorAll('[data-word-idx]');
  const totalWords = wordEls.length || 1;
  let globalCharIdx = 0;

  wordEls.forEach((wEl, wIdx) => {
    const wordStart = wIdx * 0.28;
    const wProg = bpEaseOutCubic((elapsedSec - wordStart) / 0.36);
    wEl.style.opacity = Math.min(1, wProg * 1.5).toFixed(3);

    // In Image 3, each successive word steps into a wave trough/crest before flattening in Image 4:
    // Word 0 ("FOR"): slightly high, Word 1 ("ALMOST"): mid-high, Word 2 ("NOTHING"): noticeably lower (+12px dip)
    const wordWaveOffset = (wIdx === totalWords - 1 && totalWords >= 2) ? 11.0 : (wIdx * 3.0 - 2.0);

    const charEls = wEl.querySelectorAll('[data-char-idx]');
    charEls.forEach((cEl, cIdx) => {
      const charDelay = wordStart + cIdx * 0.035;
      const cProg = bpEaseOutCubic((elapsedSec - charDelay) / 0.32);
      const entryRise = (1 - cProg) * 20;
      const charWave = Math.sin(globalCharIdx * 0.55 - elapsedSec * 4.2) * 4.5;
      const ty = entryRise + (wordWaveOffset + charWave) * waveAmp;
      cEl.style.transform = `translate3d(0px, ${ty.toFixed(1)}px, 0)`;
      globalCharIdx++;
    });
  });

  const dotEl = containerEl.querySelector('[data-globe-dot="1"]');
  if (dotEl) {
    // Dot appears right as the wave flattens (Image 3 has no dot yet; Image 4 has the flat text + dot!)
    const dotProg = bpEaseOutCubic((elapsedSec - 1.38) / 0.25);
    dotEl.style.opacity = dotProg.toFixed(3);
    dotEl.style.transform = `translate3d(0px, ${((1 - dotProg) * 10).toFixed(1)}px, 0) scale(${(0.5 + 0.5 * dotProg).toFixed(2)})`;
  }
}

function updateMagnatesBPVisualStyles() {
  const headlineEl = document.getElementById('magnates-bp-headline');
  const subcaptionEl = document.getElementById('magnates-bp-subcaption');
  const primaryImg = document.getElementById('magnates-bp-img-primary');
  const secondaryImg = document.getElementById('magnates-bp-img-secondary');
  const logoLayer = document.getElementById('magnates-bp-layer-logo');
  const logoImg = document.getElementById('magnates-bp-img-logo');
  const wavyWrap = document.getElementById('magnates-bp-wavy-wrap');
  const wavyLine1El = document.getElementById('magnates-bp-wavy-line1');
  const wavyLine2El = document.getElementById('magnates-bp-wavy-line2');
  const bgWrap = document.getElementById('magnates-bp-bg-wrap');
  const crimsonBg = document.getElementById('magnates-bp-crimson-bg');
  const bgPlateImg = document.getElementById('magnates-bp-bg-plate');
  const primaryLayer = document.getElementById('magnates-bp-layer-primary');
  const secondaryLayer = document.getElementById('magnates-bp-layer-secondary');
  const gridLayer = document.getElementById('magnates-bp-grid-layer');
  const textWrap = document.getElementById('magnates-bp-text-wrap');
  const timerEl = document.getElementById('magnates-bp-timer-display');
  const hudTimecode = document.getElementById('magnates-bp-hud-timecode');
  const scrubberFill = document.getElementById('magnates-bp-scrubber-fill');
  const hudPreset = document.getElementById('magnates-bp-hud-preset');
  const hudAnim = document.getElementById('magnates-bp-hud-anim');
  const activeLayerPill = document.getElementById('magnates-bp-hud-active-layer-pill');
  const layerCountBadge = document.getElementById('magnates-bp-layer-count-badge');

  const p = magnatesBPState.playhead;
  const dur = magnatesBPState.duration;
  const isFullFlow = magnatesBPState.preset === 'full_story_flow';
  const isBrandOnly = magnatesBPState.preset === 'brand_wavy_intro';
  const isProductsOnly = magnatesBPState.preset === 'products_unfurl';
  const isGlobeOnly = magnatesBPState.preset === 'globe_wavy_nothing';
  const isRoomScene = magnatesBPState.preset === 'room_spawn';
  const hasProductsPhase = isProductsOnly || isGlobeOnly || (isFullFlow && Boolean(magnatesBPState.productsEnabled));
  const hasGlobePhase = isGlobeOnly || (isFullFlow && Boolean(magnatesBPState.globeEnabled !== false));

  const tShiftRight = isProductsOnly ? 0.35 : (isGlobeOnly ? -2.5 : (magnatesBPState.logoShiftRightTime ?? 3.10));
  const unfurlDur = magnatesBPState.unfurlSpeed ?? 0.45;
  // When Scene 2 finishes, the Products + Price tags + Logo move UP as a whole at tOut while the Globe rises from bottom!
  const tOut = isProductsOnly
    ? 4.25
    : (isGlobeOnly ? 0.15 : (hasProductsPhase ? Math.max(6.40, tShiftRight + 3.20) : (magnatesBPState.logoOutTime ?? 4.15)));
  const tGlobeStart = isGlobeOnly ? 0.15 : (tOut + 0.05);
  const tGlobeExit = isGlobeOnly ? 3.95 : (tGlobeStart + 3.35); // ~9.85s in full_story_flow
  const isScene5Only = magnatesBPState.preset === 'article_capitol_zoom';
  const tScene5Start = isScene5Only ? 0.0 : 14.60; // Begins right after Scene 4 silhouettes exit
  const tInstantCut = tScene5Start + (magnatesBPState.articleHighlightSpeed ?? 0.75) + 0.35; // Instant hard cut
  const tScene5End = tInstantCut + (magnatesBPState.officeZoomOutDur ?? 1.40) + 0.50; // Full trackback complete

  // Seamless overlap (Image 5): $1,000,000 counter begins emerging at tGlobeExit + 0.15s (~10.00s) WHILE the globe is gliding down and "FOR ALMOST NOTHING." is fading!
  const sceneBOffset = isFullFlow
    ? (hasGlobePhase ? (tGlobeExit + 0.15) : (hasProductsPhase ? 7.20 : 4.50))
    : 0.0;

  const sceneNumLabel = isFullFlow
    ? (p < tShiftRight ? 'Scene 1' : (p < tGlobeStart ? 'Scene 2' : (p < sceneBOffset ? 'Scene 3' : (p < tScene5Start ? 'Scene 4' : 'Scene 5'))))
    : (isBrandOnly ? 'Scene 1' : (isProductsOnly ? 'Scene 2' : (isGlobeOnly ? 'Scene 3' : (isScene5Only ? 'Scene 5' : 'Scene 4'))));
  const timeText = `${p.toFixed(1)}s / ${dur.toFixed(1)}s (${sceneNumLabel})`;
  if (timerEl) timerEl.textContent = timeText;
  if (hudTimecode) hudTimecode.textContent = `${p.toFixed(2)}s / ${dur.toFixed(1)}s`;
  if (scrubberFill) scrubberFill.style.width = `${Math.max(0, Math.min(100, (p / dur) * 100)).toFixed(1)}%`;

  // Sync Cutout & Logo Image Sources & Inspector Thumbnails
  if (logoImg && logoImg.getAttribute('src') !== magnatesBPState.logoCutoutUrl) {
    logoImg.src = magnatesBPState.logoCutoutUrl;
  }
  const thumbZ4 = document.getElementById('magnates-bp-thumb-z4');
  if (thumbZ4 && thumbZ4.getAttribute('src') !== magnatesBPState.logoCutoutUrl) {
    thumbZ4.src = magnatesBPState.logoCutoutUrl;
  }
  if (secondaryImg && secondaryImg.getAttribute('src') !== magnatesBPState.secondaryCutoutUrl) {
    secondaryImg.src = magnatesBPState.secondaryCutoutUrl;
  }
  if (primaryImg && primaryImg.getAttribute('src') !== magnatesBPState.primaryCutoutUrl) {
    primaryImg.src = magnatesBPState.primaryCutoutUrl;
  }
  const thumbZ2 = document.getElementById('magnates-bp-thumb-z2');
  if (thumbZ2 && thumbZ2.getAttribute('src') !== magnatesBPState.secondaryCutoutUrl) {
    thumbZ2.src = magnatesBPState.secondaryCutoutUrl;
  }
  const thumbZ3 = document.getElementById('magnates-bp-thumb-z3');
  if (thumbZ3 && thumbZ3.getAttribute('src') !== magnatesBPState.primaryCutoutUrl) {
    thumbZ3.src = magnatesBPState.primaryCutoutUrl;
  }

  const effectiveBgFadeTime = isFullFlow
    ? (sceneBOffset + magnatesBPState.bgFadeTime)
    : magnatesBPState.bgFadeTime;

  // Z=0 Background Plate vs Radial Glow Atmosphere + Fade-out at end
  const hasBgPlate = Boolean(magnatesBPState.bgPlateUrl);
  const bgColor = magnatesBPState.backdropColor || '#991b1b';
  const bgSpread = magnatesBPState.backdropSpread || 75;

  if (crimsonBg) {
    crimsonBg.style.display = hasBgPlate ? 'none' : 'block';
    if (!hasBgPlate) {
      const c1 = bpHexToRgba(bgColor, 0.88);
      const c2 = bpHexToRgba(bgColor, 0.62);
      const c3 = bpHexToRgba(bgColor, 0.25);
      crimsonBg.style.background = `radial-gradient(circle at 20% 25%, ${c1} 0%, ${c2} ${Math.round(bgSpread * 0.45)}%, ${c3} ${bgSpread}%, #070101 100%)`;
    }
  }

  const thumbZ0 = document.getElementById('magnates-bp-thumb-z0');
  if (thumbZ0) {
    if (hasBgPlate) {
      thumbZ0.style.backgroundImage = `url(${magnatesBPState.bgPlateUrl})`;
      thumbZ0.style.backgroundSize = 'cover';
      thumbZ0.style.backgroundPosition = 'center';
    } else {
      thumbZ0.style.backgroundImage = 'none';
      thumbZ0.style.background = `radial-gradient(circle, ${bgColor}, #090101)`;
    }
  }

  if (bgPlateImg) {
    if (hasBgPlate) {
      bgPlateImg.style.display = 'block';
      if (bgPlateImg.getAttribute('src') !== magnatesBPState.bgPlateUrl) {
        bgPlateImg.src = magnatesBPState.bgPlateUrl;
      }
    } else {
      bgPlateImg.style.display = 'none';
    }
  }
  if (gridLayer) {
    gridLayer.style.opacity = magnatesBPState.showBlueprintGrid ? '0.65' : '0';
  }

  let bgOpacity = 1;
  const hasScene5Active = (isFullFlow || isScene5Only) && magnatesBPState.scene5Enabled !== false;
  if (isScene5Only) {
    bgOpacity = 1;
  } else if (hasScene5Active && p >= tScene5Start) {
    // Scene 5 Phase 1 restores the signature Crimson Radial Atmosphere right after Scene 4's brief dip
    const restoreP = bpEaseOutCubic(Math.min(1, Math.max(0, (p - tScene5Start) / 0.30)));
    bgOpacity = restoreP;
  } else if (p >= effectiveBgFadeTime) {
    const fadeQ = bpEaseInCubic((p - effectiveBgFadeTime) / 0.45);
    bgOpacity = Math.max(0, 1 - fadeQ);
  }
  if (bgWrap) bgWrap.style.opacity = bgOpacity.toFixed(3);

  // =========================================================
  // SCENE A1 & A2 RENDER:
  // A1: Brand Logo Cutout (Z=4) rises bottom->center, shifts left + Wavy Headline (Z=5)
  // A2: Brand Logo shifts right back to center (covering/wiping wavy text) ->
  //     Left Product Card unfurls Top&Bottom -> Left Price ($2.00) unfurls Left&Right ->
  //     Right Product Card unfurls Top&Bottom -> Right Price ($5.00) unfurls Left&Right
  // =========================================================
  const showSceneA = magnatesBPState.logoEnabled && (isFullFlow || isBrandOnly || isProductsOnly || isGlobeOnly);
  const tIn = (isProductsOnly || isGlobeOnly) ? -1.0 : (magnatesBPState.logoInTime ?? 0.35);
  const tShift = (isProductsOnly || isGlobeOnly) ? -0.8 : (magnatesBPState.logoShiftTime ?? 1.25);

  if (logoLayer && logoImg) {
    if (!showSceneA) {
      logoLayer.style.display = 'none';
    } else {
      logoLayer.style.display = 'flex';
      logoImg.style.filter = bpComputeCutoutGlowFilter(
        magnatesBPState.logoGlowColor || '#ff1e1e',
        magnatesBPState.logoGlowIntensity ?? 90,
        false
      );

      // 1. Bottom -> Center Rise (e.g. 0.35s to 0.83s)
      const riseProg = bpEaseOutCubic((p - tIn) / 0.48);
      // 2. Center -> Left Shift (e.g. 1.25s to 1.75s)
      const shiftLeftProg = bpEaseInOutCubic((p - tShift) / 0.50);
      // 3. Left -> Right back to Center (Image 1 -> Image 2: e.g. 3.10s to 3.62s)
      const shiftRightToCenterProg = hasProductsPhase ? bpEaseInOutCubic((p - tShiftRight) / 0.52) : 0;
      // 4. Final Exit at end of Scene 2 (at tOut): Moves UPWARD as a whole with the product cards & price tags (Image 1)!
      const exitProg = p >= tOut ? bpEaseInOutCubic((p - tOut) / 0.58) : 0;

      // Net left offset: 0 at center, 1 when shifted left, returns to 0 when shifted right back to center!
      const netLeftFactor = shiftLeftProg * (1 - shiftRightToCenterProg);
      const baseTx = -50 - netLeftFactor * 136;
      const baseTy = -50 + (1 - riseProg) * 185 - exitProg * 235;
      const op = Math.max(0, Math.min(1, (p < tIn ? 0 : riseProg * 1.35) * (1 - Math.pow(exitProg, 1.4) * 1.15)));

      logoLayer.style.transform = `translate3d(${baseTx.toFixed(2)}%, ${baseTy.toFixed(2)}%, 0)`;
      logoLayer.style.opacity = op.toFixed(3);
    }
  }

  if (wavyWrap) {
    if (!showSceneA || !magnatesBPState.wavyTextEnabled) {
      wavyWrap.style.display = 'none';
    } else {
      wavyWrap.style.display = 'flex';
      const line1Start = tShift + 0.15;
      const line2Start = tShift + 0.68;

      const prog1 = Math.max(0, Math.min(1, (p - line1Start) / 0.55));
      const prog2 = Math.max(0, Math.min(1, (p - line2Start) / 0.72));

      // As the TEMU logo moves right across the text (Image 1), it covers the left side of the text and wipes/fades it out cleanly by the time the logo stops in the center (Image 2)!
      const textCoverProg = hasProductsPhase
        ? bpEaseInOutCubic((p - tShiftRight) / 0.46)
        : (p >= tOut ? bpEaseInCubic((p - tOut) / 0.40) : 0);

      renderWavyKineticSpans(wavyLine1El, magnatesBPState.wavyLine1 || '', prog1, false);
      renderWavyKineticSpans(wavyLine2El, magnatesBPState.wavyLine2 || '', prog2, true);

      // Progressive left-to-right clip wipe as the logo passes over the text + fade out
      const clipLeft = (textCoverProg * 65).toFixed(1);
      wavyWrap.style.clipPath = textCoverProg > 0.01 ? `inset(0% 0% 0% ${clipLeft}%)` : 'none';
      const wrapOp = Math.max(0, 1 - Math.pow(textCoverProg, 1.5) * 1.25) * bgOpacity;
      wavyWrap.style.opacity = wrapOp.toFixed(3);
      wavyWrap.style.transform = `translate3d(0px, -50%, 0)`;
    }
  }

  // Render Z=6 (Left Product + Concentric Shapes + Veil + $2.00 Tag) & Z=7 (Right Product + Concentric Shapes + Veil + $5.00 Tag)
  const prod1Layer = document.getElementById('magnates-bp-layer-prod1');
  const prod1Card = document.getElementById('magnates-bp-prod1-card');
  const prod1Inner = document.getElementById('magnates-bp-prod1-inner-shape');
  const prod1Veil = document.getElementById('magnates-bp-prod1-veil');
  const prod1Img = document.getElementById('magnates-bp-img-prod1');
  const prod1Pill = document.getElementById('magnates-bp-prod1-price-pill');
  const prod1Txt = document.getElementById('magnates-bp-prod1-price-text');

  const prod2Layer = document.getElementById('magnates-bp-layer-prod2');
  const prod2Card = document.getElementById('magnates-bp-prod2-card');
  const prod2Inner = document.getElementById('magnates-bp-prod2-inner-shape');
  const prod2Veil = document.getElementById('magnates-bp-prod2-veil');
  const prod2Img = document.getElementById('magnates-bp-img-prod2');
  const prod2Pill = document.getElementById('magnates-bp-prod2-price-pill');
  const prod2Txt = document.getElementById('magnates-bp-prod2-price-text');

  if (prod1Img && prod1Img.getAttribute('src') !== magnatesBPState.prod1Url) prod1Img.src = magnatesBPState.prod1Url;
  if (prod2Img && prod2Img.getAttribute('src') !== magnatesBPState.prod2Url) prod2Img.src = magnatesBPState.prod2Url;
  const thumbZ6 = document.getElementById('magnates-bp-thumb-z6');
  if (thumbZ6 && thumbZ6.getAttribute('src') !== magnatesBPState.prod1Url) thumbZ6.src = magnatesBPState.prod1Url;
  const thumbZ7 = document.getElementById('magnates-bp-thumb-z7');
  if (thumbZ7 && thumbZ7.getAttribute('src') !== magnatesBPState.prod2Url) thumbZ7.src = magnatesBPState.prod2Url;
  if (prod1Txt) prod1Txt.textContent = magnatesBPState.prod1Price || '$2.00';
  if (prod2Txt) prod2Txt.textContent = magnatesBPState.prod2Price || '$5.00';

  // Apply Concentric Backing Shapes (Shape 1 Outer Frame + Shape 2 Inner Plate + Rim Glow)
  const hasOuterShape = magnatesBPState.prodShapeOuterEnabled !== false;
  const hasInnerShape = magnatesBPState.prodShapeInnerEnabled !== false;
  const outerCol = magnatesBPState.prodOuterColor || '#5a0001';
  const innerCol = magnatesBPState.prodInnerColor || '#800001';
  const shapeInset = magnatesBPState.prodShapeInset ?? 7;
  const cardGlowVal = magnatesBPState.prodCardGlow ?? 45;
  const glowRadius = Math.round((cardGlowVal / 100) * 32);
  const glowAlpha = ((cardGlowVal / 100) * 0.55).toFixed(2);
  const cardShadow = cardGlowVal > 0
    ? `0 12px 28px rgba(0,0,0,0.8), 0 0 ${glowRadius}px ${bpHexToRgba(innerCol, parseFloat(glowAlpha))}, inset 0 0 1px 1px rgba(255, 60, 60, 0.18)`
    : '0 12px 28px rgba(0,0,0,0.8)';

  [prod1Card, prod2Card].forEach((cEl) => {
    if (cEl) {
      cEl.style.background = hasOuterShape ? outerCol : 'transparent';
      cEl.style.padding = `${shapeInset}%`;
      cEl.style.boxShadow = hasOuterShape ? cardShadow : 'none';
    }
  });
  [prod1Inner, prod2Inner].forEach((inEl) => {
    if (inEl) {
      inEl.style.background = hasInnerShape ? innerCol : 'transparent';
      inEl.style.boxShadow = hasInnerShape ? 'inset 0 0 18px rgba(0,0,0,0.35)' : 'none';
    }
  });

  // Apply Per-Item Brightness & Top Color Veil Layer (Left iPhone veiled/blended vs Right Air Fryer untouched)
  const veilCol = magnatesBPState.prodVeilColor || '#990000';
  const veil1Op = (magnatesBPState.prod1VeilOp ?? 32) / 100;
  const veil2Op = (magnatesBPState.prod2VeilOp ?? 0) / 100;
  const b1 = (magnatesBPState.prod1Bright ?? 88) / 100;
  const b2 = (magnatesBPState.prod2Bright ?? 105) / 100;
  if (prod1Veil) {
    prod1Veil.style.background = veilCol;
    prod1Veil.style.opacity = veil1Op.toFixed(2);
  }
  if (prod2Veil) {
    prod2Veil.style.background = veilCol;
    prod2Veil.style.opacity = veil2Op.toFixed(2);
  }
  if (prod1Img) {
    // Also apply subtle sepia/red tint when veil1Op > 0 so the left object blends seamlessly into the crimson card like Screenshot 3
    prod1Img.style.filter = `brightness(${b1.toFixed(2)}) contrast(1.06) drop-shadow(0 8px 18px rgba(0,0,0,0.55))`;
    prod1Img.style.opacity = (1.0 - veil1Op * 0.28).toFixed(2);
  }
  if (prod2Img) {
    prod2Img.style.filter = `brightness(${b2.toFixed(2)}) contrast(1.06) drop-shadow(0 8px 18px rgba(0,0,0,0.55))`;
    prod2Img.style.opacity = (1.0 - veil2Op * 0.28).toFixed(2);
  }

  const showProducts = showSceneA && hasProductsPhase && p >= (tShiftRight + 0.35) && p < (tOut + 0.65);
  // At tOut, the entire product card + price tag assembly glides UPWARD as a whole (Image 1 shows the bottom of the red cards & $2.00 / $5.00 tags rising off the top edge!)
  const prodMoveUpProg = p >= tOut ? bpEaseInOutCubic((p - tOut) / 0.58) : 0;
  const prodWholeTy = -prodMoveUpProg * 125; // % of layer height upward
  const prodWholeOp = Math.max(0, 1 - Math.pow(prodMoveUpProg, 1.65) * 1.15);

  // Timing milestones matching Images 2, 3, 4, 5:
  const tProd1CardStart = tShiftRight + 0.50;
  const tProd1PriceStart = tProd1CardStart + unfurlDur + 0.12;
  const tProd2CardStart = tProd1PriceStart + unfurlDur + 0.18;
  const tProd2PriceStart = tProd2CardStart + unfurlDur + 0.12;

  if (prod1Layer && prod1Card && prod1Pill) {
    if (!showProducts) {
      prod1Layer.style.display = 'none';
    } else {
      prod1Layer.style.display = 'flex';
      prod1Layer.style.transform = `translate3d(0%, ${prodWholeTy.toFixed(2)}%, 0)`;
      prod1Layer.style.opacity = prodWholeOp.toFixed(3);

      const c1Prog = bpEaseOutCubic((p - tProd1CardStart) / unfurlDur);
      const vInset1 = ((1 - c1Prog) * 50).toFixed(2);
      prod1Card.style.clipPath = `inset(${vInset1}% 0% ${vInset1}% 0% round 22px)`;
      prod1Card.style.opacity = Math.min(1, c1Prog * 1.8).toFixed(3);

      const p1Prog = bpEaseOutCubic((p - tProd1PriceStart) / (unfurlDur * 0.88));
      const hInset1 = ((1 - p1Prog) * 50).toFixed(2);
      prod1Pill.style.clipPath = `inset(0% ${hInset1}% 0% ${hInset1}% round 999px)`;
      prod1Pill.style.opacity = Math.min(1, p1Prog * 1.8).toFixed(3);
    }
  }

  if (prod2Layer && prod2Card && prod2Pill) {
    if (!showProducts) {
      prod2Layer.style.display = 'none';
    } else {
      prod2Layer.style.display = 'flex';
      prod2Layer.style.transform = `translate3d(0%, ${prodWholeTy.toFixed(2)}%, 0)`;
      prod2Layer.style.opacity = prodWholeOp.toFixed(3);

      const c2Prog = bpEaseOutCubic((p - tProd2CardStart) / unfurlDur);
      const vInset2 = ((1 - c2Prog) * 50).toFixed(2);
      prod2Card.style.clipPath = `inset(${vInset2}% 0% ${vInset2}% 0% round 22px)`;
      prod2Card.style.opacity = Math.min(1, c2Prog * 1.8).toFixed(3);

      const p2Prog = bpEaseOutCubic((p - tProd2PriceStart) / (unfurlDur * 0.88));
      const hInset2 = ((1 - p2Prog) * 50).toFixed(2);
      prod2Pill.style.clipPath = `inset(0% ${hInset2}% 0% ${hInset2}% round 999px)`;
      prod2Pill.style.opacity = Math.min(1, p2Prog * 1.8).toFixed(3);
    }
  }

  // =========================================================
  // SCENE 3 RENDER: Spinning Earth Globe (Z=8) & Wavy-to-Flat Headline "FOR ALMOST NOTHING." (Z=9)
  // =========================================================
  const globeLayer = document.getElementById('magnates-bp-layer-globe');
  const globeImg = document.getElementById('magnates-bp-img-globe');
  const globeTextLayer = document.getElementById('magnates-bp-layer-globe-text');
  const globeHeadlineEl = document.getElementById('magnates-bp-globe-headline');

  if (globeImg && globeImg.getAttribute('src') !== (magnatesBPState.globeUrl || '/globe_atlantic_clean.svg')) {
    globeImg.src = magnatesBPState.globeUrl || '/globe_atlantic_clean.svg';
  }
  const thumbZ8 = document.getElementById('magnates-bp-thumb-z8');
  if (thumbZ8 && thumbZ8.getAttribute('src') !== (magnatesBPState.globeUrl || '/globe_atlantic_clean.svg')) {
    thumbZ8.src = magnatesBPState.globeUrl || '/globe_atlantic_clean.svg';
  }

  const showGlobeScene = hasGlobePhase && p >= (tGlobeStart - 0.05) && p < (tGlobeExit + 0.70);
  if (globeLayer && globeImg) {
    if (!showGlobeScene) {
      globeLayer.style.display = 'none';
    } else {
      globeLayer.style.display = 'flex';
      // 1) Glides in from bottom -> up (tGlobeStart to tGlobeStart + 0.58s, matching Image 1)
      // Resting position: top: 50.5% with translateY(0%) places apex exactly at 50.5% of stage height,
      // perfectly below the headline at top: 38.5% with dark negative space breathing room (Image 2)
      const gRiseProg = bpEaseOutCubic((p - tGlobeStart) / 0.58);
      // 2) Exits from its location -> down (tGlobeExit to tGlobeExit + 0.62s, matching Image 5)
      const gExitDownProg = p >= tGlobeExit ? bpEaseInCubic((p - tGlobeExit) / 0.62) : 0;

      const gy = (1 - gRiseProg) * 58 + gExitDownProg * 65;
      const gOp = Math.max(0, Math.min(1, gRiseProg * 1.45) * (1 - gExitDownProg * 1.1));
      globeLayer.style.transform = `translate3d(-50%, ${gy.toFixed(2)}%, 0)`;
      globeLayer.style.opacity = gOp.toFixed(3);

      // Continuous spin in the direction indicated in Image 2 (Left->Right clockwise arc at top of globe)
      const spinDegPerSec = magnatesBPState.globeSpinSpeed ?? 18;
      const spinSign = (magnatesBPState.globeSpinDir || 'cw') === 'ccw' ? -1 : 1;
      const elapsedGlobe = Math.max(0, p - tGlobeStart);
      const currentDeg = elapsedGlobe * spinDegPerSec * spinSign;
      globeImg.style.transform = `rotate(${currentDeg.toFixed(2)}deg)`;
    }
  }

  if (globeTextLayer && globeHeadlineEl) {
    const tGlobeTextStart = tGlobeStart + 0.55;
    const showGlobeText = showGlobeScene && p >= tGlobeTextStart;
    if (!showGlobeText) {
      globeTextLayer.style.display = 'none';
    } else {
      globeTextLayer.style.display = 'flex';
      const elapsedText = p - tGlobeTextStart;
      renderGlobeWavyHeadlineSpans(globeHeadlineEl, magnatesBPState.globeHeadline || 'FOR ALMOST NOTHING.', elapsedText);
      // As the globe glides down (tGlobeExit), "FOR ALMOST NOTHING." stays flat briefly so it overlaps with the emerging $999,655 counter (Image 5!) before fading out
      const textFadeOut = p >= (tGlobeExit + 0.22) ? bpEaseInCubic((p - (tGlobeExit + 0.22)) / 0.42) : 0;
      globeTextLayer.style.opacity = (Math.max(0, 1 - textFadeOut) * bgOpacity).toFixed(3);
      globeTextLayer.style.transform = 'translate3d(0px, -50%, 0)';
    }
  }

  // =========================================================
  // SCENE 5 RENDER: Centered Transparent Article, Red Highlight, Pristine Capitol Rise & Office Zoom-Out (Z=10, Z=11, Z=12)
  // =========================================================
  const officeLayer = document.getElementById('magnates-bp-layer-office');
  const officeImg = document.getElementById('magnates-bp-img-office');
  const articleLayer = document.getElementById('magnates-bp-layer-article');
  const articleLiveWrap = document.getElementById('magnates-bp-article-live-wrap');
  const articleShotWrap = document.getElementById('magnates-bp-article-screenshot-wrap');
  const articleShotImg = document.getElementById('magnates-bp-article-screenshot-img');
  const articleShotHl = document.getElementById('magnates-bp-article-screenshot-hl');
  const articleHl = document.getElementById('magnates-bp-article-highlight');
  const articleKickerEl = document.getElementById('magnates-bp-article-kicker');
  const articleLine1 = document.getElementById('magnates-bp-article-line1');
  const articleLine2 = document.getElementById('magnates-bp-article-line2');
  const articleSubEl = document.getElementById('magnates-bp-article-sub');
  const articleBodyEl = document.getElementById('magnates-bp-article-body');
  const capitolLayer = document.getElementById('magnates-bp-layer-capitol');
  const capitolImg = document.getElementById('magnates-bp-img-capitol');

  if (officeImg && officeImg.getAttribute('src') !== (magnatesBPState.officePhotoUrl || '/temu_boardroom_office.png')) {
    officeImg.src = magnatesBPState.officePhotoUrl || '/temu_boardroom_office.png';
  }
  if (capitolImg && capitolImg.getAttribute('src') !== (magnatesBPState.capitolCutoutUrl || '/capitol_dome_cutout.png')) {
    capitolImg.src = magnatesBPState.capitolCutoutUrl || '/capitol_dome_cutout.png';
  }
  const thumbZ12 = document.getElementById('magnates-bp-thumb-z12');
  if (thumbZ12 && thumbZ12.getAttribute('src') !== (magnatesBPState.officePhotoUrl || '/temu_boardroom_office.png')) {
    thumbZ12.src = magnatesBPState.officePhotoUrl || '/temu_boardroom_office.png';
  }
  const thumbZ11 = document.getElementById('magnates-bp-thumb-z11');
  if (thumbZ11 && thumbZ11.getAttribute('src') !== (magnatesBPState.capitolCutoutUrl || '/capitol_dome_cutout.png')) {
    thumbZ11.src = magnatesBPState.capitolCutoutUrl || '/capitol_dome_cutout.png';
  }

  // Sync live editable text elements unless the user is actively typing inside them on stage
  if (articleKickerEl && document.activeElement !== articleKickerEl) {
    articleKickerEl.textContent = magnatesBPState.articleKicker ?? 'Global Business';
  }
  if (articleLine1 && document.activeElement !== articleLine1) {
    articleLine1.textContent = magnatesBPState.articleLine1 ?? 'Temu Emerges as the Biggest';
  }
  if (articleLine2 && document.activeElement !== articleLine2) {
    articleLine2.textContent = magnatesBPState.articleLine2 ?? 'Shopping App in the U.S.';
  }
  if (articleSubEl && document.activeElement !== articleSubEl) {
    articleSubEl.textContent = magnatesBPState.articleSub ?? 'Affordable prices, a vast product range and a seamless shopping experience helped Temu rise to the top of the U.S. shopping app market.';
  }
  if (articleBodyEl && document.activeElement !== articleBodyEl) {
    articleBodyEl.textContent = magnatesBPState.articleBody ?? 'Temu, the Chinese e-commerce platform, has quickly become the most popular shopping app in the United States, surpassing long-established rivals with its combination of low prices, a massive product selection and a smooth, app-first shopping experience. What began as a relatively unknown platform has, in just a few years, grown into a household name for millions of American consumers looking for value and convenience.';
  }

  const showScene5 = (isFullFlow || isScene5Only) && magnatesBPState.scene5Enabled !== false && p >= tScene5Start;

  if (!showScene5) {
    if (officeLayer) officeLayer.style.display = 'none';
    if (articleLayer) articleLayer.style.display = 'none';
    if (capitolLayer) capitolLayer.style.display = 'none';
  } else {
    // Phase 1 vs Phase 2: Instant hard cut at tInstantCut (no crossfade!)
    const isPhase1 = p < tInstantCut;
    const hlSpeed = magnatesBPState.articleHighlightSpeed ?? 0.85;
    const hlCol = magnatesBPState.articleHighlightColor || '#b91c1c';
    const hlOp = (magnatesBPState.articleHighlightOpacity ?? 88) / 100;
    const hlBg = bpHexToRgba(hlCol, hlOp);
    // Highlight starts sweeping at tScene5Start + 0.12s and completes right after Capitol reaches its peak!
    const hlProg = bpEaseInOutCubic(Math.max(0, Math.min(1, (p - (tScene5Start + 0.12)) / hlSpeed)));

    // 1. Centered Transparent Article Headline & Kinetic Red Marker Highlight (Phase 1 Only)
    if (articleLayer) {
      if (!isPhase1) {
        articleLayer.style.display = 'none';
      } else {
        articleLayer.style.display = 'flex';
        const fontScale = (magnatesBPState.articleFontScale ?? 100) / 100;
        const artInP = bpEaseOutCubic(Math.min(1, Math.max(0, (p - tScene5Start) / 0.28)));
        articleLayer.style.opacity = artInP.toFixed(3);
        articleLayer.style.transform = `translate3d(-50%, 0, 0) scale(${fontScale.toFixed(3)})`;
        articleLayer.style.transformOrigin = 'top center';

        const useScreenshotMode = magnatesBPState.articleMode === 'screenshot' && Boolean(magnatesBPState.customScreenshotUrl);
        if (articleLiveWrap) articleLiveWrap.style.display = useScreenshotMode ? 'none' : 'flex';
        if (articleShotWrap) {
          articleShotWrap.style.display = useScreenshotMode ? 'flex' : 'none';
          if (useScreenshotMode && articleShotImg && articleShotImg.getAttribute('src') !== magnatesBPState.customScreenshotUrl) {
            articleShotImg.src = magnatesBPState.customScreenshotUrl;
          }
          if (articleShotHl) {
            articleShotHl.style.width = `${(hlProg * 92).toFixed(1)}%`;
            articleShotHl.style.background = hlBg;
          }
        }
        if (articleHl) {
          articleHl.style.width = `${(hlProg * 102).toFixed(1)}%`;
          articleHl.style.background = hlBg;
        }
      }
    }

    // 2. Office Photo: Appears INSTANTLY at tInstantCut, starts tightly zoomed in on presenter's face/glasses (scale 3.15x, origin 29.5% 15.5% matching Image 3), tracks back to 1.0x wide angle (Image 4)
    if (officeLayer && officeImg) {
      if (isPhase1) {
        officeLayer.style.display = 'none';
      } else {
        officeLayer.style.display = 'block';
        const zoomDur = magnatesBPState.officeZoomOutDur ?? 1.45;
        const zProg = bpEaseInOutCubic(Math.min(1, Math.max(0, (p - tInstantCut) / zoomDur)));
        const currentScale = 3.15 - zProg * 2.15; // 3.15 -> 1.00
        officeImg.style.transformOrigin = '29.5% 15.5%';
        officeImg.style.transform = `scale(${currentScale.toFixed(4)})`;
      }
    }

    // 3. Pristine Capitol Building Cutout:
    // Rises from bottom->up during Phase 1 slightly before the highlight finishes so its statue tip reaches between "in" and "the" on Line 2 (Image 2),
    // then the highlight finishes passing over the dot ".",
    // then on the instant cut (Phase 2) the Capitol stays at its exact peak and simultaneously glides down out of the frame while the office zooms out!
    if (capitolLayer) {
      capitolLayer.style.display = 'flex';
      const apexPct = magnatesBPState.capitolApexY ?? 82;
      capitolLayer.style.height = `${apexPct}%`;
      if (isPhase1) {
        // Capitol reaches peak slightly before highlight finishes (hlSpeed * 0.82)
        const riseDur = Math.max(0.35, hlSpeed * 0.82);
        const riseP = bpEaseOutCubic(Math.min(1, Math.max(0, (p - (tScene5Start + 0.08)) / riseDur)));
        const ty = (1 - riseP) * 108;
        capitolLayer.style.transform = `translate3d(0, ${ty.toFixed(2)}%, 0)`;
        capitolLayer.style.opacity = Math.min(1, riseP * 1.6).toFixed(3);
      } else {
        const exitDur = magnatesBPState.officeZoomOutDur ?? 1.45;
        const exitP = bpEaseInOutCubic(Math.min(1, Math.max(0, (p - tInstantCut) / (exitDur * 0.92))));
        const ty = exitP * 112;
        capitolLayer.style.transform = `translate3d(0, ${ty.toFixed(2)}%, 0)`;
        capitolLayer.style.opacity = (exitP >= 0.98 ? 0 : 1).toFixed(3);
      }
    }
  }

  // SCENE B / C RENDER: $1,000,000 Counter (Z=1) & Cutouts (Z=2, Z=3)
  // =========================================================
  const localPB = p - sceneBOffset;
  const inSceneBWindow = !isBrandOnly && !isProductsOnly && !isGlobeOnly && !isScene5Only && (!isFullFlow || (localPB >= 0 && p < tScene5Start));

  if (textWrap) {
    if (!magnatesBPState.showCounter || !inSceneBWindow) {
      textWrap.style.display = 'none';
    } else {
      textWrap.style.display = 'flex';
      const rawHead = (magnatesBPState.headline || '').trim();
      if (headlineEl) {
        if (rawHead.startsWith('$')) {
          const targetNum = parseInt(rawHead.replace(/[^0-9]/g, ''), 10) || 1000000;
          const countDur = Math.max(0.4, magnatesBPState.l2InTime + 0.20);
          let currentVal = targetNum;
          if (localPB < countDur) {
            const cProg = bpEaseOutCubic(localPB / countDur);
            currentVal = Math.floor(targetNum * (0.82 + 0.18 * cProg));
          }
          headlineEl.textContent = '$' + currentVal.toLocaleString('en-US');
        } else {
          headlineEl.textContent = rawHead;
        }
      }
      if (subcaptionEl) subcaptionEl.textContent = magnatesBPState.subcaption;
      const textEnter = bpEaseOutCubic(localPB / 0.35);
      textWrap.style.opacity = (textEnter * bgOpacity).toFixed(3);
    }
  }

  // Z=2 Layer 1 Layout & Motion (Left Standing Silhouette OR Full-Frame Office Desk Cutout)
  if (secondaryLayer && secondaryImg) {
    if (!magnatesBPState.l1Enabled || !inSceneBWindow) {
      secondaryLayer.style.display = 'none';
    } else {
      secondaryLayer.style.display = 'flex';
      if (isRoomScene && magnatesBPState.secondaryCutoutUrl.includes('laptop_guy_cutout')) {
        secondaryLayer.style.inset = '0';
        secondaryLayer.style.left = '0';
        secondaryLayer.style.bottom = '0';
        secondaryLayer.style.width = '100%';
        secondaryLayer.style.height = '100%';
        secondaryImg.style.width = '100%';
        secondaryImg.style.height = '100%';
        secondaryImg.style.objectFit = 'cover';
        secondaryImg.style.filter = bpComputeCutoutGlowFilter(magnatesBPState.l1GlowColor || '#ffffff', magnatesBPState.l1GlowIntensity ?? 0, true);
      } else {
        secondaryLayer.style.inset = 'auto';
        secondaryLayer.style.left = '5%';
        secondaryLayer.style.bottom = '2%';
        secondaryLayer.style.width = 'auto';
        secondaryLayer.style.height = '83%';
        secondaryImg.style.width = 'auto';
        secondaryImg.style.height = '100%';
        secondaryImg.style.objectFit = 'contain';
        secondaryImg.style.filter = bpComputeCutoutGlowFilter(magnatesBPState.l1GlowColor || '#ffffff', magnatesBPState.l1GlowIntensity ?? 85, false);
      }

      const m1 = computeGranularCutoutTransform(
        localPB,
        magnatesBPState.l1InTime,
        magnatesBPState.l1OutTime,
        magnatesBPState.l1InAnim,
        magnatesBPState.l1OutAnim
      );
      secondaryLayer.style.transform = m1.transform;
      secondaryLayer.style.opacity = m1.opacity;
    }
  }

  // Z=3 Layer 2 Layout & Motion (Right Sitting Silhouette)
  if (primaryLayer && primaryImg) {
    if (!magnatesBPState.l2Enabled || !inSceneBWindow) {
      primaryLayer.style.display = 'none';
    } else {
      primaryLayer.style.display = 'flex';
      primaryLayer.style.right = '0%';
      primaryLayer.style.bottom = '0%';
      primaryLayer.style.height = '61%';
      primaryImg.style.filter = bpComputeCutoutGlowFilter(magnatesBPState.l2GlowColor || '#ffffff', magnatesBPState.l2GlowIntensity ?? 85, false);

      const m2 = computeGranularCutoutTransform(
        localPB,
        magnatesBPState.l2InTime,
        magnatesBPState.l2OutTime,
        magnatesBPState.l2InAnim,
        magnatesBPState.l2OutAnim
      );
      primaryLayer.style.transform = m2.transform;
      primaryLayer.style.opacity = m2.opacity;
    }
  }

  // Render Dynamic Extra User Cutout Layers (Added via + ADD LAYER)
  const extraStageWrap = document.getElementById('magnates-bp-extra-stage-layers');
  if (extraStageWrap && Array.isArray(magnatesBPState.extraCutouts)) {
    magnatesBPState.extraCutouts.forEach((ex) => {
      let el = extraStageWrap.querySelector(`[data-bp-layer="${ex.id}"]`);
      if (!el) {
        el = document.createElement('div');
        el.setAttribute('data-bp-layer', ex.id);
        el.style.cssText = 'position: absolute; bottom: 2%; transform: translateX(-50%); pointer-events: auto; cursor: pointer; display: flex; align-items: flex-end; justify-content: center;';
        const img = document.createElement('img');
        img.style.cssText = 'height: 100%; width: auto; object-fit: contain;';
        el.appendChild(img);
        el.addEventListener('mouseenter', () => highlightMagnatesBPLayerOnStage(ex.id));
        el.addEventListener('mouseleave', () => highlightMagnatesBPLayerOnStage(null));
        el.addEventListener('click', (ev) => {
          ev.stopPropagation();
          selectMagnatesBPLayer(ex.id);
        });
        extraStageWrap.appendChild(el);
      }
      const img = el.querySelector('img');
      if (img && img.getAttribute('src') !== ex.url) img.src = ex.url;
      el.style.display = ex.enabled === false ? 'none' : 'flex';
      el.style.left = `${ex.x ?? 50}%`;
      el.style.height = `${ex.scale ?? 55}%`;
      if (img) {
        img.style.filter = bpComputeCutoutGlowFilter(ex.glowColor || '#ffffff', ex.glowIntensity ?? 85, false);
      }
      const mEx = computeGranularCutoutTransform(
        inSceneBWindow ? localPB : p,
        ex.inTime ?? 0.6,
        ex.outTime ?? (dur - 0.8),
        ex.inAnim || 'bottom_to_up',
        ex.outAnim || 'fade_out'
      );
      el.style.transform = `translateX(-50%) ${mEx.transform}`;
      el.style.opacity = mEx.opacity;
    });
  }

  // Highlight active Storyboard Scene Card during playback
  document.querySelectorAll('.bp-storyboard-scene-card').forEach((card) => {
    const cType = card.getAttribute('data-scene-card');
    let isCardActive = false;
    if (magnatesBPState.preset === 'full_story_flow') {
      if (cType === 'brand_wavy_intro') isCardActive = p < tShiftRight;
      else if (cType === 'products_unfurl') isCardActive = p >= tShiftRight && p < tGlobeStart;
      else if (cType === 'globe_wavy_nothing') isCardActive = p >= tGlobeStart && p < sceneBOffset;
      else if (cType === 'dual_silhouette') isCardActive = p >= sceneBOffset && p < tScene5Start;
      else if (cType === 'article_capitol_zoom') isCardActive = p >= tScene5Start;
    } else if (magnatesBPState.preset === 'brand_wavy_intro') {
      if (cType === 'brand_wavy_intro') isCardActive = p < tShiftRight;
      else if (cType === 'products_unfurl') isCardActive = p >= tShiftRight;
    } else {
      isCardActive = magnatesBPState.preset === cType;
    }
    card.style.background = isCardActive ? 'rgba(168,85,247,0.16)' : 'rgba(255,255,255,0.03)';
    card.style.borderColor = isCardActive ? '#a855f7' : 'rgba(255,255,255,0.08)';
  });

  // Persist shared state so all 3 linked templates stay bidirectionally synchronized
  saveMagnatesBPSharedSyncState();

  // Update HUD Phase Indicator & Layer Stack Subtitles
  const presetDef = MAGNATES_BP_PRESETS[magnatesBPState.preset];
  if (hudPreset && presetDef) hudPreset.textContent = presetDef.hudPreset;

  let phaseText = "PHASE: INTRO BUILD";
  if (showSceneA && p < tOut + 0.35) {
    if (p < tIn) {
      phaseText = "SCENE 1 // 1. ATMOSPHERE BACKDROP";
    } else if (p < tShift) {
      phaseText = "SCENE 1 // 2. LOGO RISES TO CENTER";
    } else if (p < tShift + 0.65) {
      phaseText = "SCENE 1 // 3. SHIFT LEFT + LINE 1";
    } else if (!hasProductsPhase || p < tShiftRight) {
      phaseText = "SCENE 1 // 4. WAVY HEADLINE RISE";
    } else if (p < tProd1CardStart) {
      phaseText = "SCENE 2 // 1. LOGO SHIFTS RIGHT TO CENTER";
    } else if (p < tProd2CardStart) {
      phaseText = "SCENE 2 // 2. LEFT PRODUCT & $2.00 UNFURL";
    } else {
      phaseText = "SCENE 2 // 3. RIGHT PRODUCT & $5.00 UNFURL";
    }
  } else if (showScene5) {
    if (p < tInstantCut) {
      phaseText = "SCENE 5 // 1. TRANSPARENT ARTICLE HIGHLIGHT & CAPITOL RISE";
    } else {
      phaseText = "SCENE 5 // 2. INSTANT CUT → TEMU OFFICE ZOOM-OUT & CAPITOL DESCENT";
    }
  } else if (showGlobeScene) {
    if (p < tGlobeStart + 0.58) {
      phaseText = "SCENE 3 // 1. PRODUCTS GLIDE UP & GLOBE RISES";
    } else if (p < tGlobeStart + 1.70) {
      phaseText = "SCENE 3 // 2. GLOBE SPINS + WAVY WORDS REVEAL";
    } else if (p < tGlobeExit) {
      phaseText = "SCENE 3 // 3. HEADLINE FLATTENS + PERIOD SNAPS";
    } else {
      phaseText = "SCENE 3 // 4. GLOBE EXITS DOWN → $1M COUNTER";
    }
  } else {
    if (localPB < magnatesBPState.l1InTime) {
      phaseText = magnatesBPState.showCounter ? "SCENE B // 1. COUNTER BUILDING TO $1M" : "SCENE C // 1. EMPTY ROOM PLATE";
    } else if (localPB < magnatesBPState.l1OutTime) {
      phaseText = "SCENE B // 2. CUTOUTS GLIDE IN";
    } else if (localPB < magnatesBPState.bgFadeTime) {
      phaseText = "SCENE B // 3. STAGGERED CUTOUT EXITS";
    } else {
      phaseText = "SCENE B // 4. BACKDROP FADE TO BLACK";
    }
  }
  if (hudAnim) hudAnim.textContent = phaseText;

  const activeCount = 1
    + (showSceneA ? 1 : 0)
    + (showSceneA && magnatesBPState.wavyTextEnabled ? 1 : 0)
    + (!isBrandOnly && magnatesBPState.showCounter ? 1 : 0)
    + (!isBrandOnly && magnatesBPState.l1Enabled ? 1 : 0)
    + (!isBrandOnly && magnatesBPState.l2Enabled ? 1 : 0);
  if (activeLayerPill) activeLayerPill.textContent = `${activeCount} LAYERS ACTIVE`;
  if (layerCountBadge) layerCountBadge.textContent = `${activeCount} Stacked`;

  const subZ2 = document.getElementById('magnates-bp-sub-z2');
  if (subZ2) subZ2.textContent = bpFormatAnimLabel(magnatesBPState.l1InAnim, magnatesBPState.l1OutAnim);
  const subZ3 = document.getElementById('magnates-bp-sub-z3');
  if (subZ3) {
    subZ3.textContent = magnatesBPState.l2Enabled
      ? bpFormatAnimLabel(magnatesBPState.l2InAnim, magnatesBPState.l2OutAnim)
      : "Disabled in current scene";
  }
}

function syncMagnatesBPPlayButtons() {
  const btnPlay = document.getElementById('btn-magnates-bp-play-pause');
  const iconPause = document.getElementById('magnates-bp-hud-icon-pause');
  const iconPlay = document.getElementById('magnates-bp-hud-icon-play');
  if (magnatesBPState.isPlaying) {
    if (btnPlay) btnPlay.textContent = '⏸ Pause';
    if (iconPause) iconPause.style.display = 'block';
    if (iconPlay) iconPlay.style.display = 'none';
  } else {
    if (btnPlay) btnPlay.textContent = '▶ Play';
    if (iconPause) iconPause.style.display = 'none';
    if (iconPlay) iconPlay.style.display = 'block';
  }
}

function renderMagnatesBPLoop(timestamp) {
  if (!magnatesBPState.isPlaying) return;
  if (!magnatesBPState.lastTimestamp) magnatesBPState.lastTimestamp = timestamp;
  const dt = (timestamp - magnatesBPState.lastTimestamp) / 1000;
  magnatesBPState.lastTimestamp = timestamp;

  magnatesBPState.playhead += dt;
  if (magnatesBPState.playhead > magnatesBPState.duration) {
    magnatesBPState.playhead = 0;
  }

  updateMagnatesBPVisualStyles();
  magnatesBPState.animFrameId = requestAnimationFrame(renderMagnatesBPLoop);
}

const MAGNATES_BP_SYNC_STORAGE_KEY = 'magnates_bp_shared_sync_v1';
const MAGNATES_BP_SYNC_FIELDS = [
  'backdropColor', 'backdropSpread',
  'logoCutoutUrl', 'logoInTime', 'logoShiftTime', 'logoOutTime', 'logoGlowColor', 'logoGlowIntensity',
  'wavyLine1', 'wavyLine2',
  'productsEnabled', 'logoShiftRightTime', 'unfurlSpeed',
  'prodShapeOuterEnabled', 'prodShapeInnerEnabled', 'prodOuterColor', 'prodInnerColor', 'prodShapeInset', 'prodCardGlow',
  'prodVeilColor', 'prod1VeilOp', 'prod2VeilOp', 'prod1Bright', 'prod2Bright',
  'prod1Url', 'prod1Price', 'prod1GlowColor', 'prod1GlowIntensity',
  'prod2Url', 'prod2Price', 'prod2GlowColor', 'prod2GlowIntensity',
  'globeEnabled', 'globeUrl', 'globeHeadline', 'globeSpinSpeed', 'globeSpinDir',
  'scene5Enabled', 'articleMode', 'articleKicker', 'articleLine1', 'articleLine2', 'articleSub', 'articleBody', 'articleFontScale',
  'articleHighlightSpeed', 'articleHighlightColor', 'articleHighlightOpacity', 'articleRemoveBg', 'capitolApexY', 'officeZoomOutDur',
  'headline', 'subcaption',
  'l1InAnim', 'l1OutAnim', 'l1InTime', 'l1OutTime', 'l1GlowColor', 'l1GlowIntensity',
  'l2InAnim', 'l2OutAnim', 'l2InTime', 'l2OutTime', 'l2GlowColor', 'l2GlowIntensity',
  'bgFadeTime'
];

function saveMagnatesBPSharedSyncState() {
  try {
    const payload = {};
    MAGNATES_BP_SYNC_FIELDS.forEach((k) => {
      const val = magnatesBPState[k];
      // Avoid persisting temporary blob URLs across reloads, keep everything else
      if (typeof val === 'string' && val.startsWith('blob:')) return;
      payload[k] = val;
    });
    localStorage.setItem(MAGNATES_BP_SYNC_STORAGE_KEY, JSON.stringify(payload));
  } catch (err) {
    // Ignore storage quota errors
  }
}

function loadMagnatesBPSharedSyncState() {
  try {
    const raw = localStorage.getItem(MAGNATES_BP_SYNC_STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return;
    MAGNATES_BP_SYNC_FIELDS.forEach((k) => {
      if (parsed[k] !== undefined) {
        magnatesBPState[k] = parsed[k];
      }
    });
  } catch (err) {
    // Ignore parse errors
  }
}

